def _resolve_torch_scorer_device_alias(
    requested_device: str,
    *,
    torch_module: Any | None = None,
) -> str:
    """Resolve planner-level scorer device aliases to real PyTorch devices."""

    requested = str(requested_device or "cpu").strip().lower()
    if requested in {"cpu", "cuda", "mps"}:
        return requested
    if requested == "metal":
        return "mps"
    if requested != "gpu":
        raise CompactRendererMlxSpineRunnerError(f"unsupported scorer distillation device: {requested_device!r}")
    torch = torch_module
    if torch is None:
        try:
            import torch as torch  # type: ignore[no-redef]
        except Exception as exc:  # pragma: no cover - import failure is environment.
            raise CompactRendererMlxSpineRunnerError(
                "distillation_device='gpu' requires PyTorch to resolve a concrete scorer teacher device"
            ) from exc
    cuda = getattr(torch, "cuda", None)
    cuda_available = bool(getattr(cuda, "is_available", lambda: False)())
    if cuda_available:
        return "cuda"
    backends = getattr(torch, "backends", None)
    mps = getattr(backends, "mps", None)
    mps_available = bool(getattr(mps, "is_available", lambda: False)())
    if mps_available:
        return "mps"
    raise CompactRendererMlxSpineRunnerError(
        "distillation_device='gpu' requested, but neither torch.cuda nor torch.backends.mps is available"
    )


def _resolve_mlx_prefilter_scorer_device_alias(
    requested_device: str | None,
    *,
    fallback_device: str | None = None,
) -> str:
    """Resolve local MLX prefilter device aliases to MLX's cpu/gpu dialect."""

    raw = str(requested_device or "").strip().lower()
    if not raw:
        raw = str(fallback_device or "cpu").strip().lower()
    aliases = {
        "": "cpu",
        "cpu": "cpu",
        "gpu": "gpu",
        "mps": "gpu",
        "metal": "gpu",
        "mlx-gpu": "gpu",
        "cuda": "gpu",
    }
    if raw not in aliases:
        raise CompactRendererMlxSpineRunnerError(
            f"mlx prefilter scorer device must resolve to MLX 'cpu' or 'gpu'; got {requested_device!r}"
        )
    return aliases[raw]


def adapt_pr95_mlx_report_to_spine(
    *,
    pr95_mlx_report_path: str | Path,
    output_dir: str | Path,
    hard_byte_ceilings: tuple[int, ...] = DEFAULT_BASE_RENDERER_BYTE_CEILINGS,
    mlx_profile_paths: tuple[str | Path, ...] = (),
    hprc_queue_followup_report_paths: tuple[str | Path, ...] = (),
    allow_overwrite: bool = False,
    repo_root: str | Path = REPO_ROOT,
    upstream_dir: str | Path | None = None,
) -> dict[str, Any]:
    """Adapt the latest exported PR95 MLX checkpoint into the shared spine."""

    root = Path(repo_root).expanduser().resolve(strict=False)
    scorer_upstream = _resolve_scorer_upstream_dir(root, upstream_dir)
    out = Path(output_dir).expanduser().resolve(strict=False)
    if out.exists() and any(out.iterdir()) and not allow_overwrite:
        raise CompactRendererMlxSpineRunnerError(f"output dir is non-empty; pass --overwrite: {out}")
    out.mkdir(parents=True, exist_ok=True)
    report_path = _resolve(pr95_mlx_report_path, base=root)
    pr95_report = _load_json(report_path)
    checkpoint = _select_latest_exported_checkpoint(pr95_report, base=root)
    pt_path = _resolve_existing(checkpoint["pytorch_state_dict_path"], base=root)
    latents_path = _resolve_existing(checkpoint["latents_path"], base=root)
    export_manifest_path = _optional_existing(
        checkpoint.get("pytorch_export_manifest_path"),
        base=root,
    )
    projection_dir = out / "pr95_hnerv_spine"
    adapter_report = emit_compact_renderer_spine_adapter(
        family="pr95_hnerv",
        output_dir=projection_dir,
        decoder_blob=pt_path,
        latents_blob=latents_path,
        trained_weights_provenance=_trained_provenance(
            report_path=report_path,
            checkpoint=checkpoint,
            role="weights",
        ),
        trained_latents_provenance=_trained_provenance(
            report_path=report_path,
            checkpoint=checkpoint,
            role="latents",
        ),
        manifest_extra=_coverage_manifest_extra(pr95_report),
    )
    projection_manifest = Path(adapter_report["projection"]["manifest_path"])
    acquisition = build_spine_acquisition_report(
        projection_manifest_paths=[projection_manifest],
        hard_byte_ceilings=hard_byte_ceilings,
    )
    acquisition_path = out / "hprc_spine_acquisition_report.json"
    _write_json(acquisition_path, acquisition)
    runner_plan = build_spine_bounded_runner_plan(
        acquisition_report_path=acquisition_path,
        mlx_profile_paths=mlx_profile_paths,
        hprc_queue_followup_report_paths=hprc_queue_followup_report_paths,
        repo_root=root,
        upstream_dir=scorer_upstream,
    )
    runner_plan_path = out / "hprc_spine_bounded_runner_plan.json"
    write_spine_bounded_runner_plan(
        output_path=runner_plan_path,
        plan=runner_plan,
        allow_overwrite=True,
    )
    final_report = _base_report(
        output_dir=out,
        mode="adapted_pr95_mlx_report",
        hard_byte_ceilings=hard_byte_ceilings,
        repo_root=root,
    )
    final_report.update(
        {
            "pr95_mlx_report_path": report_path.as_posix(),
            "pr95_mlx_report_sha256": _sha256_file(report_path),
            "selected_checkpoint": _checkpoint_summary(checkpoint, base=root),
            "pytorch_export_manifest_path": (None if export_manifest_path is None else export_manifest_path.as_posix()),
            "spine_adapter_report_path": adapter_report["report_path"],
            "projection_manifest_paths": [projection_manifest.as_posix()],
            "acquisition_report_path": acquisition_path.as_posix(),
            "bounded_runner_plan_path": runner_plan_path.as_posix(),
            "mlx_profile_paths": [_resolve(path, base=root).as_posix() for path in mlx_profile_paths],
            "hprc_queue_followup_report_paths": [
                _resolve(path, base=root).as_posix() for path in hprc_queue_followup_report_paths
            ],
            "selected_runner_rows": runner_plan["selected_runner_rows"],
            "blockers": _dedupe(
                [
                    *adapter_report["exact_gate"]["blockers"],
                    *runner_plan["blockers"],
                    "mlx_local_report_is_advisory_not_score_authority",
                ]
            ),
        }
    )
    final_report_path = out / "compact_renderer_mlx_spine_runner_report.json"
    _write_json(final_report_path, final_report)
    return {**final_report, "report_path": final_report_path.as_posix()}


def adapt_pr95_stage8_report_to_spine(
    *,
    pr95_stage8_report_path: str | Path,
    output_dir: str | Path,
    hard_byte_ceilings: tuple[int, ...] = DEFAULT_BASE_RENDERER_BYTE_CEILINGS,
    mlx_profile_paths: tuple[str | Path, ...] = (),
    hprc_queue_followup_report_paths: tuple[str | Path, ...] = (),
    run_receiver_proof: bool = False,
    receiver_proof_runtime_dir: str | Path = DEFAULT_PR95_RECEIVER_RUNTIME_DIR,
    keep_receiver_proof_output: bool = False,
    receiver_proof_timeout_seconds: int = 1800,
    allow_overwrite: bool = False,
    repo_root: str | Path = REPO_ROOT,
    upstream_dir: str | Path | None = None,
) -> dict[str, Any]:
    """Adapt a source-faithful PR95 Stage-8 report into the compact spine."""

    root = Path(repo_root).expanduser().resolve(strict=False)
    scorer_upstream = _resolve_scorer_upstream_dir(root, upstream_dir)
    out = Path(output_dir).expanduser().resolve(strict=False)
    if out.exists() and any(out.iterdir()) and not allow_overwrite:
        raise CompactRendererMlxSpineRunnerError(f"output dir is non-empty; pass --overwrite: {out}")
    out.mkdir(parents=True, exist_ok=True)
    report_path = _resolve_existing(pr95_stage8_report_path, base=root)
    stage8_report = _load_json(report_path)
    archive_raw = stage8_report.get("candidate_archive_zip_path") or (stage8_report.get("package_report") or {}).get(
        "archive_zip_path"
    )
    if not isinstance(archive_raw, str) or not archive_raw:
        raise CompactRendererMlxSpineRunnerError("pr95_stage8_report_missing_candidate_archive_zip_path")
    archive = _resolve_existing(archive_raw, base=root)
    receiver_proof_report: dict[str, Any] | None = None
    receiver_proof_paths: list[Path] = []
    package_report = (
        stage8_report.get("package_report") if isinstance(stage8_report.get("package_report"), dict) else {}
    )
    embedded_receiver_proof = (
        package_report.get("archive_bound_candidate_receiver_proof")
        if isinstance(package_report.get("archive_bound_candidate_receiver_proof"), dict)
        else None
    )
    if embedded_receiver_proof is not None:
        receiver_proof_report = embedded_receiver_proof
        proof_path = embedded_receiver_proof.get("proof_path")
        if isinstance(proof_path, str) and proof_path:
            receiver_proof_paths = [_resolve(proof_path, base=root)]
    if run_receiver_proof:
        receiver_proof_report = run_pr95_hnerv_receiver_proof(
            archive_zip=archive,
            runtime_dir=receiver_proof_runtime_dir,
            output_dir=out / "receiver_proof",
            keep_output=keep_receiver_proof_output,
            timeout_seconds=receiver_proof_timeout_seconds,
            repo_root=root,
        )
        proof_path = receiver_proof_report.get("report_path")
        if isinstance(proof_path, str) and proof_path:
            receiver_proof_paths = [Path(proof_path)]

    spine = build_pr95_hnerv_spine_from_archive(
        archive,
        runtime_submission_dir=receiver_proof_runtime_dir,
    )
    projection = write_representation_spine_projection(
        output_dir=out / "pr95_stage8_hnerv_spine",
        spine=spine,
        basename="pr95_stage8_hnerv_representation_spine",
    )
    projection_manifest = Path(projection["manifest_path"])
    acquisition = build_spine_acquisition_report(
        projection_manifest_paths=[projection_manifest],
        hard_byte_ceilings=hard_byte_ceilings,
    )
    acquisition_path = out / "hprc_spine_acquisition_report.json"
    _write_json(acquisition_path, acquisition)
    runner_plan = build_spine_bounded_runner_plan(
        acquisition_report_path=acquisition_path,
        mlx_profile_paths=mlx_profile_paths,
        receiver_proof_report_paths=receiver_proof_paths,
        hprc_queue_followup_report_paths=hprc_queue_followup_report_paths,
        repo_root=root,
        upstream_dir=scorer_upstream,
    )
    runner_plan_path = out / "hprc_spine_bounded_runner_plan.json"
    write_spine_bounded_runner_plan(
        output_path=runner_plan_path,
        plan=runner_plan,
        allow_overwrite=True,
    )

    exact_gate = stage8_report.get("exact_gate")
    stage8_blockers = (
        exact_gate.get("blockers")
        if isinstance(exact_gate, dict) and isinstance(exact_gate.get("blockers"), list)
        else []
    )
    local_training = stage8_report.get("local_training_result")
    raw_result = (
        local_training.get("raw_result")
        if isinstance(local_training, dict) and isinstance(local_training.get("raw_result"), dict)
        else {}
    )
    public_stage8_train_called = raw_result.get("public_stage8_train_stage_called")
    blockers: list[Any] = [
        *stage8_blockers,
        *runner_plan.get("blockers", []),
        "contest_cpu_cuda_exact_eval_not_executed",
    ]
    if not mlx_profile_paths:
        blockers.append("full_video_mlx_scorer_replay_not_attached")
    receiver_proof_passed = receiver_proof_report is not None and (
        receiver_proof_report.get("receiver_proof_valid") is True
        or receiver_proof_report.get("runtime_consumption_proof_passed") is True
        or receiver_proof_report.get("receiver_contract_satisfied") is True
    )
    if receiver_proof_report is None:
        blockers.append("receiver_proof_not_executed")
    elif not receiver_proof_passed:
        blockers.append("receiver_proof_failed")
        blockers.extend(receiver_proof_report.get("blockers") or [])
    else:
        refusal = receiver_proof_report.get("exact_readiness_refusal")
        if isinstance(refusal, dict):
            blockers.extend(refusal.get("blockers") or [])

    final_report = _base_report(
        output_dir=out,
        mode="adapted_pr95_stage8_public_archive_report",
        hard_byte_ceilings=hard_byte_ceilings,
        repo_root=root,
    )
    final_report.update(
        {
            "pr95_stage8_report_path": report_path.as_posix(),
            "pr95_stage8_report_sha256": _sha256_file(report_path),
            "stage8_mode": stage8_report.get("mode"),
            "source_archive_zip": stage8_report.get("source_archive_zip"),
            "candidate_archive_zip_path": archive.as_posix(),
            "candidate_archive_zip_bytes": archive.stat().st_size,
            "candidate_archive_zip_sha256": _sha256_file(archive),
            "projection_manifest_paths": [projection_manifest.as_posix()],
            "receiver_proof_report_paths": [path.as_posix() for path in receiver_proof_paths],
            "receiver_proof_report": receiver_proof_report,
            "acquisition_report_path": acquisition_path.as_posix(),
            "bounded_runner_plan_path": runner_plan_path.as_posix(),
            "selected_runner_rows": runner_plan["selected_runner_rows"],
            "mlx_profile_paths": [_resolve(path, base=root).as_posix() for path in mlx_profile_paths],
            "stage8_source_faithfulness": {
                "schema": "pr95_stage8_source_faithfulness.v1",
                "public_stage8_train_stage_called": public_stage8_train_called is True,
                "source_faithful_training_complete": (
                    public_stage8_train_called is True
                    and "stage8_zero_epoch_source_seed_packaged_no_training" not in stage8_blockers
                    and "stage8_training_not_executed_plan_only" not in stage8_blockers
                ),
                "optimizer_semantics": "public_pr95_stage8_muon_adamw_source_code",
                "score_authority": "none_until_exact_cpu_cuda",
            },
            "hprc_queue_followup_report_paths": [
                _resolve(path, base=root).as_posix() for path in hprc_queue_followup_report_paths
            ],
            "blockers": _dedupe(blockers),
        }
    )
    final_report_path = out / "compact_renderer_mlx_spine_runner_report.json"
    _write_json(final_report_path, final_report)
    return {**final_report, "report_path": final_report_path.as_posix()}


def execute_pr95_stage8_source_and_adapt(
    *,
    output_dir: str | Path,
    source_archive_zip: str | Path,
    source_video_path: str | Path,
    hard_byte_ceilings: tuple[int, ...] = DEFAULT_BASE_RENDERER_BYTE_CEILINGS,
    mlx_profile_paths: tuple[str | Path, ...] = (),
    hprc_queue_followup_report_paths: tuple[str | Path, ...] = (),
    stage8_epochs: int = 0,
    stage8_eval_every: int = 1,
    stage8_batch_size: int = 1,
    stage8_device: str = "cpu",
    stage8_muon_weight_decay: float = 5e-4,
    stage8_target_cache_path: str | Path | None = None,
    stage8_build_target_cache_if_missing: bool = True,
    run_receiver_proof: bool = False,
    receiver_proof_runtime_dir: str | Path = DEFAULT_PR95_RECEIVER_RUNTIME_DIR,
    keep_receiver_proof_output: bool = False,
    receiver_proof_timeout_seconds: int = 1800,
    allow_overwrite: bool = False,
    repo_root: str | Path = REPO_ROOT,
    upstream_dir: str | Path | None = None,
) -> dict[str, Any]:
    """Execute the public PR95 Stage-8 source lane, then adapt it to the spine."""

    from tools.run_pr95_stage8_from_public_archive import (
        DEFAULT_CHALLENGE_ROOT,
        DEFAULT_PUBLIC_SUBMISSION_ROOT,
        run_pr95_stage8_from_public_archive,
    )

    root = Path(repo_root).expanduser().resolve(strict=False)
    out = Path(output_dir).expanduser().resolve(strict=False)
    if out.exists() and any(out.iterdir()) and not allow_overwrite:
        raise CompactRendererMlxSpineRunnerError(f"output dir is non-empty; pass --overwrite: {out}")
    out.mkdir(parents=True, exist_ok=True)
    stage8_report = run_pr95_stage8_from_public_archive(
        source_archive_zip=_resolve_existing(source_archive_zip, base=root),
        public_submission_root=DEFAULT_PUBLIC_SUBMISSION_ROOT,
        challenge_root=DEFAULT_CHALLENGE_ROOT,
        source_video_path=_resolve(source_video_path, base=root),
        output_dir=out / "pr95_stage8_source_lane",
        epochs=int(stage8_epochs),
        eval_every=int(stage8_eval_every),
        batch_size=int(stage8_batch_size),
        muon_weight_decay=float(stage8_muon_weight_decay),
        device=stage8_device,
        execute=True,
        target_cache_path=None if stage8_target_cache_path is None else _resolve(stage8_target_cache_path, base=root),
        build_target_cache_if_missing=bool(stage8_build_target_cache_if_missing),
        overwrite=True,
    )
    return adapt_pr95_stage8_report_to_spine(
        pr95_stage8_report_path=stage8_report["report_path"],
        output_dir=out,
        hard_byte_ceilings=hard_byte_ceilings,
        mlx_profile_paths=mlx_profile_paths,
        hprc_queue_followup_report_paths=hprc_queue_followup_report_paths,
        run_receiver_proof=run_receiver_proof,
        receiver_proof_runtime_dir=receiver_proof_runtime_dir,
        keep_receiver_proof_output=keep_receiver_proof_output,
        receiver_proof_timeout_seconds=receiver_proof_timeout_seconds,
        allow_overwrite=True,
        repo_root=root,
        upstream_dir=upstream_dir,
    )


def build_plan_only_report(
    *,
    output_dir: str | Path,
    hard_byte_ceilings: tuple[int, ...] = DEFAULT_BASE_RENDERER_BYTE_CEILINGS,
    repo_root: str | Path = REPO_ROOT,
    allow_overwrite: bool = False,
) -> dict[str, Any]:
    """Write the executable backlog when trained MLX artifacts are absent."""

    root = Path(repo_root).expanduser().resolve(strict=False)
    out = Path(output_dir).expanduser().resolve(strict=False)
    if out.exists() and any(out.iterdir()) and not allow_overwrite:
        raise CompactRendererMlxSpineRunnerError(f"output dir is non-empty; pass --overwrite: {out}")
    out.mkdir(parents=True, exist_ok=True)
    report = _base_report(
        output_dir=out,
        mode="plan_only",
        hard_byte_ceilings=hard_byte_ceilings,
        repo_root=root,
    )
    report["blockers"] = [
        "trained_mlx_checkpoint_report_or_execute_pr95_mlx_smoke_required",
        "receiver_proof_not_yet_emitted",
        "contest_cpu_cuda_exact_eval_missing",
    ]
    path = out / "compact_renderer_mlx_spine_runner_report.json"
    _write_json(path, report)
    return {**report, "report_path": path.as_posix()}


def execute_planner_gated_compact_family(
    *,
    family: str,
    output_dir: str | Path,
    num_pairs: int,
    epochs: int,
    hard_byte_ceilings: tuple[int, ...] = DEFAULT_BASE_RENDERER_BYTE_CEILINGS,
    mlx_profile_paths: tuple[str | Path, ...] = (),
    hprc_queue_followup_report_paths: tuple[str | Path, ...] = (),
    allow_overwrite: bool = False,
    repo_root: str | Path = REPO_ROOT,
) -> dict[str, Any]:
    """Emit a planner-owned refusal for families whose adapters are not real yet.

    Planner-gated families are accepted by ``--execute-family`` only to produce
    a normal runner report carrying the score-aware planner row and exact
    blockers. They are not allowed to fake execution.
    """

    if family not in PLANNER_GATED_FAMILIES:
        raise CompactRendererMlxSpineRunnerError(
            f"planner-gated execution only supports {PLANNER_GATED_FAMILIES}; got {family!r}"
        )
    root = Path(repo_root).expanduser().resolve(strict=False)
    out = Path(output_dir).expanduser().resolve(strict=False)
    if out.exists() and any(out.iterdir()) and not allow_overwrite:
        raise CompactRendererMlxSpineRunnerError(f"output dir is non-empty; pass --overwrite: {out}")
    out.mkdir(parents=True, exist_ok=True)
    backend = COMPACT_FAMILY_BACKENDS[family]
    planner = _score_aware_carrier_training_plan(family, backend)
    blockers = _dedupe(
        [
            *planner.get("dispatch_blockers", []),
            f"{family}_mlx_native_train_export_archive_adapter_missing",
            f"{family}_byte_closed_archive_export_missing",
            f"{family}_receiver_proof_missing",
            f"{family}_full_video_mlx_prefilter_not_executed",
            "local_cpu_replay_not_executed",
            "contest_cpu_cuda_exact_eval_not_executed",
        ]
    )
    report = _base_report(
        output_dir=out,
        mode=f"{family}_planner_gated_execution_refused",
        hard_byte_ceilings=hard_byte_ceilings,
        repo_root=root,
    )
    report.update(
        {
            "execute_family": family,
            "trainer_launch_allowed": False,
            "launch_refusal_reason": (
                "planner row consumed; native MLX train/export/archive adapter "
                "is missing, so no fake training or manual launch is allowed"
            ),
            "requested_campaign": {
                "schema": "compact_carrier_campaign_request.v1",
                "family": family,
                "num_pairs": int(num_pairs),
                "epochs": int(epochs),
                "hard_byte_ceilings": [int(value) for value in hard_byte_ceilings],
                "mlx_profile_paths": [_resolve(path, base=root).as_posix() for path in mlx_profile_paths],
                "hprc_queue_followup_report_paths": [
                    _resolve(path, base=root).as_posix() for path in hprc_queue_followup_report_paths
                ],
            },
            "score_aware_carrier_training_plan": planner,
            "adapter_contract_required": {
                "schema": "mlx_native_compact_carrier_adapter_contract.v1",
                "required_surfaces": [
                    "MLX renderer module with differentiable pair decode",
                    "real SegNet teacher cache",
                    "real PoseNet teacher cache",
                    "PR95-faithful staged optimizer bridge",
                    "coder-aware regularization and QAT hooks",
                    "byte-closed archive exporter",
                    "numpy-portable inflate runtime",
                    "receiver proof",
                    "full-video MLX prefilter report",
                    "local CPU replay gate",
                ],
                "false_authority_until_all_surfaces_exist": True,
            },
            "next_actions": [
                f"implement_{family}_mlx_native_renderer_bundle",
                f"implement_{family}_archive_exporter_and_numpy_inflate",
                f"run_{family}_2_pair_mlx_training_smoke_with_real_scorer_teachers",
                f"scale_{family}_32_128_600_pair_campaigns_after_smoke",
                "promote_only_byte_closed_local_winners_to_contest_cpu_then_cuda",
            ],
            "blockers": blockers,
        }
    )
    path = out / "compact_renderer_mlx_spine_runner_report.json"
    _write_json(path, report)
    return {**report, "report_path": path.as_posix()}


def _resolve_execute_modelsize_candidate(
    *,
    family: str,
    candidate_id: str,
    hard_byte_ceilings: tuple[int, ...],
    num_pairs: int = CONTEST_PAIR_COUNT,
    target_modelsize_mparams: tuple[float, ...] = (),
    hinerv_target_modelsize_mparams: tuple[float, ...] = (),
    snerv_official_modelsize_mparams: tuple[float, ...] = (),
    snerv_modelsize_control_profile_id: str = DEFAULT_SNERV_MODELSIZE_CONTROL_PROFILE_ID,
    snerv_official_enc_strds: tuple[int, ...] = DEFAULT_SNERV_MODELSIZE_ENC_STRDS,
    snerv_official_dec_strds: tuple[int, ...] = DEFAULT_SNERV_MODELSIZE_DEC_STRDS,
    snerv_model_size_adapter: str | None = None,
    snerv_temporal_context: int = 0,
    snerv_temporal_modes: tuple[str, ...] = ("delta",),
    snerv_official_skip_high_modes: tuple[str, ...] = ("full",),
    byte_cap_feedback_rows: Sequence[Mapping[str, Any]] = (),
) -> dict[str, Any] | None:
    """Resolve an executable NeRV byte-budget candidate for a family launch.

    ``auto`` chooses a byte-plausible candidate from the complete enumeration,
    not just the truncated report rows. ``none/manual/off`` preserves the
    explicit CLI knobs for focused probes. Unknown ids fail before any campaign
    starts so the planner cannot silently drift away from curriculum provenance.
    """

    token = str(candidate_id or "auto").strip()
    if _modelsize_candidate_resolution_disabled(token):
        return None
    shared_targets = tuple(float(value) for value in target_modelsize_mparams)
    hinerv_targets = _dedupe_float_tuple((*shared_targets, *tuple(float(v) for v in hinerv_target_modelsize_mparams)))
    snerv_targets = _dedupe_float_tuple((*shared_targets, *tuple(float(v) for v in snerv_official_modelsize_mparams)))
    hinerv_auto_official_only = family == "hi_nerv" and token.lower() == "auto"
    if family == "hi_nerv":
        candidates = [
            row.as_dict()
            for row in enumerate_hinerv_modelsize_candidates(
                hard_byte_ceilings=hard_byte_ceilings,
                num_pairs=int(num_pairs),
                use_hierarchical_feature_grid_options=((True,) if hinerv_auto_official_only else (False, True)),
                use_convnext_blocks_options=((True,) if hinerv_auto_official_only else (False, True)),
                target_modelsize_mparams=hinerv_targets,
            )
        ]
    elif family == "snerv":
        candidates = [
            row.as_dict()
            for row in enumerate_snerv_modelsize_candidates(
                hard_byte_ceilings=hard_byte_ceilings,
                num_pairs=int(num_pairs),
                official_modelsize_mparams=snerv_targets,
                official_enc_strds=tuple(int(value) for value in snerv_official_enc_strds),
                official_dec_strds=tuple(int(value) for value in snerv_official_dec_strds),
                snerv_model_size_adapter=(
                    normalize_snerv_model_size_adapter(snerv_model_size_adapter)
                    if snerv_model_size_adapter
                    else DEFAULT_SNERV_MODEL_SIZE_ADAPTER
                ),
                modelsize_control_profile_id=str(snerv_modelsize_control_profile_id),
                temporal_context=int(snerv_temporal_context),
                temporal_modes=tuple(str(value) for value in snerv_temporal_modes),
                official_skip_high_modes=tuple(str(value) for value in snerv_official_skip_high_modes),
            )
        ]
    else:
        raise CompactRendererMlxSpineRunnerError(
            f"modelsize candidate resolution is only supported for hi_nerv/snerv; got {family!r}"
        )
    if not candidates:
        raise CompactRendererMlxSpineRunnerError(f"no {family} modelsize candidates were enumerated")
    candidates = _attach_byte_cap_controller_predictions(
        candidates,
        family=family,
        byte_cap_feedback_rows=byte_cap_feedback_rows,
    )
    if token.lower() == "auto":
        if family == "hi_nerv":
            official_candidates = [row for row in candidates if _hi_nerv_modelsize_candidate_has_official_controls(row)]
            official_under = [row for row in official_candidates if bool(row.get("nominal_under_ceiling"))]
            if not official_under:
                raise CompactRendererMlxSpineRunnerError("hinerv_official_control_candidate_missing_under_ceiling")
            candidates = official_candidates
        if family == "hi_nerv" and hinerv_targets:
            target_candidates = [
                row for row in candidates if row.get("capacity_source") == "local_hinerv_target_modelsize"
            ]
            if target_candidates:
                candidates = target_candidates
        if family == "snerv" and snerv_targets:
            official_candidates = [row for row in candidates if row.get("official_modelsize_solution") is not None]
            if official_candidates:
                candidates = official_candidates
        under = [row for row in candidates if _byte_cap_controller_predicts_under_ceiling(row)]
        if under:
            tightest_ceiling = min(int(row["hard_byte_ceiling"]) for row in under)
            tightest_under = [row for row in under if int(row["hard_byte_ceiling"]) == tightest_ceiling]
            if family == "hi_nerv" and hinerv_targets:
                return min(
                    tightest_under,
                    key=lambda row: (
                        float(row.get("modelsize_error_mparams") or 0.0),
                        int(row["nominal_total_payload_bytes"]),
                        -float(row.get("modelsize_mparams") or 0.0),
                        int(row.get("total_trainable_params", 0)),
                    ),
                )
            return max(
                tightest_under,
                key=lambda row: (
                    int(row["nominal_total_payload_bytes"]),
                    -int(_byte_cap_controller_predicted_archive_bytes(row) or row["nominal_total_payload_bytes"]),
                    int(row.get("capacity_source") == "local_hinerv_target_modelsize"),
                    int(row.get("official_modelsize_solution") is not None),
                    float(row.get("modelsize_mparams") or 0.0),
                    int(row.get("total_trainable_params", 0)),
                ),
            )
        calibrated_rows = [row for row in candidates if _byte_cap_controller_has_observation(row)]
        if calibrated_rows:
            best = min(
                calibrated_rows,
                key=lambda row: (
                    abs(_byte_cap_controller_predicted_headroom(row)),
                    int(row["hard_byte_ceiling"]),
                    -float(row.get("modelsize_mparams") or 0.0),
                ),
            )
            raise CompactRendererMlxSpineRunnerError(
                f"{family}_modelsize_auto_no_calibrated_candidate_under_hard_byte_ceiling: "
                f"best_candidate={best.get('candidate_id')} "
                f"predicted_archive_bytes={_byte_cap_controller_predicted_archive_bytes(best)} "
                f"hard_byte_ceiling={best.get('hard_byte_ceiling')}"
            )
        best_uncalibrated = min(
            candidates,
            key=lambda row: (
                abs(_byte_cap_controller_predicted_headroom(row)),
                float(row.get("modelsize_error_mparams") or 0.0),
                -int(row.get("capacity_source") == "local_hinerv_target_modelsize"),
                -int(row.get("official_modelsize_solution") is not None),
                -float(row.get("modelsize_mparams") or 0.0),
                int(row["hard_byte_ceiling"]),
            ),
        )
        predicted_archive_bytes = _byte_cap_controller_predicted_archive_bytes(best_uncalibrated)
        hard_byte_ceiling = int(best_uncalibrated["hard_byte_ceiling"])
        normalized_snerv_adapter = (
            normalize_snerv_model_size_adapter(snerv_model_size_adapter)
            if snerv_model_size_adapter
            else DEFAULT_SNERV_MODEL_SIZE_ADAPTER
        )
        near_cap_over_ratio = (
            (float(predicted_archive_bytes) / float(hard_byte_ceiling))
            if predicted_archive_bytes is not None and hard_byte_ceiling > 0
            else None
        )
        snerv_spectra_near_cap = bool(
            family == "snerv"
            and snerv_targets
            and normalized_snerv_adapter == SNERV_SPECTRA_PRESERVING_ADAPTER
            and near_cap_over_ratio is not None
            and near_cap_over_ratio <= 1.10
        )
        generic_measured_feedback_near_cap = bool(
            family in {"hi_nerv", "snerv"} and near_cap_over_ratio is not None and 1.0 < near_cap_over_ratio <= 1.01
        )
        if snerv_spectra_near_cap or generic_measured_feedback_near_cap:
            near_cap = dict(best_uncalibrated)
            near_cap["modelsize_auto_selection_requires_measured_archive_feedback"] = True
            near_cap["modelsize_auto_selection_warning"] = (
                "snerv_spectra_adapter_uncalibrated_near_cap_candidate"
                if snerv_spectra_near_cap
                else f"{family}_uncalibrated_near_cap_candidate_requires_archive_measurement"
            )
            near_cap["modelsize_auto_selection_predicted_archive_bytes"] = int(predicted_archive_bytes)
            near_cap["modelsize_auto_selection_hard_byte_ceiling"] = hard_byte_ceiling
            near_cap["modelsize_auto_selection_over_cap_ratio"] = near_cap_over_ratio
            near_cap["promotion_eligible"] = False
            near_cap["ready_for_exact_eval_dispatch"] = False
            near_cap["score_claim"] = False
            return near_cap
        raise CompactRendererMlxSpineRunnerError(
            f"{family}_modelsize_auto_no_candidate_under_hard_byte_ceiling: "
            f"best_candidate={best_uncalibrated.get('candidate_id')} "
            f"predicted_archive_bytes={predicted_archive_bytes} "
            f"hard_byte_ceiling={best_uncalibrated.get('hard_byte_ceiling')} "
            "measured_archive_feedback_required"
        )
    for row in candidates:
        if row["candidate_id"] == token:
            return _enforce_explicit_modelsize_byte_cap_candidate(
                row,
                family=family,
                candidate_id=token,
            )
    rebuilt = _modelsize_candidate_from_self_describing_id(
        family=family,
        candidate_id=token,
    )
    if rebuilt is not None:
        attached = _attach_byte_cap_controller_predictions(
            [rebuilt],
            family=family,
            byte_cap_feedback_rows=byte_cap_feedback_rows,
        )[0]
        return _enforce_explicit_modelsize_byte_cap_candidate(
            attached,
            family=family,
            candidate_id=token,
        )
    raise CompactRendererMlxSpineRunnerError(
        f"unknown {family} --modelsize-candidate-id {token!r}; "
        "rerun plan mode and select one of the emitted candidate_id values"
    )


def _enforce_explicit_modelsize_byte_cap_candidate(
    row: Mapping[str, Any],
    *,
    family: str,
    candidate_id: str,
) -> dict[str, Any]:
    """Reject explicit modelsize candidates once measured bytes prove over-cap."""

    selected = dict(row)
    controller = selected.get("byte_cap_controller")
    if (
        isinstance(controller, Mapping)
        and _byte_cap_controller_has_observation(selected)
        and controller.get("predicted_under_hard_byte_ceiling") is False
    ):
        raise CompactRendererMlxSpineRunnerError(
            f"{family}_modelsize_explicit_candidate_over_hard_byte_ceiling: "
            f"candidate_id={candidate_id} "
            f"predicted_archive_bytes={controller.get('predicted_archive_bytes')} "
            f"hard_byte_ceiling={selected.get('hard_byte_ceiling')} "
            "measured_archive_feedback_required_new_candidate"
        )
    return selected


def _effective_snerv_modelsize_adapter_for_resolution(args: argparse.Namespace) -> str:
    """Return the SNeRV adapter that modelsize auto-selection must size.

    Runtime launch already gives planner candidates precedence, but auto
    candidate enumeration happens before runtime dispatch.  Keep the resolver
    pointed at the same adapter requested by the operator-facing controls so
    ``--snerv-spectra-preserving-adapter`` cannot silently size a base SNAR1
    graph and fail only after campaign startup.
    """

    raw_explicit_adapter = str(getattr(args, "snerv_model_size_adapter", "") or "").strip()
    explicit_adapter = normalize_snerv_model_size_adapter(raw_explicit_adapter) if raw_explicit_adapter else ""
    spectra_requested = bool(getattr(args, "snerv_spectra_preserving_adapter", False))
    if spectra_requested:
        if explicit_adapter and explicit_adapter != SNERV_SPECTRA_PRESERVING_ADAPTER:
            raise SystemExit(
                "--snerv-spectra-preserving-adapter conflicts with "
                f"--snerv-model-size-adapter {explicit_adapter!r}; use "
                f"{SNERV_SPECTRA_PRESERVING_ADAPTER!r} or omit the manual adapter"
            )
        return SNERV_SPECTRA_PRESERVING_ADAPTER
    return explicit_adapter or DEFAULT_SNERV_MODEL_SIZE_ADAPTER


def _snerv_auto_skip_high_modes_for_resolution(
    *,
    explicit_mode: str | None,
    model_size_adapter: str,
) -> tuple[str, ...]:
    """Enumerate compact official SNeRV skip modes unless the user pinned one.

    The executor still consumes exactly one resolved candidate.  This helper
    only broadens ``auto`` candidate discovery so the rate-plausible compact
    modes replace the historically huge ``full`` mode by default. ``full`` is
    still available when explicitly requested as a diagnostic, but byte-capped
    official SNeRV launches should not spend their first smoke on a known
    multi-megabyte MFU activation slab.
    """

    if explicit_mode is not None:
        return (str(explicit_mode),)
    if normalize_snerv_model_size_adapter(str(model_size_adapter)) == SNERV_OFFICIAL_MFU_HFR_TUB_PRIMITIVES_ADAPTER:
        return ("scalar_mean", "channel_mean", "shared_mean")
    return ("full",)


def _snerv_hard_byte_ceiling_configured(
    hard_byte_ceilings: Sequence[int],
) -> bool:
    return any(int(value) > 0 for value in hard_byte_ceilings)


def _modelsize_candidate_resolution_disabled(candidate_id: Any) -> bool:
    """Return whether the launch requested manual modelsize knobs only."""

    return str(candidate_id or "auto").strip().lower() in {
        "none",
        "manual",
        "off",
        "false",
        "0",
    }


def _snerv_official_modelsize_candidate_resolution_blockers(
    args: argparse.Namespace,
) -> list[str]:
    """Block source-named SNeRV capacity flags when candidates are disabled."""

    if getattr(args, "execute_family", None) != "snerv":
        return []
    if not _modelsize_candidate_resolution_disabled(getattr(args, "modelsize_candidate_id", "auto")):
        return []
    flag_attrs = (
        ("--target-modelsize-mparams", "target_modelsize_mparams"),
        ("--snerv-official-modelsize-mparams", "snerv_official_modelsize_mparams"),
        ("--snerv-official-enc-strds", "snerv_official_enc_strds"),
        ("--snerv-official-dec-strds", "snerv_official_dec_strds"),
    )
    blockers = [
        f"snerv_official_modelsize_control_requires_candidate_resolution:{flag}"
        for flag, attr in flag_attrs
        if getattr(args, attr, None) is not None
    ]
    profile = str(
        getattr(
            args,
            "snerv_modelsize_control_profile",
            DEFAULT_SNERV_MODELSIZE_CONTROL_PROFILE_ID,
        )
    )
    if profile != DEFAULT_SNERV_MODELSIZE_CONTROL_PROFILE_ID:
        blockers.append(
            "snerv_official_modelsize_control_requires_candidate_resolution:--snerv-modelsize-control-profile"
        )
    return blockers


def _dedupe_float_tuple(values: tuple[float, ...]) -> tuple[float, ...]:
    out: list[float] = []
    seen: set[float] = set()
    for value in values:
        normalized = float(value)
        if normalized in seen:
            continue
        seen.add(normalized)
        out.append(normalized)
    return tuple(out)


def _attach_byte_cap_controller_predictions(
    candidates: Sequence[Mapping[str, Any]],
    *,
    family: str,
    byte_cap_feedback_rows: Sequence[Mapping[str, Any]] = (),
) -> list[dict[str, Any]]:
    """Attach calibrated archive-byte predictions to modelsize candidates."""

    calibration = _byte_cap_calibration(
        family=family,
        feedback_rows=byte_cap_feedback_rows,
    )
    return [
        {
            **dict(candidate),
            "byte_cap_controller": _byte_cap_controller_prediction(
                candidate,
                family=family,
                calibration=calibration,
            ),
        }
        for candidate in candidates
    ]


def _byte_cap_controller_prediction(
    candidate: Mapping[str, Any],
    *,
    family: str,
    calibration: Mapping[str, Any],
) -> dict[str, Any]:
    nominal = _compact_first_present_int(
        candidate,
        (
            "nominal_total_payload_bytes",
            "total_payload_bytes",
            "estimated_total_payload_bytes",
            "packet_bytes",
        ),
    )
    ceiling = _compact_first_present_int(candidate, ("hard_byte_ceiling",))
    codec = _candidate_byte_cap_codec(candidate)
    observations = _byte_cap_matching_observations(
        calibration,
        candidate=candidate,
        codec=codec,
    )
    blockers: list[str] = []
    if nominal is None:
        blockers.append("byte_cap_controller_candidate_nominal_payload_missing")
    if ceiling is None:
        blockers.append("byte_cap_controller_candidate_hard_ceiling_missing")
    if not observations:
        blockers.append("byte_cap_controller_measured_archive_feedback_missing")
    predicted = nominal
    prediction_rule = "nominal_payload_bytes_uncalibrated"
    residual_guard_bytes = 0
    if nominal is not None and observations:
        predicted = _byte_cap_archive_prediction_from_observations(
            nominal_payload_bytes=int(nominal),
            observations=observations,
        )
        residual_guard_bytes = _byte_cap_leave_one_out_underprediction_margin(observations)
        predicted += residual_guard_bytes
        prediction_rule = "max_observed_archive_to_nominal_ratio_or_additive_overhead_plus_loo_residual_guard"
    calibrated_prediction = bool(observations and not blockers)
    headroom = None
    if predicted is not None and ceiling is not None:
        headroom = int(ceiling) - int(predicted)
    predicted_under = None
    if headroom is not None and calibrated_prediction:
        predicted_under = headroom >= 0
    return {
        "schema": "compact_modelsize_byte_cap_controller.v1",
        "family": str(family),
        "codec": codec,
        "hard_byte_ceiling": ceiling,
        "nominal_payload_bytes": nominal,
        "predicted_archive_bytes": predicted,
        "predicted_headroom_bytes": headroom,
        "predicted_under_hard_byte_ceiling": predicted_under,
        "prediction_rule": prediction_rule,
        "prediction_authority": (
            "calibrated_measured_archive_feedback"
            if calibrated_prediction
            else "uncalibrated_nominal_payload_diagnostic"
        ),
        "calibrated_archive_prediction": calibrated_prediction,
        "calibration_residual_guard_bytes": int(residual_guard_bytes),
        "calibration_observation_count": len(observations),
        "calibration_source": calibration.get("calibration_source"),
        "matching_observations": observations,
        "authority_surface": "measured_archive_zip_bytes_after_receiver_export",
        "selection_semantics": (
            "auto modelsize candidates spend only the calibrated bytes that fit "
            "the hard archive cap; scorer/replay authority remains separate"
        ),
        "blockers": blockers,
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }


def _byte_cap_archive_prediction_from_observations(
    *,
    nominal_payload_bytes: int,
    observations: Sequence[Mapping[str, Any]],
) -> int:
    max_ratio = max(float(row["archive_to_nominal_ratio"]) for row in observations)
    max_delta = max(int(row["archive_minus_nominal_bytes"]) for row in observations)
    return max(
        math.ceil(float(nominal_payload_bytes) * max_ratio),
        int(nominal_payload_bytes) + int(max_delta),
    )


def _byte_cap_leave_one_out_underprediction_margin(
    observations: Sequence[Mapping[str, Any]],
) -> int:
    """Return the worst receiver-proof archive underprediction in calibration.

    The base predictor is the upper envelope of ratio and additive overhead.
    A final-checkpoint export can still shift entropy enough to falsify that
    envelope.  Leave-one-out residuals turn those falsifications into an
    explicit guard band before the next byte spend.
    """

    if len(observations) < 2:
        return 0
    worst = 0
    for index, row in enumerate(observations):
        peers = [peer for peer_index, peer in enumerate(observations) if peer_index != index]
        if not peers:
            continue
        nominal = int(row["nominal_payload_bytes"])
        measured = int(row["measured_archive_bytes"])
        predicted = _byte_cap_archive_prediction_from_observations(
            nominal_payload_bytes=nominal,
            observations=peers,
        )
        worst = max(worst, measured - predicted)
    return max(0, int(worst))


def _byte_cap_calibration(
    *,
    family: str,
    feedback_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    observations: list[dict[str, Any]] = []
    rejected_rows: list[dict[str, Any]] = []
    for index, row in enumerate(feedback_rows):
        row_family = str(row.get("family") or family)
        if row_family and row_family != family:
            continue
        receiver_closed = _truthy_any(
            row,
            (
                "receiver_closed",
                "receiver_proof_ready",
                "receiver_proof_passed",
                "runtime_consumption_proof_ready",
                "receiver_archive_replay_verified",
                "receiver_contract_satisfied",
                "byte_closed_receiver_proof",
            ),
        )
        if not receiver_closed:
            rejected_rows.append(
                {
                    "source_index": index,
                    "row_id": row.get("row_id") or row.get("candidate_id"),
                    "reason": "byte_cap_feedback_row_not_receiver_closed",
                }
            )
            continue
        measured = _compact_first_present_int(
            row,
            (
                "charged_archive_bytes",
                "measured_archive_bytes",
                "archive_bytes",
                "archive_zip_bytes",
                "candidate_archive_bytes",
            ),
        )
        nominal = _compact_first_present_int(
            row,
            (
                "nominal_total_payload_bytes",
                "total_payload_bytes",
                "estimated_total_payload_bytes",
                "packet_bytes",
            ),
        )
        if measured is None or nominal is None or measured <= 0 or nominal <= 0:
            rejected_rows.append(
                {
                    "source_index": index,
                    "row_id": row.get("row_id") or row.get("candidate_id"),
                    "reason": "byte_cap_feedback_row_missing_positive_measured_or_nominal_bytes",
                }
            )
            continue
        observations.append(
            {
                "source_index": index,
                "source_path": row.get("source_path") or row.get("report_path"),
                "row_id": row.get("row_id") or row.get("candidate_id"),
                "candidate_id": row.get("candidate_id"),
                "family": row_family,
                "codec": _candidate_byte_cap_codec(row),
                "measured_archive_bytes": int(measured),
                "nominal_payload_bytes": int(nominal),
                "archive_minus_nominal_bytes": int(measured) - int(nominal),
                "archive_to_nominal_ratio": float(measured) / float(nominal),
                "source_bound_controls": _byte_cap_candidate_match_controls(row),
                "receiver_closed": True,
                **{
                    key: row[key]
                    for key in (
                        "calibrated_archive_overrun_bytes",
                        "required_nominal_payload_bytes_max",
                        "hard_byte_ceiling_measurement_bypass_enabled",
                        "hard_byte_ceiling_checked_after_export",
                    )
                    if key in row
                },
            }
        )
    return {
        "schema": "compact_modelsize_byte_cap_calibration.v1",
        "family": str(family),
        "calibration_source": ("measured_archive_feedback_rows" if observations else "none"),
        "observation_count": len(observations),
        "rejected_feedback_row_count": len(rejected_rows),
        "rejected_feedback_rows": rejected_rows,
        "observations": observations,
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }


def _byte_cap_matching_observations(
    calibration: Mapping[str, Any],
    *,
    candidate: Mapping[str, Any],
    codec: str | None,
) -> list[dict[str, Any]]:
    observations = [dict(row) for row in calibration.get("observations", ()) if isinstance(row, Mapping)]
    candidate_id = str(candidate.get("candidate_id") or "")
    if candidate_id:
        exact_id = [row for row in observations if str(row.get("candidate_id") or "") == candidate_id]
        if exact_id:
            return exact_id
    target_controls = _byte_cap_candidate_match_controls(candidate)
    exact_controls = [
        row for row in observations if _byte_cap_controls_match(row.get("source_bound_controls"), target_controls)
    ]
    if exact_controls:
        return exact_controls
    scoped_rows = [
        row
        for row in observations
        if row.get("candidate_id") or _byte_cap_controls_are_candidate_scoped(row.get("source_bound_controls"))
    ]
    if scoped_rows:
        return []
    if codec:
        exact = [row for row in observations if row.get("codec") == codec]
        if exact:
            return exact
    return observations


def _candidate_byte_cap_codec(row: Mapping[str, Any]) -> str | None:
    for key in (
        "decoder_codec",
        "decoder_payload_codec",
        "codec",
        "latent_codec",
    ):
        value = row.get(key)
        if value:
            return str(value)
    candidate = row.get("modelsize_candidate")
    if isinstance(candidate, Mapping):
        return _candidate_byte_cap_codec(candidate)
    return None


def _byte_cap_candidate_match_controls(candidate: Mapping[str, Any]) -> dict[str, Any]:
    keys = (
        "family",
        "num_pairs",
        "hard_byte_ceiling",
        "decoder_codec",
        "decoder_payload_codec",
        "wavelet",
        "levels",
        "bits_per_coeff",
        "step_map_bits_per_coeff",
        "snerv_model_size_adapter",
        "fc_dim",
        "emb_size",
        "patch_radius",
        "mfu_scales",
        "hfr_gain",
        "temporal_context",
        "temporal_mode",
        "official_skip_high_mode",
        "use_hierarchical_feature_grid",
        "use_convnext_blocks",
        "local_grid_levels",
        "local_grid_channels",
        "convnext_mlp_ratio",
        "convnext_kernel_size",
    )
    out: dict[str, Any] = {}
    for key in keys:
        if key not in candidate:
            continue
        value = candidate[key]
        if isinstance(value, tuple):
            value = list(value)
        out[key] = value
    return out


def _byte_cap_controls_match(
    source_controls: Any,
    target_controls: Mapping[str, Any],
) -> bool:
    if not isinstance(source_controls, Mapping) or not source_controls:
        return False
    if not target_controls:
        return False
    for key, source_value in source_controls.items():
        if key not in target_controls:
            return False
        target_value = target_controls[key]
        if isinstance(source_value, tuple):
            source_value = list(source_value)
        if isinstance(target_value, tuple):
            target_value = list(target_value)
        if source_value != target_value:
            return False
    return True


def _byte_cap_controls_are_candidate_scoped(source_controls: Any) -> bool:
    if not isinstance(source_controls, Mapping) or not source_controls:
        return False
    generic_keys = {
        "family",
        "decoder_codec",
        "decoder_payload_codec",
        "hard_byte_ceiling",
    }
    return any(str(key) not in generic_keys for key in source_controls)


def _byte_cap_controller_predicts_under_ceiling(row: Mapping[str, Any]) -> bool:
    controller = row.get("byte_cap_controller")
    if not isinstance(controller, Mapping):
        return False
    if int(controller.get("calibration_observation_count") or 0) <= 0:
        return False
    value = controller.get("predicted_under_hard_byte_ceiling")
    return bool(value) if value is not None else False


def _byte_cap_controller_has_observation(row: Mapping[str, Any]) -> bool:
    controller = row.get("byte_cap_controller")
    if not isinstance(controller, Mapping):
        return False
    return int(controller.get("calibration_observation_count") or 0) > 0


def _byte_cap_controller_predicted_archive_bytes(
    row: Mapping[str, Any],
) -> int | None:
    controller = row.get("byte_cap_controller")
    if isinstance(controller, Mapping):
        value = _optional_int(controller.get("predicted_archive_bytes"))
        if value is not None:
            return value
    return _compact_first_present_int(
        row,
        (
            "nominal_total_payload_bytes",
            "total_payload_bytes",
            "estimated_total_payload_bytes",
        ),
    )


def _byte_cap_controller_predicted_headroom(row: Mapping[str, Any]) -> int:
    controller = row.get("byte_cap_controller")
    if isinstance(controller, Mapping):
        value = _optional_int(controller.get("predicted_headroom_bytes"))
        if value is not None:
            return int(value)
    value = _compact_first_present_int(row, ("byte_headroom",))
    return int(value or 0)


def _truthy_any(row: Mapping[str, Any], keys: Sequence[str]) -> bool:
    return any(row.get(key) is True for key in keys)


def _hi_nerv_modelsize_candidate_has_official_controls(row: Mapping[str, Any]) -> bool:
    """Return whether a candidate enables the official HiNeRV control spine."""

    return bool(row.get("use_hierarchical_feature_grid")) and bool(row.get("use_convnext_blocks"))


def _resolve_hi_nerv_latent_codec_policy(
    *,
    requested: str,
    hard_byte_ceiling: int | None,
) -> str:
    """Pick the HiNeRV latent codec that protects the active decoder bottleneck."""

    normalized = str(requested).strip()
    if normalized != "auto":
        return normalized
    if hard_byte_ceiling is not None and int(hard_byte_ceiling) <= 178_493:
        return "int8_brotli_q11"
    return "int16_hi_ac_brotli_q11"


def _resolve_hi_nerv_decoder_codec_policy(
    *,
    candidate: Mapping[str, Any] | None,
    requested_decoder_codec: str,
    post_export_receiver_cache_quality_gate: bool,
    segnet_direct_live_distillation_weight: float,
    segnet_direct_live_class_histogram_weight: float,
    segnet_direct_live_class_balanced_hinge_weight: float,
    segnet_direct_live_class_balanced_ce_weight: float,
    segnet_direct_live_class_balanced_squared_hinge_weight: float,
    segnet_direct_live_class_region_recon_weight: float,
    segnet_direct_live_rare_class_logit_weight: float,
    segnet_direct_live_target_mass_floor_weight: float,
    segnet_direct_live_target_min_ratio_floor_weight: float,
    pose_direct_live_distillation_weight: float,
    scorer_input_distribution_guard_attached: bool,
) -> dict[str, Any]:
    """Resolve the HiNeRV export codec as a scorer-preservation actuator.

    Modelsize candidates are rate/capacity controls.  For scorer-active runs,
    the actual receiver-visible codec is also a distortion actuator: a single
    lossy codec can satisfy nominal bytes while destroying SegNet class islands
    at export.  The mathematically useful default is therefore portfolio-auto
    receiver-survival selection under the same hard byte cap, unless the
    candidate explicitly pins the codec for a dedicated codec-ablation run.
    """

    requested = str(requested_decoder_codec).strip() or "portfolio_auto"
    candidate_mapping = dict(candidate or {})
    candidate_codec = str(candidate_mapping.get("decoder_codec") or "") if candidate_mapping else None
    direct_live_weights = (
        float(segnet_direct_live_distillation_weight),
        float(segnet_direct_live_class_histogram_weight),
        float(segnet_direct_live_class_balanced_hinge_weight),
        float(segnet_direct_live_class_balanced_ce_weight),
        float(segnet_direct_live_class_balanced_squared_hinge_weight),
        float(segnet_direct_live_class_region_recon_weight),
        float(segnet_direct_live_rare_class_logit_weight),
        float(segnet_direct_live_target_mass_floor_weight),
        float(segnet_direct_live_target_min_ratio_floor_weight),
    )
    scorer_active = bool(
        any(weight > 0.0 for weight in direct_live_weights)
        or float(pose_direct_live_distillation_weight) > 0.0
        or bool(scorer_input_distribution_guard_attached)
    )
    explicit_pin = bool(
        candidate_mapping.get("decoder_codec_pinned")
        or candidate_mapping.get("pin_decoder_codec")
        or candidate_mapping.get("force_decoder_codec")
        or candidate_mapping.get("single_decoder_codec_ablation")
    )
    portfolio_intervened = bool(
        candidate_mapping
        and bool(post_export_receiver_cache_quality_gate)
        and scorer_active
        and requested != "portfolio_auto"
        and not explicit_pin
    )
    resolved = "portfolio_auto" if portfolio_intervened else requested
    return {
        "schema": "compact_hi_nerv_decoder_codec_policy.v1",
        "candidate_decoder_codec": candidate_codec,
        "requested_decoder_codec": requested,
        "resolved_decoder_codec": resolved,
        "portfolio_auto_intervened": portfolio_intervened,
        "post_export_receiver_cache_quality_gate": bool(post_export_receiver_cache_quality_gate),
        "scorer_active": scorer_active,
        "explicit_pin": explicit_pin,
        "policy": (
            "score_preserving_receiver_survival_portfolio_under_byte_cap"
            if portfolio_intervened
            else ("explicit_single_codec_ablation" if explicit_pin else "requested_codec")
        ),
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }


_HINERV_MODEL_SIZE_ID_RE = re.compile(
    r"^hinerv_np(?P<num_pairs>\d+)_ld(?P<latent_dim>\d+)_"
    r"ed(?P<embed_dim>\d+)_dc(?P<decoder_channel>\d+)"
    r"(?:_mi(?P<mid_injection_block_index>\d+)fi(?P<fine_injection_block_index>\d+))?"
    r"(?P<control_suffix>(?:_hfg)?(?:_cnx)?)_"
    r"(?:(?:lg(?P<local_grid_levels>\d+)c(?P<local_grid_channels>\d+)_"
    r"cx(?P<convnext_mlp_ratio>\d+)k(?P<convnext_kernel_size>\d+)_))?"
    r"(?P<decoder_codec>.+)_ceil(?P<hard_byte_ceiling>\d+)"
    r"(?:_tgtmp(?P<target_modelsize>\d+(?:p\d+)?))?$"
)
_SNERV_MODEL_SIZE_ID_RE = re.compile(
    r"^snerv_np(?P<num_pairs>\d+)_(?P<wavelet>[A-Za-z0-9]+)_"
    r"lv(?P<levels>\d+)_"
    r"lfb(?P<bits_per_coeff>\d+(?:p\d+)?)_"
    r"stepb(?P<step_map_bits_per_coeff>\d+(?:p\d+)?)_"
    r"fc(?P<fc_dim>\d+)e(?P<emb_size>\d+)_"
    r"p(?P<patch_radius>\d+)_"
    r"mfu(?P<mfu_scales>\d+(?:-\d+)*)_"
    r"hfr(?P<hfr_gain>\d+(?:p\d+)?)_"
    r"t(?P<temporal_context>\d+)(?:_tm(?P<temporal_mode_token>[A-Za-z0-9]+))?_"
    r"ad(?P<adapter_token>[A-Za-z0-9]+)"
    r"(?:_oms(?P<official_modelsize>\d+(?:p\d+)?))?_"
    r"(?:(?:sk|_sk)(?P<official_skip_high_mode_token>[A-Za-z0-9]+)_)?"
    r"(?P<decoder_payload_codec>.+)_ceil(?P<hard_byte_ceiling>\d+)$"
)
_SNERV_PARTIAL_MODEL_SIZE_ID_RE = re.compile(
    r"^snerv_np(?P<num_pairs>\d+)_(?P<wavelet>[A-Za-z0-9]+)_"
    r"lv(?P<levels>\d+)_"
    r"lfb(?P<bits_per_coeff>\d+(?:p\d+)?)_"
    r"stepb(?P<step_map_bits_per_coeff>\d+(?:p\d+)?)_"
    r"fc(?P<fc_dim>\d+)e(?P<emb_size>\d+)_"
    r"(?!(?:p\d+_mfu))"
    r"(?P<decoder_payload_codec>.+)_ceil(?P<hard_byte_ceiling>\d+)$"
)
_SNERV_LEGACY_MODEL_SIZE_ID_RE = re.compile(
    r"^snerv_np(?P<num_pairs>\d+)_lv(?P<levels>\d+)_"
    r"lfb(?P<bits_per_coeff>\d+(?:p\d+)?)_"
    r"stepb(?P<step_map_bits_per_coeff>\d+(?:p\d+)?)_"
    r"(?P<decoder_payload_codec>.+)_ceil(?P<hard_byte_ceiling>\d+)$"
)


def _float_token(value: str) -> float:
    return float(value.replace("p", "."))


def _snerv_official_skip_high_mode_from_id_token(token: str | None) -> str:
    if token is None:
        return "full"
    normalized = str(token).strip().lower()
    token_to_mode = {
        "sharedmean": "shared_mean",
        "channelmean": "channel_mean",
        "scalarmean": "scalar_mean",
    }
    mode = token_to_mode.get(normalized, normalized)
    if mode not in SNERV_OFFICIAL_SKIP_HIGH_MODES:
        raise CompactRendererMlxSpineRunnerError(
            "SNeRV modelsize candidate official_skip_high_mode token must decode "
            f"to one of {sorted(SNERV_OFFICIAL_SKIP_HIGH_MODES)}; got {token!r}"
        )
    return mode


def _modelsize_candidate_from_self_describing_id(
    *,
    family: str,
    candidate_id: str,
) -> dict[str, Any] | None:
    """Rebuild a queue-owned candidate from its stable self-describing id.

    The long-campaign queue stores the candidate id as custody. Execution must
    not depend on rerunning the same planner ceiling list: otherwise a valid
    queue can become unlaunchable after harmless planner-default changes. The
    id grammar is generated by ``tac.analysis.nerv_modelsize_budget``; this
    helper parses that grammar, reuses the canonical analyzer, then verifies the
    round-trip id before returning an executable row.
    """

    token = str(candidate_id).strip()
    if family == "hi_nerv":
        match = _HINERV_MODEL_SIZE_ID_RE.match(token)
        if match is None:
            return None
        control_suffix = match.group("control_suffix") or ""
        row_obj = analyze_hinerv_modelsize_candidate(
            hard_byte_ceiling=int(match.group("hard_byte_ceiling")),
            num_pairs=int(match.group("num_pairs")),
            latent_dim=int(match.group("latent_dim")),
            embed_dim=int(match.group("embed_dim")),
            decoder_channel=int(match.group("decoder_channel")),
            decoder_codec=match.group("decoder_codec"),
            use_hierarchical_feature_grid="_hfg" in control_suffix,
            use_convnext_blocks="_cnx" in control_suffix,
            local_grid_levels=int(match.group("local_grid_levels") or 2),
            local_grid_channels=int(match.group("local_grid_channels") or 4),
            convnext_mlp_ratio=int(match.group("convnext_mlp_ratio") or 2),
            convnext_kernel_size=int(match.group("convnext_kernel_size") or 7),
            mid_injection_block_index=int(
                match.group("mid_injection_block_index") or HINERV_COMPACT_MID_INJECTION_BLOCK_INDEX
            ),
            fine_injection_block_index=int(
                match.group("fine_injection_block_index") or HINERV_COMPACT_FINE_INJECTION_BLOCK_INDEX
            ),
        )
        target_modelsize = match.group("target_modelsize")
        if target_modelsize is not None:
            row_obj = tag_hinerv_target_modelsize_candidate(
                row_obj,
                target_modelsize_mparams=_float_token(target_modelsize),
            )
        row = row_obj.as_dict()
        if row["candidate_id"] != token:
            row["canonical_candidate_id"] = row["candidate_id"]
            row["candidate_id"] = token
            row["legacy_candidate_id"] = True
            row["blockers"] = [
                *list(row.get("blockers") or []),
                "legacy_hinerv_modelsize_candidate_id_missing_graph_controls",
            ]
    elif family == "snerv":
        match = _SNERV_MODEL_SIZE_ID_RE.match(token)
        partial_match = _SNERV_PARTIAL_MODEL_SIZE_ID_RE.match(token)
        legacy_match = _SNERV_LEGACY_MODEL_SIZE_ID_RE.match(token)
        if match is None and partial_match is None and legacy_match is None:
            return None
        matched = match or partial_match or legacy_match
        if matched is None:  # pragma: no cover - defensive for type checkers
            return None
        groups = matched.groupdict()
        parsed_bits_per_coeff = _float_token(matched.group("bits_per_coeff"))
        parsed_step_map_bits_per_coeff = _float_token(matched.group("step_map_bits_per_coeff"))
        parsed_adapter = (
            snerv_model_size_adapter_from_id_token(matched.group("adapter_token"))
            if "adapter_token" in groups
            else DEFAULT_SNERV_MODEL_SIZE_ADAPTER
        )
        parsed_official_modelsize_mparams = (
            _float_token(groups["official_modelsize"]) if groups.get("official_modelsize") is not None else None
        )
        parsed_temporal_mode = (
            snerv_temporal_mode_from_id_token(groups["temporal_mode_token"])
            if groups.get("temporal_mode_token") is not None
            else "delta"
        )
        parsed_official_skip_high_mode_token = groups.get("official_skip_high_mode_token")
        parsed_official_skip_high_mode = _snerv_official_skip_high_mode_from_id_token(
            parsed_official_skip_high_mode_token
        )
        row = analyze_snerv_modelsize_candidate(
            hard_byte_ceiling=int(matched.group("hard_byte_ceiling")),
            num_pairs=int(matched.group("num_pairs")),
            wavelet=(matched.group("wavelet") if "wavelet" in matched.groupdict() else "db2"),
            levels=int(matched.group("levels")),
            bits_per_coeff=parsed_bits_per_coeff,
            step_map_bits_per_coeff=parsed_step_map_bits_per_coeff,
            decoder_payload_codec=matched.group("decoder_payload_codec"),
            fc_dim=(int(matched.group("fc_dim")) if "fc_dim" in matched.groupdict() else 9),
            emb_size=(int(matched.group("emb_size")) if "emb_size" in groups else 0),
            patch_radius=(int(matched.group("patch_radius")) if "patch_radius" in groups else 1),
            mfu_scales=(
                tuple(int(v) for v in matched.group("mfu_scales").split("-")) if "mfu_scales" in groups else (1, 2, 4)
            ),
            hfr_gain=(_float_token(matched.group("hfr_gain")) if "hfr_gain" in groups else 0.0),
            temporal_context=(int(matched.group("temporal_context")) if "temporal_context" in groups else 0),
            temporal_mode=parsed_temporal_mode,
            snerv_model_size_adapter=parsed_adapter,
            official_modelsize_mparams=parsed_official_modelsize_mparams,
            official_skip_high_mode=parsed_official_skip_high_mode,
        ).as_dict()
        if partial_match is not None or legacy_match is not None:
            row["candidate_id"] = token
            row["legacy_candidate_id"] = True
        elif row["candidate_id"] != token:
            requested_bit_id = snerv_modelsize_candidate_id_from_controls(
                num_pairs=int(row["num_pairs"]),
                wavelet=str(row["wavelet"]),
                levels=int(row["levels"]),
                bits_per_coeff=parsed_bits_per_coeff,
                step_map_bits_per_coeff=parsed_step_map_bits_per_coeff,
                fc_dim=int(row["fc_dim"]),
                emb_size=int(row["emb_size"]),
                patch_radius=int(row["patch_radius"]),
                mfu_scales=tuple(int(v) for v in row["mfu_scales"]),
                hfr_gain=float(row["hfr_gain"]),
                temporal_context=int(row["temporal_context"]),
                temporal_mode=str(row["temporal_mode"]),
                official_skip_high_mode=str(row["official_skip_high_mode"]),
                snerv_model_size_adapter=str(row["snerv_model_size_adapter"]),
                decoder_payload_codec=str(row["decoder_payload_codec"]),
                hard_byte_ceiling=int(row["hard_byte_ceiling"]),
                official_modelsize_mparams=parsed_official_modelsize_mparams,
            )
            if (
                str(row.get("snerv_model_size_adapter")) == SNERV_OFFICIAL_MFU_HFR_TUB_PRIMITIVES_ADAPTER
                and requested_bit_id == token
            ):
                row["canonical_candidate_id"] = row["candidate_id"]
                row["candidate_id"] = token
                row["legacy_requested_lf_bit_candidate_id"] = True
                row["requested_bits_per_coeff_from_candidate_id"] = float(parsed_bits_per_coeff)
                row["requested_step_map_bits_per_coeff_from_candidate_id"] = float(parsed_step_map_bits_per_coeff)
                row["bits_per_coeff"] = float(parsed_bits_per_coeff)
                row["step_map_bits_per_coeff"] = float(parsed_step_map_bits_per_coeff)
            else:
                return None
        if (
            str(row.get("snerv_model_size_adapter")) == SNERV_OFFICIAL_MFU_HFR_TUB_PRIMITIVES_ADAPTER
            and parsed_official_skip_high_mode_token is None
            and str(row.get("official_skip_high_mode")) == "full"
        ):
            row["official_skip_high_mode_token_missing"] = True
            row["implicit_official_skip_high_mode"] = "full"
            row["blockers"] = [
                *list(row.get("blockers") or []),
                "official_snerv_skip_high_mode_token_missing_full_is_diagnostic_only",
            ]
    else:
        return None
    if row["candidate_id"] != token:
        raise CompactRendererMlxSpineRunnerError(
            f"{family} --modelsize-candidate-id {token!r} did not round-trip "
            f"through the canonical modelsize analyzer; rebuilt {row['candidate_id']!r}"
        )
    return row


def _int_tuple_from_candidate_value(value: Any) -> tuple[int, ...]:
    if value is None:
        return ()
    if isinstance(value, str):
        return tuple(int(v) for v in re.split(r"[x,]", value) if v.strip())
    return tuple(int(v) for v in value)


def _float_tuple_from_candidate_value(value: Any) -> tuple[float, ...]:
    if value is None:
        return ()
    if isinstance(value, str):
        return tuple(float(v) for v in re.split(r"[,]", value) if v.strip())
    return tuple(float(v) for v in value)


def _resolve_snerv_execution_fc_dim(
    candidate: Mapping[str, Any],
    *,
    cli_override: int | None,
    fallback: int,
) -> int:
    """Resolve the receiver-visible SNeRV fc_dim at launch time."""

    return _resolve_snerv_execution_fc_dim_with_source(
        candidate,
        cli_override=cli_override,
        fallback=fallback,
    )[0]


def _resolve_snerv_execution_fc_dim_with_source(
    candidate: Mapping[str, Any],
    *,
    cli_override: int | None,
    fallback: int,
) -> tuple[int, str]:
    """Resolve SNeRV fc_dim plus provenance for launch-control telemetry."""

    solution = candidate.get("official_modelsize_solution")
    if isinstance(solution, Mapping):
        solved = _compact_positive_int_from_keys(solution, ("fc_dim", "snerv_fc_dim"))
        if solved is not None:
            return int(solved), "official_modelsize_solution"
    modelsize = _compact_finite_float_from_keys(
        candidate,
        ("modelsize_mparams", "official_modelsize_mparams"),
    )
    if modelsize is not None:
        carrier_hw = _int_tuple_from_candidate_value(candidate.get("carrier_hw") or (384, 512))
        profile = candidate.get("modelsize_control_profile")
        enc_strds = candidate.get("enc_strds", candidate.get("official_enc_strds"))
        dec_strds = candidate.get("dec_strds", candidate.get("official_dec_strds"))
        if isinstance(profile, Mapping):
            enc_strds = enc_strds or profile.get("enc_strds")
            dec_strds = dec_strds or profile.get("dec_strds")
        enc_tuple = _int_tuple_from_candidate_value(enc_strds)
        dec_tuple = _int_tuple_from_candidate_value(dec_strds)
        if len(carrier_hw) == 2 and enc_tuple and dec_tuple:
            return int(
                official_snerv_modelsize_to_fc_dim(
                    modelsize_mparams=float(modelsize),
                    full_data_length=int(candidate.get("num_pairs", 600)) * 2,
                    final_size=int(carrier_hw[0]) * int(carrier_hw[1]),
                    enc_strds=enc_tuple,
                    dec_strds=dec_tuple,
                    ks=_int_tuple_from_candidate_value(candidate.get("ks", (0, 1, 5))),
                    enc_dim=_float_tuple_from_candidate_value(candidate.get("enc_dim", (64.0, 16.0))),
                    emb_size=int(candidate.get("emb_size", candidate.get("snerv_emb_size", 0))),
                    reduce=float(candidate.get("reduce", 1.2)),
                    lower_width=int(candidate.get("lower_width", 12)),
                    saturate_stages=int(candidate.get("saturate_stages", -1)),
                ).fc_dim
            ), "official_modelsize_formula"
        missing = [
            key
            for key, value in (
                ("carrier_hw", carrier_hw if len(carrier_hw) == 2 else None),
                ("enc_strds/official_enc_strds", enc_tuple or None),
                ("dec_strds/official_dec_strds", dec_tuple or None),
            )
            if value is None
        ]
        raise CompactRendererMlxSpineRunnerError(
            "SNeRV modelsize_mparams requires official_modelsize_solution or "
            "official formula controls; missing " + ", ".join(missing)
        )
    explicit = _compact_positive_int_from_keys(candidate, ("fc_dim", "snerv_fc_dim"))
    if explicit is not None:
        return int(explicit), "explicit_candidate_fc_dim"
    if cli_override is not None:
        return int(cli_override), "manual_cli_override"
    return int(fallback), "fallback_default_missing_official_modelsize_inputs"


def _modelsize_control_contract(
    candidate: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """Return canonical modelsize-control semantics without inventing authority."""

    if not candidate:
        return None
    contract = candidate.get("modelsize_control_contract")
    if not isinstance(contract, Mapping):
        return None
    out = dict(contract)
    out.setdefault(
        "control_precedence",
        modelsize_control_precedence_contract(candidate),
    )
    return out


def _write_snerv_binary_profile_attachment(
    *,
    archive_path: str | Path | None,
    output_dir: str | Path,
    repo_root: str | Path,
) -> dict[str, Any]:
    """Write a SNeRV binary profile, fail-closed if unavailable."""

    out = Path(output_dir).expanduser().resolve(strict=False)
    if archive_path is None or str(archive_path).strip() == "":
        return {
            "schema": "compact_runner_snerv_binary_profile_attachment.v1",
            "profile_written": False,
            "blockers": ["snerv_binary_profile_archive_path_missing"],
            "score_claim": False,
            "promotion_eligible": False,
            "ready_for_exact_eval_dispatch": False,
        }
    profile_path = out / "snerv_binary_profile.json"
    try:
        resolved_archive = _resolve(archive_path, base=Path(repo_root))
        profile = write_snerv_binary_profile(
            input_path=resolved_archive,
            output_path=profile_path,
        )
    except (
        OSError,
        SnervArchiveError,
        SnervBinaryProfileError,
        ValueError,
        zipfile.BadZipFile,
    ) as exc:
        return {
            "schema": "compact_runner_snerv_binary_profile_attachment.v1",
            "profile_written": False,
            "profile_path": profile_path.as_posix(),
            "blockers": [f"snerv_binary_profile_failed:{exc}"],
            "score_claim": False,
            "promotion_eligible": False,
            "ready_for_exact_eval_dispatch": False,
        }
    lf_profile = dict(profile.get("lf_quant_profile") or {})
    return {
        "schema": "compact_runner_snerv_binary_profile_attachment.v1",
        "profile_written": True,
        "profile_path": profile_path.as_posix(),
        "verdict": profile.get("verdict"),
        "charged_archive_bytes": profile.get("charged_archive_bytes"),
        "snar1_packet_bytes": profile.get("snar1_packet_bytes"),
        "lf_payload_bytes": lf_profile.get("section_bytes"),
        "lf_payload_fraction_of_packet": lf_profile.get("section_fraction_of_packet"),
        "lf_payload_bytes_per_coeff": lf_profile.get("bytes_per_coeff"),
        "blockers": list(profile.get("blockers") or []),
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }


def _run_snerv_scorer_loop_qat_attachment(
    *,
    requested: bool,
    output_dir: str | Path,
    num_pairs: int,
    levels: int,
    wavelet: str,
    target_bits_per_coeff: float,
    source_video_path: str | Path,
    upstream_dir: str | Path,
    distillation_device: str,
    step_map_bins: int,
    qat_bits: int,
    decoder_payload_codec: str,
    lf_payload_codec: str,
    snerv_spectra_preserving_adapter: bool,
    snerv_model_size_adapter: str,
    snerv_fc_dim: int,
    snerv_emb_size: int,
    snerv_patch_radius: int,
    snerv_mfu_scales: tuple[int, ...],
    snerv_hfr_gain: float,
    snerv_temporal_context: int,
    snerv_temporal_mode: str,
    max_trials: int,
    search_mode: str,
    perturb_scale: float,
    byte_pressure_multiplier: float,
    section_value_pressure_multiplier: float,
    max_archive_byte_growth: int | None,
    byte_growth_admission_mode: str,
    pose_slack: float,
    seg_slack: float,
    pair_stride: int,
    start_pair: int,
    prioritized_pair_indices: tuple[int, ...],
    pair_guard_min_score_improved_fraction: float,
    pair_guard_max_pose_worsened_fraction: float,
    component_guard_mode: str,
    seed: int,
) -> dict[str, Any]:
    """Run SNeRV receiver-priced scorer-loop QAT and persist its result.

    This is executable score-aware evidence for the SNeRV carrier, but it is not
    native MLX training and it never becomes promotion authority by itself.
    """

    attachment_dir = Path(output_dir).expanduser().resolve(strict=False)
    result_path = attachment_dir / "snerv_scorer_loop_qat_result.json"
    progress_path = attachment_dir / "snerv_scorer_loop_qat_progress.jsonl"
    attachment_dir.mkdir(parents=True, exist_ok=True)
    if not requested:
        payload = {
            "schema": "compact_runner_snerv_scorer_loop_qat_attachment.v1",
            "executed": False,
            "requested": False,
            "component_guard_mode": str(component_guard_mode),
            "decoder_payload_codec": str(decoder_payload_codec),
            "lf_payload_codec": str(lf_payload_codec),
            "perturb_scale": float(perturb_scale),
            "byte_pressure_multiplier": float(byte_pressure_multiplier),
            "section_value_pressure_multiplier": float(section_value_pressure_multiplier),
            "max_archive_byte_growth": (None if max_archive_byte_growth is None else int(max_archive_byte_growth)),
            "byte_growth_admission_mode": str(byte_growth_admission_mode),
            "pose_slack": float(pose_slack),
            "seg_slack": float(seg_slack),
            "seed": int(seed),
            "blockers": ["snerv_scorer_loop_qat_not_requested"],
            "score_claim": False,
            "promotion_eligible": False,
            "rank_or_kill_eligible": False,
            "ready_for_exact_eval_dispatch": False,
        }
        _write_json(result_path, payload)
        return {**payload, "result_path": result_path.as_posix()}

    try:
        from tac.substrates.snerv_inverse_steg_carrier import (
            scorer_loop_decoder_qat as qat_mod,
        )

        result = qat_mod.run_snerv_scorer_loop_decoder_qat(
            n_pairs=int(num_pairs),
            levels=int(levels),
            wavelet=str(wavelet),
            target_bits_per_coeff=float(target_bits_per_coeff),
            pair_stride=int(pair_stride),
            start_pair=int(start_pair),
            pair_indices=(
                tuple(int(value) for value in prioritized_pair_indices) if prioritized_pair_indices else None
            ),
            upstream_dir=Path(upstream_dir).as_posix(),
            video_path=Path(source_video_path).as_posix(),
            device=str(distillation_device),
            step_map_bins=int(step_map_bins),
            snerv_spectra_preserving_adapter=bool(snerv_spectra_preserving_adapter),
            snerv_model_size_adapter=str(snerv_model_size_adapter),
            snerv_fc_dim=int(snerv_fc_dim),
            snerv_emb_size=int(snerv_emb_size),
            snerv_patch_radius=int(snerv_patch_radius),
            snerv_mfu_scales=tuple(int(v) for v in snerv_mfu_scales),
            snerv_hfr_gain=float(snerv_hfr_gain),
            snerv_temporal_context=int(snerv_temporal_context),
            snerv_temporal_mode=str(snerv_temporal_mode),
            decoder_payload_codec=str(decoder_payload_codec),
            lf_payload_codec=str(lf_payload_codec),
            qat_bits=int(qat_bits),
            max_trials=int(max_trials),
            search_mode=str(search_mode),
            perturb_scale=float(perturb_scale),
            byte_pressure_multiplier=float(byte_pressure_multiplier),
            section_value_pressure_multiplier=float(section_value_pressure_multiplier),
            max_archive_byte_growth=(None if max_archive_byte_growth is None else int(max_archive_byte_growth)),
            byte_growth_admission_mode=str(byte_growth_admission_mode),
            pose_slack=float(pose_slack),
            seg_slack=float(seg_slack),
            pair_guard_min_score_improved_fraction=float(pair_guard_min_score_improved_fraction),
            pair_guard_max_pose_worsened_fraction=float(pair_guard_max_pose_worsened_fraction),
            component_guard_mode=str(component_guard_mode),
            seed=int(seed),
            progress_callback=_snerv_scorer_loop_progress_callback(progress_path),
        )
        result_payload = result.as_jsonable() if hasattr(result, "as_jsonable") else dict(result)
        blockers = list(result_payload.get("blockers") or [])
        if int(num_pairs) < CONTEST_PAIR_COUNT:
            blockers.append("snerv_scorer_loop_qat_partial_pair_coverage")
        payload = {
            "schema": "compact_runner_snerv_scorer_loop_qat_attachment.v1",
            "executed": True,
            "requested": True,
            "axis_tag": "[macOS-CPU advisory]",
            "n_pairs": int(num_pairs),
            "source_pair_indices": [int(value) for value in result_payload.get("source_pair_indices") or []],
            "prioritized_pair_training": {
                "schema": "compact_snerv_prioritized_pair_training.v1",
                "enabled": bool(prioritized_pair_indices),
                "pair_indices": [int(value) for value in prioritized_pair_indices],
                "pair_count": len(prioritized_pair_indices),
                "consumed_by_cpu_advisory_qat": bool(prioritized_pair_indices),
                "sampling_scope": "snerv_cpu_advisory_and_scorer_loop_qat_pair_subset",
                **FALSE_AUTHORITY,
            },
            "levels": int(levels),
            "wavelet": str(wavelet),
            "target_bits_per_coeff": float(target_bits_per_coeff),
            "snerv_model_size_adapter": str(snerv_model_size_adapter),
            "snerv_spectra_preserving_adapter": bool(snerv_spectra_preserving_adapter),
            "snerv_fc_dim": int(snerv_fc_dim),
            "snerv_emb_size": int(snerv_emb_size),
            "snerv_patch_radius": int(snerv_patch_radius),
            "snerv_mfu_scales": [int(v) for v in snerv_mfu_scales],
            "snerv_hfr_gain": float(snerv_hfr_gain),
            "snerv_temporal_context": int(snerv_temporal_context),
            "snerv_temporal_mode": str(snerv_temporal_mode),
            "qat_bits": int(qat_bits),
            "lf_payload_codec": str(result_payload.get("lf_payload_codec") or lf_payload_codec),
            "max_trials": int(max_trials),
            "search_mode": str(search_mode),
            "component_guard_mode": str(result_payload.get("component_guard_mode") or component_guard_mode),
            "perturb_scale": float(perturb_scale),
            "byte_pressure_multiplier": float(byte_pressure_multiplier),
            "section_value_pressure_multiplier": float(section_value_pressure_multiplier),
            "max_archive_byte_growth": (None if max_archive_byte_growth is None else int(max_archive_byte_growth)),
            "byte_growth_admission_mode": str(byte_growth_admission_mode),
            "pose_slack": float(pose_slack),
            "seg_slack": float(seg_slack),
            "seed": int(seed),
            "pair_robust_admission": result_payload.get("pair_robust_admission"),
            "result": result_payload,
            "accepted_improvement": bool(result_payload.get("accepted_improvement")),
            "receiver_contract_satisfied": bool(result_payload.get("receiver_contract_satisfied")),
            "ready_for_pose_guard_gate": bool(result_payload.get("ready_for_pose_guard_gate")),
            "improvement_score_delta": result_payload.get("improvement_score_delta"),
            "improvement_d_pose_delta": result_payload.get("improvement_d_pose_delta"),
            "improvement_d_seg_delta": result_payload.get("improvement_d_seg_delta"),
            "scorer_loop_evaluations": result_payload.get("scorer_loop_evaluations"),
            "progress_jsonl_path": progress_path.as_posix(),
            "progress_jsonl_sha256": (_sha256_file(progress_path) if progress_path.is_file() else None),
            "blockers": _dedupe(blockers),
            "score_claim": False,
            "promotion_eligible": False,
            "rank_or_kill_eligible": False,
            "ready_for_exact_eval_dispatch": False,
        }
    except Exception as exc:  # pragma: no cover - covered through runner contract
        payload = {
            "schema": "compact_runner_snerv_scorer_loop_qat_attachment.v1",
            "executed": False,
            "requested": True,
            "failure": repr(exc),
            "component_guard_mode": str(component_guard_mode),
            "decoder_payload_codec": str(decoder_payload_codec),
            "lf_payload_codec": str(lf_payload_codec),
            "byte_growth_admission_mode": str(byte_growth_admission_mode),
            "progress_jsonl_path": progress_path.as_posix(),
            "blockers": ["snerv_scorer_loop_qat_failed"],
            "score_claim": False,
            "promotion_eligible": False,
            "rank_or_kill_eligible": False,
            "ready_for_exact_eval_dispatch": False,
        }
    _write_json(result_path, payload)
    return {
        **payload,
        "result_path": result_path.as_posix(),
        "result_sha256": _sha256_file(result_path),
    }


def _run_snerv_score_aware_long_training_scorer_tether_gate(
    *,
    attachment_dir: Path,
    required: bool,
    steps: int,
) -> dict[str, Any]:
    gate_path = attachment_dir / "snerv_scorer_tether_smoke_gate.json"
    normalized_steps = max(int(steps), 0)
    if not required:
        payload = {
            "schema": "snerv_score_aware_long_training_scorer_tether_gate.v1",
            "required": False,
            "executed": False,
            "passed": True,
            "steps": normalized_steps,
            "status": "not_required_without_score_aware_long_training",
            "blockers": [],
            **FALSE_AUTHORITY,
        }
        _write_json(gate_path, payload)
        return {
            **payload,
            "gate_path": gate_path.as_posix(),
            "gate_sha256": _sha256_file(gate_path),
        }

    try:
        report = run_snerv_scorer_tether_smoke(steps=normalized_steps)
    except Exception as exc:  # pragma: no cover - defensive launcher gate
        report = {
            "schema": "snerv_scorer_tether_smoke.v1",
            "passed": False,
            "steps": normalized_steps,
            "failure": repr(exc),
            "blockers": [
                "snerv_scorer_tether_smoke_exception_before_long_training",
                f"snerv_scorer_tether_smoke_exception_type:{type(exc).__name__}",
            ],
            **FALSE_AUTHORITY,
        }
    blockers = [str(blocker) for blocker in report.get("blockers") or [] if str(blocker)]
    if report.get("passed") is not True:
        blockers.insert(0, "snerv_scorer_tether_smoke_failed_before_long_training")
    payload = {
        "schema": "snerv_score_aware_long_training_scorer_tether_gate.v1",
        "required": True,
        "executed": True,
        "passed": report.get("passed") is True,
        "steps": normalized_steps,
        "smoke_schema": report.get("schema"),
        "smoke_report": report,
        "blockers": _dedupe(blockers),
        **FALSE_AUTHORITY,
    }
    _write_json(gate_path, payload)
    return {
        **payload,
        "gate_path": gate_path.as_posix(),
        "gate_sha256": _sha256_file(gate_path),
    }


def _snerv_score_aware_long_training_required_control_contract(
    *,
    executed: bool,
    score_aware_long_training: Mapping[str, Any],
    training_telemetry_contract: Mapping[str, Any] | None,
    scorer_input_distribution_guard_weight: float,
    scorer_input_contrast_floor_weight: float,
    scorer_input_shape_tether_weight: float,
    posenet_yuv6_geometry_tether_weight: float,
    posenet_temporal_signal_floor_weight: float,
) -> dict[str, Any]:
    """Require configured SNeRV scorer-domain controls to appear in telemetry."""

    telemetry = training_telemetry_contract if isinstance(training_telemetry_contract, Mapping) else None
    definitions = (
        {
            "control_id": "scorer_input_distribution_guard",
            "weight": float(scorer_input_distribution_guard_weight),
            "bound_key": "scorer_input_distribution_guard_bound",
            "expected_key": "expected_scorer_input_guard_metric",
            "observed_keys": (
                "scorer_input_guard_metric_observed",
                "scorer_input_guard_dual_metric_observed",
            ),
        },
        {
            "control_id": "scorer_input_contrast_floor",
            "weight": float(scorer_input_contrast_floor_weight),
            "bound_key": "scorer_input_contrast_floor_bound",
            "expected_key": "expected_scorer_input_contrast_floor_metric",
            "observed_keys": (
                "scorer_input_contrast_floor_metric_observed",
                "scorer_input_contrast_floor_segnet_ratio_metric_observed",
                "scorer_input_contrast_floor_posenet_ratio_metric_observed",
            ),
        },
        {
            "control_id": "scorer_input_shape_tether",
            "weight": float(scorer_input_shape_tether_weight),
            "bound_key": "scorer_input_shape_tether_bound",
            "expected_key": "expected_scorer_input_shape_tether_metric",
            "observed_keys": (
                "scorer_input_shape_tether_metric_observed",
                "scorer_input_shape_tether_segnet_metric_observed",
                "scorer_input_shape_tether_posenet_pair_metric_observed",
                "scorer_input_shape_tether_posenet_delta_metric_observed",
            ),
        },
        {
            "control_id": "posenet_yuv6_geometry_tether",
            "weight": float(posenet_yuv6_geometry_tether_weight),
            "bound_key": "posenet_yuv6_geometry_tether_bound",
            "expected_key": "expected_posenet_yuv6_geometry_tether_metric",
            "observed_keys": (
                "posenet_yuv6_geometry_tether_metric_observed",
                "posenet_yuv6_geometry_tether_pair_metric_observed",
                "posenet_yuv6_geometry_tether_delta_metric_observed",
            ),
        },
        {
            "control_id": "posenet_temporal_signal_floor",
            "weight": float(posenet_temporal_signal_floor_weight),
            "bound_key": "posenet_temporal_signal_floor_bound",
            "expected_key": "expected_posenet_temporal_signal_floor_metric",
            "observed_keys": (
                "posenet_temporal_signal_floor_metric_observed",
                "posenet_temporal_signal_floor_std_ratio_metric_observed",
                "posenet_temporal_signal_floor_mean_abs_ratio_metric_observed",
            ),
        },
    )
    controls: dict[str, Any] = {}
    blockers: list[str] = []
    for definition in definitions:
        control_id = str(definition["control_id"])
        weight = float(definition["weight"])
        required = bool(executed and weight > 0.0)
        bound_key = str(definition["bound_key"])
        bound = bool(score_aware_long_training.get(bound_key) is True)
        expected_key = str(definition["expected_key"])
        observed_keys = tuple(str(key) for key in definition["observed_keys"])
        telemetry_expected = bool(telemetry is not None and telemetry.get(expected_key) is True)
        observed = {key: bool(telemetry is not None and telemetry.get(key) is True) for key in observed_keys}
        telemetry_observed = bool(telemetry_expected and all(observed.values()))
        control_passed = bool(not required or (bound and telemetry_observed))
        controls[control_id] = {
            "required": required,
            "configured_weight": weight,
            "bound": bound,
            "bound_key": bound_key,
            "telemetry_expected_key": expected_key,
            "telemetry_expected": telemetry_expected,
            "telemetry_observed": telemetry_observed,
            "telemetry_observed_keys": observed,
            "passed": control_passed,
        }
        if not required:
            continue
        if not bound:
            blockers.append(f"snerv_score_aware_long_training_{control_id}_required_control_not_bound")
        if telemetry is None:
            blockers.append("snerv_score_aware_long_training_required_control_telemetry_contract_missing")
        elif telemetry.get("passed") is not True:
            blockers.append("snerv_score_aware_long_training_required_control_telemetry_contract_failed")
        elif not telemetry_observed:
            blockers.append(f"snerv_score_aware_long_training_{control_id}_required_telemetry_missing")
    blockers = _dedupe(blockers)
    return {
        "schema": "snerv_score_aware_long_training_required_control_contract.v1",
        "executed": bool(executed),
        "passed": not blockers,
        "controls": controls,
        "blockers": blockers,
        **FALSE_AUTHORITY,
    }


def _snerv_score_aware_long_training_artifact_path(
    score_aware_long_training: Mapping[str, Any],
) -> Path | None:
    for key in ("training_artifact_path", "artifact_path"):
        raw = score_aware_long_training.get(key)
        if isinstance(raw, str) and raw:
            return Path(raw).expanduser().resolve(strict=False)
    telemetry_path = score_aware_long_training.get("telemetry_path")
    if isinstance(telemetry_path, str) and telemetry_path:
        return Path(telemetry_path).expanduser().resolve(strict=False).parent / "training_artifact.json"
    return None


def _write_snerv_runner_crux_trace(
    *,
    artifact: dict[str, Any],
    score_aware_long_training: dict[str, Any],
) -> dict[str, Any]:
    training_artifact_path = _snerv_score_aware_long_training_artifact_path(score_aware_long_training)
    if training_artifact_path is None:
        return {
            "schema": "snerv_runner_crux_trace_attachment.v1",
            "written": False,
            "blockers": ["snerv_score_aware_training_artifact_path_missing"],
            **FALSE_AUTHORITY,
        }
    trace_path = training_artifact_path.parent / "nerv_crux_trace_rows.json"
    if not training_artifact_path.is_file():
        return {
            "schema": "snerv_runner_crux_trace_attachment.v1",
            "written": False,
            "path": trace_path.as_posix(),
            "source_path": training_artifact_path.as_posix(),
            "blockers": ["snerv_score_aware_training_artifact_missing_for_crux_trace"],
            **FALSE_AUTHORITY,
        }
    try:
        trace = write_trace_rows_for_training_artifact(
            training_artifact_path,
            output_path=trace_path,
            require_direct_live_posenet=True,
            require_direct_live_segnet=True,
        )
    except Exception as exc:  # pragma: no cover - defensive runner custody path
        return {
            "schema": "snerv_runner_crux_trace_attachment.v1",
            "written": False,
            "path": trace_path.as_posix(),
            "source_path": training_artifact_path.as_posix(),
            "error": f"{type(exc).__name__}:{exc}",
            "blockers": ["snerv_crux_trace_write_failed"],
            **FALSE_AUTHORITY,
        }
    trace_attachment = {
        "schema": "snerv_runner_crux_trace_attachment.v1",
        "written": True,
        **trace,
        **FALSE_AUTHORITY,
    }
    score_aware_long_training["nerv_crux_trace"] = dict(trace_attachment)
    artifact["score_aware_long_training"] = score_aware_long_training
    return trace_attachment


