def _weight_stats(arr: Any) -> dict[str, Any]:
    import numpy as np

    a = np.asarray(arr, dtype=np.float32)
    return {
        "shape": [int(v) for v in a.shape],
        "dtype": "float32",
        "min": float(np.min(a)),
        "max": float(np.max(a)),
        "mean": float(np.mean(a)),
        "nonzero_fraction": float(np.count_nonzero(a) / max(int(a.size), 1)),
    }


def _validate_recon_pixel_weight_array(
    arr: Any,
    *,
    expected_hw: tuple[int, int] = (384, 512),
    expected_pairs: int | None = None,
) -> Any:
    import numpy as np

    weight = np.asarray(arr, dtype=np.float32)
    if weight.ndim == 2:
        h, w = weight.shape
        channels = 1
    elif weight.ndim == 3:
        h, w, channels = weight.shape
    elif weight.ndim == 4:
        leading, h, w, channels = weight.shape
        if int(leading) != 1 and (expected_pairs is None or int(leading) != int(expected_pairs)):
            raise CompactRendererMlxSpineRunnerError(
                "recon pixel weight with 4 dims must have leading dimension "
                f"1 or expected pair count {expected_pairs}; got {int(leading)}"
            )
    elif weight.ndim == 5:
        pairs, frames, h, w, channels = weight.shape
        if int(frames) != 2:
            raise CompactRendererMlxSpineRunnerError("recon pixel weight with 5 dims must have frame dimension 2")
        if expected_pairs is not None and int(pairs) != int(expected_pairs):
            raise CompactRendererMlxSpineRunnerError(
                f"recon pixel weight pair count must match num_pairs ({int(pairs)} vs {int(expected_pairs)})"
            )
    else:
        raise CompactRendererMlxSpineRunnerError(
            "recon pixel weight must be shaped (H,W), (H,W,1/3), (1|N,H,W,1/3), or (N,2,H,W,1/3)"
        )
    if (int(h), int(w)) != tuple(int(v) for v in expected_hw):
        raise CompactRendererMlxSpineRunnerError(
            f"recon pixel weight spatial shape {(int(h), int(w))} != {expected_hw}"
        )
    if int(channels) not in (1, 3):
        raise CompactRendererMlxSpineRunnerError("recon pixel weight channel count must be 1 or 3")
    if not bool(np.all(np.isfinite(weight))):
        raise CompactRendererMlxSpineRunnerError("recon pixel weight must be finite")
    if float(np.min(weight)) < 0.0:
        raise CompactRendererMlxSpineRunnerError("recon pixel weight must be non-negative")
    if float(np.mean(weight)) <= 0.0:
        raise CompactRendererMlxSpineRunnerError("recon pixel weight must have positive total mass")
    return weight


def _load_recon_pixel_weight(
    path: str | Path,
    *,
    base: Path,
    expected_hw: tuple[int, int] = (384, 512),
    expected_pairs: int | None = None,
    normalize: str = "mean",
) -> tuple[Any, dict[str, Any]]:
    import numpy as np

    if normalize not in ("mean", "none"):
        raise CompactRendererMlxSpineRunnerError("recon_pixel_weight_normalize must be 'mean' or 'none'")
    resolved = _resolve_existing(path, base=base)
    key: str | None = None
    if resolved.suffix == ".npz":
        with np.load(resolved) as data:
            keys = sorted(str(item) for item in data.files)
            if not keys:
                raise CompactRendererMlxSpineRunnerError(f"recon pixel weight npz is empty: {resolved}")
            key = "weight" if "weight" in data.files else keys[0]
            weight = np.asarray(data[key], dtype=np.float32)
    else:
        weight = np.asarray(np.load(resolved), dtype=np.float32)
    source_sha256 = _sha256_file(resolved)
    weight = _validate_recon_pixel_weight_array(
        weight,
        expected_hw=expected_hw,
        expected_pairs=expected_pairs,
    )
    producer_manifest = _recon_pixel_weight_producer_manifest(
        resolved,
        expected_weight_sha256=source_sha256,
    )
    metadata = {
        "schema": "compact_recon_pixel_weight.v1",
        "enabled": True,
        "source_kind": "file",
        "path": resolved.as_posix(),
        "sha256": source_sha256,
        "npz_key": key,
        "normalize": normalize,
        "scorer_terms": {
            "p18_segnet": "caller_supplied",
            "p19_posenet": "caller_supplied",
        },
        "stats": _weight_stats(weight),
        "producer_manifest": producer_manifest,
        "authority": "false_macos_mlx_research_signal",
    }
    if expected_pairs is not None:
        metadata["expected_pairs"] = int(expected_pairs)
    return weight, metadata


def _discover_joint_recon_pixel_weight_path(
    *,
    repo_root: str | Path,
    num_pairs: int,
) -> tuple[Path, dict[str, Any]]:
    """Find the latest verified joint P18/P19 recon-weight artifact.

    Discovery is intentionally strict. It only returns artifacts generated by
    the finite-gradient joint-scorer surface producer, for the exact requested
    pair count, with the manifest's SHA matching the NPZ bytes. Anything else is
    ignored here and will remain a manual ``--recon-pixel-weight-path`` choice.
    """

    root = Path(repo_root).expanduser().resolve(strict=False)
    search_roots = [
        root / "experiments" / "results",
        *(ssd / "experiments" / "results" for ssd in DEFAULT_SSD_ROOTS),
    ]
    candidates: list[tuple[str, Path, Path, str]] = []
    rejected: list[dict[str, Any]] = []
    seen: set[Path] = set()
    for search_root in search_roots:
        resolved_root = search_root.expanduser().resolve(strict=False)
        if resolved_root in seen:
            continue
        seen.add(resolved_root)
        if not resolved_root.is_dir():
            continue
        for manifest_path in sorted(resolved_root.rglob("joint_p18_p19_recon_pixel_weight_manifest.json")):
            try:
                manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
                if not isinstance(manifest, dict):
                    raise ValueError("manifest_not_object")
                config = manifest.get("config")
                metadata = manifest.get("metadata")
                if not isinstance(config, dict) or not isinstance(metadata, dict):
                    raise ValueError("manifest_missing_config_or_metadata")
                if int(config.get("num_pairs", -1)) != int(num_pairs):
                    raise ValueError("num_pairs_mismatch")
                health = metadata.get("gradient_health")
                if not isinstance(health, dict):
                    raise ValueError("gradient_health_missing")
                blockers = list(metadata.get("blockers") or [])
                if health.get("status") != "pass_finite":
                    raise ValueError("gradient_health_not_pass_finite")
                if not bool(metadata.get("training_consumption_recommended")):
                    raise ValueError("training_consumption_not_recommended")
                if blockers:
                    raise ValueError("manifest_has_blockers")
                weight_path_value = manifest.get("weight_path")
                if weight_path_value is None:
                    raise ValueError("weight_path_missing")
                weight_path = _resolve_existing(
                    weight_path_value,
                    base=manifest_path.parent,
                )
                expected_sha = str(manifest.get("weight_sha256") or "")
                actual_sha = _sha256_file(weight_path)
                if expected_sha and expected_sha != actual_sha:
                    raise ValueError("weight_sha256_mismatch")
                candidates.append(
                    (
                        manifest_path.parent.as_posix(),
                        manifest_path,
                        weight_path,
                        actual_sha,
                    )
                )
            except Exception as exc:
                rejected.append(
                    {
                        "manifest_path": manifest_path.as_posix(),
                        "reason": f"{type(exc).__name__}:{exc!s}",
                    }
                )
    if not candidates:
        raise CompactRendererMlxSpineRunnerError(
            "no verified joint P18/P19 recon_pixel_weight artifact found for "
            f"num_pairs={int(num_pairs)}; build one with "
            "tools/build_joint_recon_pixel_weight_surface.py or pass "
            "--recon-pixel-weight-path explicitly"
        )
    _sort_key, manifest_path, weight_path, weight_sha = sorted(candidates)[-1]
    discovery = {
        "schema": "compact_auto_joint_recon_pixel_weight_discovery.v1",
        "status": "selected_verified_joint_p18_p19_weight",
        "num_pairs": int(num_pairs),
        "search_roots": [path.expanduser().resolve(strict=False).as_posix() for path in search_roots],
        "candidate_count": len(candidates),
        "rejected_count": len(rejected),
        "selected_manifest_path": manifest_path.as_posix(),
        "selected_manifest_sha256": _sha256_file(manifest_path),
        "selected_weight_path": weight_path.as_posix(),
        "selected_weight_sha256": weight_sha,
        "authority": "false_macos_mlx_research_signal",
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }
    if rejected:
        discovery["rejected_manifests"] = rejected[:16]
    return weight_path, discovery


def _recon_pixel_weight_producer_manifest(
    weight_path: Path,
    *,
    expected_weight_sha256: str,
) -> dict[str, Any]:
    """Return fail-closed producer-manifest custody for a recon weight file."""

    manifest_path = weight_path.with_name("joint_p18_p19_recon_pixel_weight_manifest.json")
    hard_region_manifest_path = weight_path.with_name("receiver_replay_hard_region_recon_pixel_weight_manifest.json")
    if not manifest_path.is_file():
        if hard_region_manifest_path.is_file():
            return _hard_region_recon_pixel_weight_producer_manifest(
                hard_region_manifest_path,
                weight_path=weight_path,
                expected_weight_sha256=expected_weight_sha256,
            )
        return {
            "schema": "compact_recon_pixel_weight_producer_manifest.v1",
            "status": "not_found_unverified_manual_or_legacy_weight",
            "path": manifest_path.as_posix(),
            "searched_paths": [
                manifest_path.as_posix(),
                hard_region_manifest_path.as_posix(),
            ],
            "consumption_certified": False,
        }

    manifest = _load_recon_pixel_weight_manifest_object(manifest_path)
    _validate_recon_pixel_weight_manifest_identity(
        manifest,
        manifest_path=manifest_path,
        weight_path=weight_path,
        expected_weight_sha256=expected_weight_sha256,
    )
    producer_metadata = manifest.get("metadata")
    if not isinstance(producer_metadata, dict):
        raise CompactRendererMlxSpineRunnerError("recon pixel weight producer manifest is missing metadata object")
    gradient_health = producer_metadata.get("gradient_health")
    if not isinstance(gradient_health, dict):
        raise CompactRendererMlxSpineRunnerError(
            "recon pixel weight producer manifest is missing gradient_health; "
            "regenerate the surface with the finite-gradient producer"
        )
    blockers = list(producer_metadata.get("blockers") or [])
    consumption_recommended = bool(producer_metadata.get("training_consumption_recommended", False))
    if gradient_health.get("status") != "pass_finite":
        raise CompactRendererMlxSpineRunnerError(
            f"recon pixel weight producer manifest did not pass finite-gradient health: {gradient_health.get('status')}"
        )
    if not consumption_recommended or blockers:
        raise CompactRendererMlxSpineRunnerError(
            f"recon pixel weight producer manifest is not recommended for training consumption; blockers={blockers}"
        )

    return {
        "schema": "compact_recon_pixel_weight_producer_manifest.v1",
        "status": "verified_finite_gradient_manifest",
        "path": manifest_path.as_posix(),
        "sha256": _sha256_file(manifest_path),
        "producer_schema": manifest.get("schema"),
        "producer_metadata_schema": producer_metadata.get("schema"),
        "weight_path": Path(str(manifest.get("weight_path", weight_path))).as_posix(),
        "weight_sha256": expected_weight_sha256,
        "gradient_health": gradient_health,
        "blockers": blockers,
        "training_consumption_recommended": consumption_recommended,
        "consumption_certified": True,
    }


def _hard_region_recon_pixel_weight_producer_manifest(
    manifest_path: Path,
    *,
    weight_path: Path,
    expected_weight_sha256: str,
) -> dict[str, Any]:
    """Carry false-authority receiver hard-region custody into trainer telemetry."""

    manifest = _load_recon_pixel_weight_manifest_object(manifest_path)
    _validate_recon_pixel_weight_manifest_identity(
        manifest,
        manifest_path=manifest_path,
        weight_path=weight_path,
        expected_weight_sha256=expected_weight_sha256,
    )
    if str(manifest.get("schema") or "") != ("receiver_replay_hard_region_recon_pixel_weight_manifest.v1"):
        raise CompactRendererMlxSpineRunnerError(
            f"receiver hard-region recon pixel weight manifest has unexpected schema: {manifest.get('schema')!r}"
        )
    producer_metadata = manifest.get("metadata")
    if not isinstance(producer_metadata, dict):
        raise CompactRendererMlxSpineRunnerError(
            "receiver hard-region recon pixel weight manifest is missing metadata object"
        )
    consumption = manifest.get("consumption")
    if not isinstance(consumption, dict):
        raise CompactRendererMlxSpineRunnerError(
            "receiver hard-region recon pixel weight manifest is missing consumption object"
        )
    applied_records = int(producer_metadata.get("applied_hard_region_records") or 0)
    if applied_records <= 0 or not bool(consumption.get("training_consumption_recommended")):
        raise CompactRendererMlxSpineRunnerError(
            "receiver hard-region recon pixel weight manifest has no active "
            f"training pressure: applied_hard_region_records={applied_records}"
        )

    return {
        "schema": "compact_recon_pixel_weight_producer_manifest.v1",
        "status": "receiver_replay_hard_region_manifest_false_authority",
        "path": manifest_path.as_posix(),
        "sha256": _sha256_file(manifest_path),
        "producer_schema": manifest.get("schema"),
        "producer_metadata_schema": producer_metadata.get("schema"),
        "weight_path": Path(str(manifest.get("weight_path", weight_path))).as_posix(),
        "weight_sha256": expected_weight_sha256,
        "weight_array_sha256": manifest.get("weight_array_sha256"),
        "evidence_grade": producer_metadata.get("evidence_grade"),
        "evidence_tag": producer_metadata.get("evidence_tag"),
        "source_report_schema": producer_metadata.get("source_report_schema"),
        "source_report_label": producer_metadata.get("source_report_label"),
        "source_report_identity": dict(producer_metadata.get("source_report_identity") or {}),
        "applied_hard_region_records": applied_records,
        "applied_component_bboxes": int(producer_metadata.get("applied_component_bboxes") or 0),
        "target_frame_index": int(producer_metadata.get("target_frame_index") or 0),
        "training_arg": consumption.get("training_arg"),
        "training_consumption_recommended": bool(consumption.get("training_consumption_recommended")),
        "auto_discovery_eligible": bool(consumption.get("auto_discovery_eligible")),
        "consumption_reason": consumption.get("reason"),
        "consumption_certified": False,
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }


def _load_recon_pixel_weight_manifest_object(manifest_path: Path) -> dict[str, Any]:
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except Exception as exc:
        raise CompactRendererMlxSpineRunnerError(
            f"recon pixel weight producer manifest is not valid JSON: {manifest_path}"
        ) from exc
    if not isinstance(manifest, dict):
        raise CompactRendererMlxSpineRunnerError(
            f"recon pixel weight producer manifest must be an object: {manifest_path}"
        )
    return manifest


def _validate_recon_pixel_weight_manifest_identity(
    manifest: Mapping[str, Any],
    *,
    manifest_path: Path,
    weight_path: Path,
    expected_weight_sha256: str,
) -> None:
    manifest_weight_path = manifest.get("weight_path")
    if manifest_weight_path is not None:
        manifest_resolved = _resolve_existing(manifest_weight_path, base=weight_path.parent)
        if manifest_resolved != weight_path:
            raise CompactRendererMlxSpineRunnerError(
                "recon pixel weight producer manifest points at a different "
                f"weight file: {manifest_resolved} != {weight_path}"
            )
    manifest_weight_sha = manifest.get("weight_sha256")
    if manifest_weight_sha is not None and str(manifest_weight_sha) != expected_weight_sha256:
        raise CompactRendererMlxSpineRunnerError(
            "recon pixel weight producer manifest SHA does not match loaded "
            f"weight file: {manifest_weight_sha} != {expected_weight_sha256}; "
            f"manifest={manifest_path}"
        )


def _segnet_boundary_recon_pixel_weight(
    scorer_teacher: Any,
    *,
    tau: float,
    normalize: str = "mean",
) -> tuple[Any, dict[str, Any]]:
    import numpy as np

    if tau <= 0.0:
        raise CompactRendererMlxSpineRunnerError("recon pixel weight tau must be > 0")
    if normalize not in ("mean", "none"):
        raise CompactRendererMlxSpineRunnerError("recon_pixel_weight_normalize must be 'mean' or 'none'")
    logits = np.asarray(scorer_teacher.teacher_logits_thwk, dtype=np.float32)
    if logits.ndim != 4 or int(logits.shape[-1]) < 2:
        raise CompactRendererMlxSpineRunnerError(
            "SegNet boundary recon weight requires teacher logits shaped (T,H,W,K>=2)"
        )
    sorted_logits = np.sort(logits, axis=-1)
    margin = sorted_logits[..., -1] - sorted_logits[..., -2]
    saliency = np.exp(-np.maximum(margin, 0.0) / float(tau)).astype(np.float32)
    # SegNet scores only the LAST frame of each pair. Keep frame 0 on uniform
    # reconstruction pressure for pose/reconstruction, and give frame 1 its
    # own per-pair boundary map so moving class boundaries are not blurred into
    # one static full-video average.
    weight = np.stack(
        [
            np.ones_like(saliency, dtype=np.float32),
            saliency,
        ],
        axis=1,
    )[..., None].astype(np.float32)
    weight = _validate_recon_pixel_weight_array(weight, expected_hw=(384, 512))
    metadata = {
        "schema": "compact_recon_pixel_weight.v1",
        "enabled": True,
        "source_kind": "auto_segnet_top2_boundary_margin",
        "tau": float(tau),
        "normalize": normalize,
        "scorer_terms": {
            "p18_segnet": ("per_pair_last_frame_top2_margin_exp_boundary_saliency_from_real_teacher"),
            "p19_posenet": "not_included_use_recon_pixel_weight_path_for_joint_map",
        },
        "frame_policy": {
            "frame0": "uniform_reconstruction_pose_support_not_seen_by_segnet",
            "frame1": "per_pair_segnet_top2_boundary_saliency",
            "reason": "upstream SegNet scores x[:,-1,...] only",
        },
        "stats": _weight_stats(weight),
        "authority": "false_macos_mlx_research_signal",
    }
    return weight, metadata


class _LazySegNetBoundaryReconPixelWeight:
    """Provider-backed P18 recon weights for full-video compact training.

    The dense equivalent is ``(N,2,384,512,1)``: frame 0 is uniform; frame 1 is
    exp(-top2-margin/tau) from the real SegNet teacher logits. Keeping that as a
    full float32 tensor adds avoidable full-video memory pressure. This provider
    computes the active batch slice from the already-bound teacher cache instead.
    """

    def __init__(self, scorer_teacher: Any, *, tau: float) -> None:
        self.scorer_teacher = scorer_teacher
        self.tau = float(tau)

    def recon_pixel_weight_for_batch(
        self,
        *,
        idx: Any,
        frame_shape: Any,
        frame_index: int,
    ) -> Any:
        import mlx.core as mx

        b, h, w, _c = frame_shape
        if int(frame_index) == 0:
            return mx.ones((int(b), int(h), int(w), 1), dtype=mx.float32)
        logits = self.scorer_teacher.teacher_logits_for_indices(idx)
        sorted_logits = mx.sort(logits, axis=-1)
        margin = sorted_logits[..., -1] - sorted_logits[..., -2]
        saliency = mx.exp(-mx.maximum(margin, 0.0) / self.tau)
        return saliency.astype(mx.float32)[..., None]


def _lazy_segnet_boundary_recon_pixel_weight(
    scorer_teacher: Any,
    *,
    tau: float,
    normalize: str = "mean",
) -> tuple[Any, dict[str, Any]]:
    import numpy as np

    if tau <= 0.0:
        raise CompactRendererMlxSpineRunnerError("recon pixel weight tau must be > 0")
    if normalize not in ("mean", "none"):
        raise CompactRendererMlxSpineRunnerError("recon_pixel_weight_normalize must be 'mean' or 'none'")
    logits = np.asarray(scorer_teacher.teacher_logits_thwk, dtype=np.float32)
    if logits.ndim != 4 or int(logits.shape[-1]) < 2:
        raise CompactRendererMlxSpineRunnerError(
            "SegNet boundary recon weight requires teacher logits shaped (T,H,W,K>=2)"
        )
    provider = _LazySegNetBoundaryReconPixelWeight(scorer_teacher, tau=float(tau))
    # Stats are intentionally sampled from the same real teacher logits used by
    # the provider. The provider itself remains the training authority.
    sorted_logits = np.sort(logits, axis=-1)
    margin = sorted_logits[..., -1] - sorted_logits[..., -2]
    saliency = np.exp(-np.maximum(margin, 0.0) / float(tau)).astype(np.float32)
    stats_weight = np.stack(
        [np.ones_like(saliency, dtype=np.float32), saliency],
        axis=1,
    )[..., None]
    metadata = {
        "schema": "compact_recon_pixel_weight.v1",
        "enabled": True,
        "source_kind": "auto_segnet_top2_boundary_margin_lazy_provider",
        "provider_kind": "lazy_segnet_top2_boundary_margin",
        "materialization": "batch_slices_only_no_full_video_dense_weight",
        "dense_equivalent_shape": [
            int(logits.shape[0]),
            2,
            int(logits.shape[1]),
            int(logits.shape[2]),
            1,
        ],
        "tau": float(tau),
        "normalize": normalize,
        "scorer_terms": {
            "p18_segnet": ("per_pair_last_frame_top2_margin_exp_boundary_saliency_from_real_teacher"),
            "p19_posenet": "not_included_use_recon_pixel_weight_path_for_joint_map",
        },
        "frame_policy": {
            "frame0": "uniform_reconstruction_pose_support_not_seen_by_segnet",
            "frame1": "per_pair_segnet_top2_boundary_saliency",
            "reason": "upstream SegNet scores x[:,-1,...] only",
        },
        "stats": _weight_stats(stats_weight),
        "authority": "false_macos_mlx_research_signal",
    }
    return provider, metadata


def _disabled_recon_pixel_weight_metadata() -> dict[str, Any]:
    return {
        "schema": "compact_recon_pixel_weight.v1",
        "enabled": False,
        "authority": "false_macos_mlx_research_signal",
    }


def _recon_pixel_weight_report_metadata(
    artifact_dict: Mapping[str, Any],
) -> dict[str, Any]:
    score_training = _substrate_score_aware_training_from_artifact(artifact_dict)
    value = score_training.get("recon_pixel_weight")
    if isinstance(value, Mapping):
        return dict(value)
    return _disabled_recon_pixel_weight_metadata()


