def _hi_nerv_receiver_cache_quality_numeric_class_collapse(
    summary: Mapping[str, Any],
    *,
    min_material_occupied_fraction: float = (HI_NERV_SEGNET_ARGMAX_MIN_OCCUPIED_CLASS_FRACTION_FOR_FIT_GATE),
) -> bool:
    candidate_fraction = _compact_finite_float_from_keys(
        summary,
        ("segnet_candidate_occupied_class_fraction",),
    )
    reference_fraction = _compact_finite_float_from_keys(
        summary,
        ("segnet_reference_occupied_class_fraction",),
    )
    if candidate_fraction is None or reference_fraction is None:
        return False
    return float(candidate_fraction) < float(min_material_occupied_fraction) and float(reference_fraction) >= float(
        min_material_occupied_fraction
    )


def _measured_archive_byte_cap_report(
    *,
    archive_bytes: int | None,
    archive_sha256: str | None,
    hard_byte_ceilings: tuple[int, ...],
    candidate: Mapping[str, Any],
) -> dict[str, Any]:
    ceilings = tuple(sorted({int(value) for value in hard_byte_ceilings if int(value) > 0}))
    tightest = min(ceilings) if ceilings else None
    candidate_ceiling = _compact_first_present_int(candidate, ("hard_byte_ceiling",))
    archive_int = None if archive_bytes is None else int(archive_bytes)
    delta = None if archive_int is None or tightest is None else archive_int - int(tightest)
    under_tightest = None if delta is None else delta <= 0
    candidate_delta = None if archive_int is None or candidate_ceiling is None else archive_int - int(candidate_ceiling)
    blockers: list[str] = []
    if not ceilings:
        blockers.append("hard_byte_ceiling_not_configured")
    if archive_int is None:
        blockers.append("measured_archive_bytes_missing_for_byte_cap")
    if not _compact_is_sha256_hex(archive_sha256):
        blockers.append("measured_archive_sha256_missing_for_byte_cap")
    if candidate and candidate_ceiling is None:
        blockers.append("selected_modelsize_candidate_missing_hard_byte_ceiling")
    if (
        delta is not None
        and delta > 0
        and (candidate_ceiling is None or tightest is None or int(candidate_ceiling) <= int(tightest))
    ):
        blockers.append("measured_archive_bytes_exceed_tightest_hard_ceiling")
    if candidate_delta is not None and candidate_delta > 0:
        blockers.append("measured_archive_bytes_exceed_selected_candidate_ceiling")
    return {
        "schema": "measured_archive_byte_cap_report.v1",
        "authority_surface": "measured_archive_zip_bytes_after_receiver_export",
        "hard_byte_ceilings": list(ceilings),
        "tightest_hard_byte_ceiling": tightest,
        "selected_candidate_hard_byte_ceiling": candidate_ceiling,
        "archive_zip_bytes": archive_int,
        "archive_sha256": archive_sha256,
        "delta_bytes_vs_tightest_hard_byte_ceiling": delta,
        "delta_bytes_vs_selected_candidate_ceiling": candidate_delta,
        "under_tightest_hard_byte_ceiling": under_tightest,
        "under_selected_candidate_hard_byte_ceiling": (None if candidate_delta is None else candidate_delta <= 0),
        "tightest_hard_ceiling_is_blocking": bool(
            candidate_ceiling is None or tightest is None or int(candidate_ceiling) <= int(tightest)
        ),
        "blockers": _dedupe(blockers),
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }


def _compact_receiver_closed_identity_blockers(row: Mapping[str, Any]) -> list[str]:
    blockers: list[str] = []
    if (
        _compact_first_present_str(
            row,
            (
                "receiver_proof_path",
                "receiver_proof_report_path",
                "receiver_closed_proof_path",
            ),
        )
        is None
    ):
        blockers.append("receiver_proof_path_missing")
    if not _compact_is_sha256_hex(
        _compact_first_present_str(
            row,
            (
                "receiver_proof_sha256",
                "receiver_proof_report_sha256",
                "receiver_closed_proof_sha256",
            ),
        )
    ):
        blockers.append("receiver_proof_sha256_missing_or_invalid")
    if not _compact_is_sha256_hex(
        _compact_first_present_str(
            row,
            (
                "archive_sha256",
                "candidate_archive_sha256",
                "receiver_archive_sha256",
                "source_archive_sha256",
                "archive_zip_sha256",
            ),
        )
    ):
        blockers.append("archive_sha256_missing_or_invalid")
    if (
        _compact_first_present_str(
            row,
            (
                "axis_tag",
                "score_axis_tag",
                "measured_score_axis_tag",
                "receiver_proof_axis_tag",
            ),
        )
        is None
    ):
        blockers.append("receiver_proof_axis_tag_missing")
    sample_count = _compact_first_present_int(
        row,
        ("sample_pair_count", "sample_pairs", "n_pairs", "num_pairs", "pair_count"),
    )
    full_video = any(bool(row.get(key)) for key in ("full_video_coverage", "full600_coverage", "full_sample_coverage"))
    if sample_count is None and not full_video:
        blockers.append("receiver_proof_full_sample_count_missing")
    elif sample_count is not None and sample_count < CONTEST_PAIR_COUNT and not full_video:
        blockers.append("receiver_proof_full_sample_count_incomplete")
    return blockers


def _compact_first_present_str(
    row: Mapping[str, Any],
    keys: tuple[str, ...],
) -> str | None:
    for key in keys:
        value = row.get(key)
        if value is not None and str(value).strip():
            return str(value).strip()
    return None


def _compact_first_present_int(
    row: Mapping[str, Any],
    keys: tuple[str, ...],
) -> int | None:
    for key in keys:
        value = row.get(key)
        if value is None:
            continue
        try:
            return int(value)
        except (TypeError, ValueError):
            continue
    return None


def _compact_is_sha256_hex(value: str | None) -> bool:
    if value is None:
        return False
    text = str(value).strip().lower()
    return len(text) == 64 and all(ch in "0123456789abcdef" for ch in text)


def _compact_modelsize_row_has_source_bound_capacity(row: Mapping[str, Any]) -> bool:
    if _compact_finite_float_from_keys(row, ("modelsize_mparams",)) is not None:
        return True
    if _compact_positive_int_from_keys(row, ("fc_dim",)) is not None:
        return True
    official_controls = row.get("official_controls")
    if isinstance(official_controls, Mapping):
        return (
            _compact_finite_float_from_keys(official_controls, ("--modelsize",)) is not None
            or _compact_positive_int_from_keys(official_controls, ("fc_dim",)) is not None
        )
    solved = row.get("solved_budget")
    if isinstance(solved, Mapping):
        return _compact_modelsize_row_has_source_bound_capacity(solved)
    return False


def _compact_modelsize_row_has_nonrate_signal(row: Mapping[str, Any]) -> bool:
    if (
        _compact_finite_float_from_keys(
            row,
            ("nonrate_score", "nonrate_score_value"),
        )
        is not None
    ):
        return True
    if _compact_finite_float_from_keys(row, ("avg_segnet_dist", "d_seg")) is not None:
        return (
            _compact_finite_float_from_keys(
                row,
                ("avg_posenet_dist", "d_pose"),
            )
            is not None
        )
    return False


def _compact_positive_int_from_keys(
    row: Mapping[str, Any],
    keys: tuple[str, ...],
) -> int | None:
    for key in keys:
        try:
            value = int(row.get(key))
        except (TypeError, ValueError):
            continue
        if value > 0:
            return value
    return None


def _compact_finite_float_from_keys(
    row: Mapping[str, Any],
    keys: tuple[str, ...],
) -> float | None:
    for key in keys:
        try:
            value = float(row.get(key))
        except (TypeError, ValueError):
            continue
        if math.isfinite(value):
            return value
    return None


def _metric_mapping_float(
    mapping: Mapping[str, Any] | None,
    key: str,
) -> float | None:
    if mapping is None:
        return None
    try:
        value = float(mapping.get(key))
    except (TypeError, ValueError):
        return None
    return value if math.isfinite(value) else None


class _PoseInstabilityEpochMonitor:
    """Fail-fast monitor for full-video HiNeRV PoseNet instability."""

    def __init__(
        self,
        *,
        start_epoch: int = 0,
        min_epoch: int = 64,
        consecutive_bad_epochs: int = 8,
        pose_loss_threshold: float = 1_000.0,
        pose_axis_threshold: float = 1_000.0,
        hard_pair_sampling_active: bool = False,
    ) -> None:
        self.start_epoch = max(0, int(start_epoch))
        self.min_epoch = max(0, int(min_epoch))
        self.consecutive_bad_epochs = max(1, int(consecutive_bad_epochs))
        self.pose_loss_threshold = float(pose_loss_threshold)
        self.pose_axis_threshold = float(pose_axis_threshold)
        self.hard_pair_sampling_active = bool(hard_pair_sampling_active)
        self.bad_epoch_count = 0
        self.last_reason = ""

    def as_dict(self) -> dict[str, Any]:
        return {
            "schema": "compact_pose_instability_epoch_monitor.v1",
            "start_epoch": int(self.start_epoch),
            "min_epoch": int(self.min_epoch),
            "min_local_epochs": int(self.min_epoch),
            "consecutive_bad_epochs": int(self.consecutive_bad_epochs),
            "pose_loss_threshold": float(self.pose_loss_threshold),
            "pose_loss_metric_name": "loss_part_pose_score_term",
            "pose_raw_loss_metric_name": "loss_part_pose_distill",
            "pose_axis_threshold": float(self.pose_axis_threshold),
            "hard_pair_sampling_active": bool(self.hard_pair_sampling_active),
            "hard_pair_axis_stop_enabled": not bool(self.hard_pair_sampling_active),
            "bad_epoch_count": int(self.bad_epoch_count),
            "last_reason": self.last_reason,
        }

    def __call__(self, metrics: Any) -> None:
        epoch = int(metrics.epoch)
        local_epoch = max(0, epoch - self.start_epoch)
        if local_epoch < self.min_epoch:
            return
        loss_components = getattr(metrics, "loss_components", None)
        per_axis = getattr(metrics, "per_axis_decomposition", None)
        pose_score_term = _metric_mapping_float(
            loss_components,
            "loss_part_pose_score_term",
        )
        pose_raw_loss = _metric_mapping_float(loss_components, "loss_part_pose_distill")
        pose_loss = pose_score_term if pose_score_term is not None else pose_raw_loss
        pose_loss_metric_name = "loss_part_pose_score_term" if pose_score_term is not None else "loss_part_pose_distill"
        pose_axis = _metric_mapping_float(per_axis, "pose")
        bad_loss = pose_loss is not None and pose_loss >= self.pose_loss_threshold
        bad_axis = pose_axis is not None and pose_axis >= self.pose_axis_threshold
        if bad_loss or bad_axis:
            self.bad_epoch_count += 1
            self.last_reason = (
                f"hi_nerv_pose_instability_epoch_{epoch}:"
                f"local_epoch={local_epoch}:"
                f"pose_loss_metric={pose_loss_metric_name}:"
                f"pose_loss={pose_loss}:"
                f"pose_score_term={pose_score_term}:"
                f"pose_raw_mse={pose_raw_loss}:"
                f"pose_axis={pose_axis}:"
                f"bad_epochs={self.bad_epoch_count}"
            )
        else:
            self.bad_epoch_count = 0
            self.last_reason = ""
        if self.hard_pair_sampling_active:
            if self.last_reason:
                self.last_reason = f"{self.last_reason}:stop_suppressed_for_hard_pair_sampling"
            return
        if self.bad_epoch_count >= self.consecutive_bad_epochs:
            raise LongTrainingStopRequested(
                "hi_nerv_pose_instability_guard:"
                f"epoch={epoch}:"
                f"local_epoch={local_epoch}:"
                f"start_epoch={self.start_epoch}:"
                f"pose_loss={pose_loss}:"
                f"pose_axis={pose_axis}:"
                f"consecutive_bad_epochs={self.bad_epoch_count}:"
                f"thresholds=loss>={self.pose_loss_threshold},"
                f"axis>={self.pose_axis_threshold}"
            )


def _resume_start_epoch_for_pose_monitor(
    resume_from_checkpoint: str | Path | None,
) -> int:
    """Return the first local epoch for a resumed run's pose guard window."""

    if resume_from_checkpoint is None:
        return 0
    path = Path(resume_from_checkpoint).expanduser().resolve(strict=False)
    if not path.is_file():
        return 0
    try:
        payload = _load_json(path)
        global_epoch = int(payload.get("global_epoch", -1))
    except Exception:
        return 0
    return max(0, global_epoch + 1)


def _hi_nerv_priority_target_hydration_contract(
    *,
    prioritized_pair_indices: tuple[int, ...],
    model_num_pairs: int,
    hydrated_target_pair_count: int,
    sparse_target_hydration: bool = False,
) -> dict[str, Any]:
    """Return the machine-readable HiNeRV hard-pair hydration contract."""

    enabled = bool(prioritized_pair_indices)
    sparse = bool(enabled and sparse_target_hydration)
    return {
        "schema": "compact_hi_nerv_prioritized_pair_training.v1",
        "enabled": enabled,
        "pair_indices": [int(value) for value in prioritized_pair_indices],
        "pair_count": len(prioritized_pair_indices),
        "sampling_scope": (
            "sparse_source_pair_target_hydration"
            if sparse
            else (
                "full_video_target_hydration_with_prioritized_sampling" if enabled else "training_batch_emphasis_only"
            )
        ),
        "pair_index_domain": (
            "source_video_pair_indices_0_to_model_num_pairs_minus_1"
            if enabled
            else "decoded_prefix_pair_indices_0_to_num_pairs_minus_1"
        ),
        "model_num_pairs": int(model_num_pairs),
        "hydrated_target_pair_count": int(hydrated_target_pair_count),
        "source_pair_indices": [int(value) for value in prioritized_pair_indices],
        "local_target_rows_are_compact": sparse,
        "arbitrary_source_pair_hydration": sparse,
        "target_hydration_pair_indices_consumed": sparse,
        "target_hydration_pair_indices_consumed_by_renderer_bundle": sparse,
        "requires_num_pairs_covering_pair_ids": sparse,
        "authority": "macos_mlx_research_signal_false_authority",
    }


def _modelsize_budget_rows_from_plan(plan: Any) -> list[dict[str, Any]]:
    if not isinstance(plan, Mapping):
        return []
    source_rows = plan.get("receiver_closed_points") or plan.get("points") or []
    if not isinstance(source_rows, list):
        return []
    rows: list[dict[str, Any]] = []
    for point in source_rows:
        if not isinstance(point, Mapping):
            continue
        row = dict(point.get("source") or {})
        row.setdefault("row_id", point.get("row_id"))
        row.setdefault("archive_bytes", point.get("archive_bytes"))
        row.setdefault("nonrate_score", point.get("nonrate_score"))
        row.setdefault("receiver_closed", point.get("receiver_closed_bytes"))
        row.setdefault("receiver_proof_passed", point.get("receiver_closed_bytes"))
        rows.append(row)
    return rows


def _validate_hi_nerv_frontier_training_config(
    *,
    segnet_distillation_weight: float,
    segnet_direct_live_distillation_weight: float = 0.0,
    segnet_direct_live_class_histogram_weight: float = 0.0,
    segnet_direct_live_class_balanced_hinge_weight: float = 0.0,
    segnet_direct_live_class_balanced_ce_weight: float = 0.0,
    segnet_direct_live_class_balanced_squared_hinge_weight: float = 0.0,
    segnet_direct_live_class_region_recon_weight: float = 0.0,
    segnet_direct_live_rare_class_logit_weight: float = 0.0,
    segnet_direct_live_target_mass_floor_weight: float = 0.0,
    segnet_direct_live_target_min_ratio_floor_weight: float = 0.0,
    scorer_input_distribution_guard_weight: float = 0.0,
    scorer_input_contrast_floor_weight: float = 0.0,
    scorer_input_shape_tether_weight: float = 0.0,
    posenet_yuv6_geometry_tether_weight: float = 0.0,
    posenet_temporal_signal_floor_weight: float = 0.0,
    pose_distillation_weight: float,
    pose_direct_live_distillation_weight: float = 0.0,
    allow_segnet_only_research: bool,
    allow_unscored_research_smoke: bool,
    score_aware_training_plan: Mapping[str, Any],
) -> dict[str, Any]:
    blockers: list[str] = []
    direct_live_escape_controls = {
        "class_histogram": float(segnet_direct_live_class_histogram_weight),
        "class_balanced_hinge": float(segnet_direct_live_class_balanced_hinge_weight),
        "class_balanced_ce": float(segnet_direct_live_class_balanced_ce_weight),
        "class_balanced_squared_hinge": float(segnet_direct_live_class_balanced_squared_hinge_weight),
        "class_region_recon": float(segnet_direct_live_class_region_recon_weight),
        "rare_class_logit": float(segnet_direct_live_rare_class_logit_weight),
        "target_mass_floor": float(segnet_direct_live_target_mass_floor_weight),
        "target_min_ratio_floor": float(segnet_direct_live_target_min_ratio_floor_weight),
        "contrast_floor": float(scorer_input_contrast_floor_weight),
        "shape_tether": float(scorer_input_shape_tether_weight),
    }
    direct_live_supporting_controls = {
        "distribution_guard": float(scorer_input_distribution_guard_weight),
    }
    pose_supporting_controls = {
        "posenet_yuv6_geometry_tether": float(posenet_yuv6_geometry_tether_weight),
        "posenet_temporal_signal_floor": float(posenet_temporal_signal_floor_weight),
    }
    direct_live_escape_controls_attached = any(value > 0.0 for value in direct_live_escape_controls.values())
    direct_live_attached = float(segnet_direct_live_distillation_weight) > 0.0 or direct_live_escape_controls_attached
    segnet_attached = float(segnet_distillation_weight) > 0.0 or direct_live_attached
    pose_direct_live_attached = float(pose_direct_live_distillation_weight) > 0.0
    posenet_attached = float(pose_distillation_weight) > 0.0 or pose_direct_live_attached
    if not segnet_attached:
        blockers.append("hi_nerv_real_segnet_teacher_missing")
    if not posenet_attached:
        blockers.append("hi_nerv_real_posenet_teacher_missing")
    if direct_live_attached and not direct_live_escape_controls_attached:
        blockers.append("hi_nerv_direct_live_escape_controls_missing")
    if allow_segnet_only_research and segnet_attached and not posenet_attached:
        blockers.append("hi_nerv_segnet_only_research_not_frontier_targeting")
    unscored_smoke = bool(allow_unscored_research_smoke)
    segnet_only_research_allowed = bool(allow_segnet_only_research and segnet_attached and not posenet_attached)
    base_launch_allowed = (segnet_attached and posenet_attached) or segnet_only_research_allowed or unscored_smoke
    launch_allowed = bool(
        base_launch_allowed and not (direct_live_attached and not direct_live_escape_controls_attached)
    )
    return {
        "schema": "compact_hi_nerv_score_aware_training_config_gate.v1",
        "launch_allowed": launch_allowed,
        "base_launch_allowed": base_launch_allowed,
        "frontier_targeting": segnet_attached and posenet_attached,
        "segnet_only_research_allowed": segnet_only_research_allowed,
        "allow_segnet_only_research": bool(allow_segnet_only_research),
        "allow_unscored_research_smoke": unscored_smoke,
        "real_segnet_teacher_attached": segnet_attached,
        "segnet_distillation_weight": float(segnet_distillation_weight),
        "segnet_direct_live_distillation_weight": float(segnet_direct_live_distillation_weight),
        "direct_live_escape_controls_attached": direct_live_escape_controls_attached,
        "direct_live_escape_controls": direct_live_escape_controls,
        "direct_live_supporting_controls": direct_live_supporting_controls,
        "real_posenet_teacher_attached": posenet_attached,
        "pose_distillation_weight": float(pose_distillation_weight),
        "pose_direct_live_distillation_weight": float(pose_direct_live_distillation_weight),
        "pose_direct_live_attached": pose_direct_live_attached,
        "pose_supporting_controls": pose_supporting_controls,
        "modelsize_budget_receiver_closed_ready": bool(
            score_aware_training_plan.get("modelsize_budget_receiver_closed_ready")
        ),
        "planner_action": score_aware_training_plan.get("planner_action"),
        "blockers": blockers,
        "score_claim": False,
        "promotion_eligible": False,
        "rank_or_kill_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }


def _hi_nerv_launch_source_faithfulness_report(
    *,
    use_hierarchical_feature_grid: bool,
    use_convnext_blocks: bool,
    local_grid_levels: int,
    local_grid_channels: int,
    convnext_mlp_ratio: int,
    convnext_kernel_size: int,
    decoder_codec: str,
    hi_nerv_latent_codec: str = "int16_raw",
) -> dict[str, Any]:
    cfg = SimpleNamespace(
        use_hierarchical_feature_grid=bool(use_hierarchical_feature_grid),
        use_convnext_blocks=bool(use_convnext_blocks),
        local_grid_levels=int(local_grid_levels),
        local_grid_channels=int(local_grid_channels),
        convnext_mlp_ratio=int(convnext_mlp_ratio),
        convnext_kernel_size=int(convnext_kernel_size),
    )
    return _hi_nerv_source_faithfulness_report(
        cfg=cfg,
        decoder_codec=str(decoder_codec),
    )


def _hi_nerv_source_faithfulness_report(*, cfg: Any, decoder_codec: str) -> dict[str, Any]:
    """Classify whether a HiNeRV launch is official-control faithful or local."""

    hierarchical_grid = bool(getattr(cfg, "use_hierarchical_feature_grid", False))
    convnext_blocks = bool(getattr(cfg, "use_convnext_blocks", False))
    official_hinerv_blockers: list[str] = []
    if not hierarchical_grid:
        official_hinerv_blockers.append("hinerv_official_hierarchical_feature_grid_not_enabled")
    if not convnext_blocks:
        official_hinerv_blockers.append("hinerv_official_convnext_blocks_not_enabled")
    pr95_better_blockers = [
        "hinerv_pr95_pixelshuffle_bilinear_skip_refine_path_missing",
        "hinerv_pr95_pr101_latent_delta_brotli_codec_missing",
    ]
    official_hinerv_control = not official_hinerv_blockers
    source_parity_binding = _hi_nerv_source_parity_binding()
    source_parity_blockers = list(source_parity_binding.get("required_blockers") or [])
    source_parity_attached = bool(source_parity_binding.get("contract_attached") and not source_parity_blockers)
    source_faithful = False
    if official_hinerv_control and pr95_better_blockers and source_parity_attached:
        classification = "official_hinerv_control_candidate_source_parity_bound_pr95_better_gaps"
    elif official_hinerv_control and pr95_better_blockers:
        classification = "official_hinerv_control_candidate_source_parity_missing_pr95_better_gaps"
    elif official_hinerv_control:
        classification = (
            "official_hinerv_control_candidate_source_parity_bound"
            if source_parity_attached
            else "official_hinerv_control_candidate_source_parity_missing"
        )
    else:
        classification = "local_hiv1_adaptation_not_official_hinerv"
    return {
        "schema": "hi_nerv_source_faithfulness.v1",
        "classification": classification,
        "source_faithful_official_hinerv": source_faithful,
        "official_hinerv_control": official_hinerv_control,
        "official_source_parity_proof_required": True,
        "official_source_parity_proof_attached": source_parity_attached,
        "source_parity_binding": source_parity_binding,
        "local_hiv1_adaptation": not source_faithful,
        "use_hierarchical_feature_grid": hierarchical_grid,
        "use_convnext_blocks": convnext_blocks,
        "local_grid_levels": int(getattr(cfg, "local_grid_levels", 0) or 0),
        "local_grid_channels": int(getattr(cfg, "local_grid_channels", 0) or 0),
        "convnext_mlp_ratio": int(getattr(cfg, "convnext_mlp_ratio", 0) or 0),
        "convnext_kernel_size": int(getattr(cfg, "convnext_kernel_size", 0) or 0),
        "decoder_codec": str(decoder_codec),
        "official_hinerv_blockers": official_hinerv_blockers,
        "source_parity_blockers": source_parity_blockers,
        "pr95_better_blockers": pr95_better_blockers,
        "blockers": [
            *official_hinerv_blockers,
            *source_parity_blockers,
            *pr95_better_blockers,
        ],
        "authority_note": (
            "This classifies source/architecture custody only. It is not score "
            "authority, and local HiNeRV/MLX rows remain false-authority until "
            "byte-closed archive/runtime plus contest CPU/CUDA replay."
        ),
        "score_claim": False,
        "frontier_score_claim": False,
        "promotion_eligible": False,
        "rank_or_kill_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }


def _hi_nerv_source_parity_binding() -> dict[str, Any]:
    return copy.deepcopy(_hi_nerv_source_parity_binding_cached())


@lru_cache(maxsize=1)
def _hi_nerv_source_parity_binding_cached() -> dict[str, Any]:
    """Return the long-training source-parity binding for HiNeRV rows."""

    contract = build_nerv_source_parity_contract(
        repo_root=REPO_ROOT,
        families=("hi_nerv",),
    )
    family_rows = [
        row for row in contract.get("family_rows") or () if isinstance(row, Mapping) and row.get("family") == "hi_nerv"
    ]
    family_row = family_rows[0] if family_rows else {}
    blockers = [
        f"source_parity:{blocker}"
        for blocker in (family_row.get("blockers") if isinstance(family_row, Mapping) else ())
    ]
    feature_statuses = {
        str(row.get("feature_id")): str(row.get("status"))
        for row in contract.get("feature_rows") or ()
        if isinstance(row, Mapping) and row.get("family") == "hi_nerv"
    }
    return {
        "schema": "hi_nerv_source_parity_binding.v1",
        "contract_schema": contract.get("schema"),
        "contract_authority": contract.get("authority"),
        "contract_attached": contract.get("schema") == "nerv_source_parity_contract.v1",
        "required_for_long_training_ready": bool(contract.get("required_for_long_training_ready")),
        "required_blockers": blockers,
        "nonblocking_gaps": [f"source_parity:{gap}" for gap in contract.get("nonblocking_gaps") or ()],
        "feature_statuses": feature_statuses,
        "score_claim": False,
        "frontier_score_claim": False,
        "promotion_eligible": False,
        "rank_or_kill_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }


def _hi_nerv_source_faithfulness_metadata(*, cfg: Any, decoder_codec: str) -> dict[str, Any]:
    """Return source-faithfulness facts safe for nested substrate metadata.

    ``_hi_nerv_source_faithfulness_report`` is also used as a top-level report
    surface and therefore carries canonical false-authority fields. The shared
    MLX harness intentionally rejects those fields inside
    ``substrate_artifact_metadata`` so there is one custody surface. Keep the
    source-control signal, strip only authority/readiness flags at the boundary.
    """

    report = _hi_nerv_source_faithfulness_report(
        cfg=cfg,
        decoder_codec=decoder_codec,
    )
    return strip_candidate_curriculum_authority_fields(report)


_SUBSTRATE_METADATA_AUTHORITY_KEYS = frozenset(
    {
        "score_claim",
        "frontier_score_claim",
        "rank_or_kill_eligible",
        "promotion_eligible",
        "ready_for_exact_eval_dispatch",
        "promotable",
        "score_claim_valid",
    }
)


def _strip_substrate_metadata_authority_fields(value: Any) -> Any:
    """Return a nested metadata copy accepted by RendererBundle guards."""

    if isinstance(value, Mapping):
        return {
            str(key): _strip_substrate_metadata_authority_fields(item)
            for key, item in value.items()
            if str(key) not in _SUBSTRATE_METADATA_AUTHORITY_KEYS
        }
    if isinstance(value, list):
        return [_strip_substrate_metadata_authority_fields(item) for item in value]
    if isinstance(value, tuple):
        return [_strip_substrate_metadata_authority_fields(item) for item in value]
    return value


def _positive_int_from_controls(
    controls: Mapping[str, Any],
    *,
    keys: Sequence[str],
    default: int,
) -> int:
    for key in keys:
        if key not in controls:
            continue
        try:
            value = int(controls.get(key))
        except (TypeError, ValueError) as exc:
            raise CompactRendererMlxSpineRunnerError(
                f"{key} must be a positive integer; got {controls.get(key)!r}"
            ) from exc
        if value <= 0:
            raise CompactRendererMlxSpineRunnerError(f"{key} must be a positive integer; got {value}")
        return value
    return int(default)


def _hi_nerv_section_metric_payload_from_telemetry(
    telemetry: Mapping[str, Any],
    *,
    source: str,
    refresh_call: int,
    refresh_every_steps: int,
    fallback_archive_bytes: int | None = None,
) -> dict[str, Any]:
    if str(telemetry.get("schema") or "") != "hinerv_archive_section_telemetry.v1":
        raise CompactRendererMlxSpineRunnerError("live HiNeRV archive-section telemetry schema mismatch")
    if telemetry.get("profile_ready") is not True:
        raise CompactRendererMlxSpineRunnerError("live HiNeRV archive-section telemetry is not profile_ready")
    sections = telemetry.get("sections")
    if not isinstance(sections, Sequence) or isinstance(sections, (str, bytes)):
        raise CompactRendererMlxSpineRunnerError("live HiNeRV archive-section telemetry is missing sections")
    section_bytes: dict[str, int] = {}
    for index, row in enumerate(sections):
        if not isinstance(row, Mapping):
            continue
        name = str(row.get("name") or f"section_{index:04d}")
        try:
            nbytes = int(row.get("bytes") or 0)
        except (TypeError, ValueError):
            continue
        if name and nbytes > 0:
            section_bytes[name] = nbytes
    if not section_bytes:
        raise CompactRendererMlxSpineRunnerError("live HiNeRV archive-section telemetry has no positive-byte sections")
    archive_bytes = None
    for key in ("archive_zip_bytes", "inner_payload_bytes"):
        try:
            parsed = int(telemetry.get(key) or 0)
        except (TypeError, ValueError):
            parsed = 0
        if parsed > 0:
            archive_bytes = parsed
            break
    if archive_bytes is None:
        archive_bytes = (
            int(fallback_archive_bytes)
            if fallback_archive_bytes is not None and int(fallback_archive_bytes) > 0
            else int(sum(section_bytes.values()))
        )
    return {
        "schema": "hi_nerv_live_train_time_section_byte_metrics.v1",
        "archive_bytes": int(archive_bytes),
        "section_bytes": dict(sorted(section_bytes.items())),
        "source": str(source),
        "live_profile": {
            "refresh_call": int(refresh_call),
            "refresh_every_steps": int(refresh_every_steps),
        },
        "authority": "macos_mlx_research_signal_false_authority",
        "blockers": ["live_metrics_are_inner_hiv1_packet_bytes_until_export_zip_replay"],
    }


def _hi_nerv_startup_archive_section_telemetry_from_model(
    *,
    model: Any,
    cfg: Any,
    decoder_codec: str,
    latent_codec: str,
    decoder_weight_waterfill_plan: Mapping[str, Any] | None,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    """Measure initial live HIV1 sections so byte caps act from step zero."""

    metadata: dict[str, Any] = {
        "schema": "hi_nerv_startup_archive_section_telemetry_from_model.v1",
        "generated_from_initial_model": True,
        "validated": False,
        "packet_grammar": "HIV1",
        "decoder_codec": str(decoder_codec),
        "latent_codec": str(latent_codec),
        "source": "initial_model_export_state_dict_in_memory_hiv1_pack",
        "writes_artifacts": False,
        "blockers": [],
        "authority": "macos_mlx_research_signal_false_authority",
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }
    export_state_dict = getattr(model, "export_state_dict", None)
    if not callable(export_state_dict):
        metadata["blockers"] = ["hi_nerv_startup_model_export_state_dict_missing"]
        return None, metadata
    try:
        exported_state_dict = export_state_dict()
        if not isinstance(exported_state_dict, Mapping):
            raise CompactRendererMlxSpineRunnerError(
                f"HiNeRV startup export_state_dict returned {type(exported_state_dict).__name__}, expected Mapping"
            )
        from tac.substrates.hi_nerv.archive import build_archive_section_telemetry
        from tac.substrates.hi_nerv.archive_candidate import (
            pack_archive_from_exported_state_dict,
        )

        packet_bytes = pack_archive_from_exported_state_dict(
            exported_state_dict=dict(exported_state_dict),
            cfg=cfg,
            decoder_codec=str(decoder_codec),
            decoder_weight_waterfill_plan=decoder_weight_waterfill_plan,
            latent_codec=str(latent_codec),
        )
        if isinstance(packet_bytes, tuple):
            packet_bytes = packet_bytes[0]
        telemetry = build_archive_section_telemetry(packet_bytes)
        if not isinstance(telemetry, Mapping):
            raise CompactRendererMlxSpineRunnerError(
                f"build_archive_section_telemetry returned {type(telemetry).__name__}, expected Mapping"
            )
        sections = telemetry.get("sections")
        metadata.update(
            {
                "validated": bool(
                    telemetry.get("schema") == "hinerv_archive_section_telemetry.v1"
                    and telemetry.get("profile_ready") is True
                ),
                "source_schema": telemetry.get("schema"),
                "profile_ready": telemetry.get("profile_ready"),
                "archive_zip_bytes": telemetry.get("archive_zip_bytes"),
                "inner_payload_bytes": telemetry.get("inner_payload_bytes"),
                "section_payload_bytes": telemetry.get("section_payload_bytes"),
                "section_count": (
                    len(sections) if isinstance(sections, Sequence) and not isinstance(sections, (str, bytes)) else 0
                ),
            }
        )
        if not metadata["validated"]:
            metadata["blockers"] = ["hi_nerv_startup_archive_section_telemetry_not_profile_ready"]
            return dict(telemetry), metadata
        return dict(telemetry), metadata
    except Exception as exc:
        metadata["blockers"] = [f"hi_nerv_startup_archive_section_telemetry_failed:{type(exc).__name__}:{exc}"]
        return None, metadata


def _build_hi_nerv_live_train_time_section_byte_metrics_callback(
    *,
    cfg: Any,
    decoder_codec: str,
    latent_codec: str,
    decoder_weight_waterfill_plan: Mapping[str, Any] | None,
    train_time_section_byte_control: Mapping[str, Any],
    optimizer_controls: Mapping[str, Any],
) -> tuple[
    Callable[[Any, Any, Mapping[str, float]], Mapping[str, Any] | None] | None,
    dict[str, Any],
]:
    """Build a live HIV1 section-byte callback for HiNeRV long training.

    The prior control surface priced section bytes from startup/export
    telemetry.  This callback re-packs the current MLX model state into the
    real receiver-visible HIV1 grammar at a bounded interval, entirely in
    memory, so the existing dual-ascent controller tracks current decoder and
    latent bytes during training.
    """

    static_payload_obj = train_time_section_byte_control.get("metrics_payload")
    static_payload = dict(static_payload_obj) if isinstance(static_payload_obj, Mapping) else None
    refresh_every = _positive_int_from_controls(
        optimizer_controls,
        keys=(
            "hi_nerv_live_section_byte_refresh_every_steps",
            "section_byte_refresh_every_steps",
            "train_time_section_byte_refresh_every_steps",
        ),
        default=25,
    )
    metadata: dict[str, Any] = {
        "schema": "hi_nerv_live_train_time_section_byte_metrics_callback.v1",
        "enabled": static_payload is not None,
        "refresh_every_steps": int(refresh_every),
        "packet_grammar": "HIV1",
        "decoder_codec": str(decoder_codec),
        "latent_codec": str(latent_codec),
        "uses_current_export_state_dict": True,
        "writes_artifacts": False,
        "source": "in_memory_pack_archive_from_current_mlx_state",
        "fallback_source": ("startup_archive_section_telemetry" if static_payload is not None else None),
        "fallback_static_archive_bytes": (
            static_payload.get("archive_bytes") if isinstance(static_payload, Mapping) else None
        ),
        "refresh_call_count": 0,
        "successful_refresh_count": 0,
        "fallback_count": 0,
        "blockers": []
        if static_payload is not None
        else ["hi_nerv_live_section_byte_callback_requires_startup_metrics_payload"],
        "authority": "macos_mlx_research_signal_false_authority",
    }
    if static_payload is None:
        return None, metadata

    state: dict[str, Any] = {
        "call_count": 0,
        "last_payload": None,
        "last_blocker": None,
    }

    def _fallback_payload(blocker: str) -> Mapping[str, Any] | None:
        metadata["fallback_count"] = int(metadata.get("fallback_count") or 0) + 1
        blockers = [str(value) for value in metadata.get("blockers") or []]
        blockers.append(str(blocker))
        metadata["blockers"] = _dedupe(blockers)
        state["last_blocker"] = str(blocker)
        if isinstance(state.get("last_payload"), Mapping):
            payload = dict(state["last_payload"])
        else:
            payload = dict(static_payload)
            payload["source"] = "startup_archive_section_telemetry_fallback"
        payload["schema"] = "hi_nerv_train_time_section_byte_metrics_fallback.v1"
        payload["blockers"] = _dedupe([*list(payload.get("blockers") or []), str(blocker)])
        payload["authority"] = "macos_mlx_research_signal_false_authority"
        return payload

    def _callback(
        model_obj: Any,
        _idx: Any,
        _loss_weights: Mapping[str, float],
    ) -> Mapping[str, Any] | None:
        state["call_count"] = int(state.get("call_count") or 0) + 1
        call_count = int(state["call_count"])
        should_refresh = state.get("last_payload") is None or (call_count - 1) % int(refresh_every) == 0
        if not should_refresh and isinstance(state.get("last_payload"), Mapping):
            payload = dict(state["last_payload"])
            live_profile = dict(payload.get("live_profile") or {})
            live_profile["cache_hit"] = True
            live_profile["callback_call"] = call_count
            payload["live_profile"] = live_profile
            return payload
        export_state_dict = getattr(model_obj, "export_state_dict", None)
        if not callable(export_state_dict):
            return _fallback_payload("hi_nerv_model_export_state_dict_missing")
        try:
            exported_state_dict = export_state_dict()
            if not isinstance(exported_state_dict, Mapping):
                raise CompactRendererMlxSpineRunnerError(
                    f"HiNeRV export_state_dict returned {type(exported_state_dict).__name__}, expected Mapping"
                )
            from tac.substrates.hi_nerv.archive import build_archive_section_telemetry
            from tac.substrates.hi_nerv.archive_candidate import (
                pack_archive_from_exported_state_dict,
            )

            packet_bytes = pack_archive_from_exported_state_dict(
                exported_state_dict=dict(exported_state_dict),
                cfg=cfg,
                decoder_codec=str(decoder_codec),
                decoder_weight_waterfill_plan=decoder_weight_waterfill_plan,
                latent_codec=str(latent_codec),
            )
            if isinstance(packet_bytes, tuple):
                packet_bytes = packet_bytes[0]
            telemetry = build_archive_section_telemetry(packet_bytes)
            if not isinstance(telemetry, Mapping):
                raise CompactRendererMlxSpineRunnerError(
                    f"build_archive_section_telemetry returned {type(telemetry).__name__}, expected Mapping"
                )
            payload = _hi_nerv_section_metric_payload_from_telemetry(
                telemetry,
                source="live_current_hiv1_packet",
                refresh_call=call_count,
                refresh_every_steps=refresh_every,
                fallback_archive_bytes=static_payload.get("archive_bytes"),
            )
        except Exception as exc:
            return _fallback_payload(f"hi_nerv_live_section_byte_refresh_failed:{type(exc).__name__}:{exc}")
        state["last_payload"] = dict(payload)
        metadata["refresh_call_count"] = call_count
        metadata["successful_refresh_count"] = int(metadata.get("successful_refresh_count") or 0) + 1
        metadata["last_live_archive_bytes"] = int(payload["archive_bytes"])
        metadata["last_live_section_bytes"] = dict(payload["section_bytes"])
        metadata["last_refresh_call"] = call_count
        metadata["last_refresh_blocker"] = None
        return payload

    return _callback, metadata


