def _snapshot_mlx_model_parameters(model: Any) -> list[tuple[Any, Any]]:
    try:
        import mlx.core as mx
        from mlx.utils import tree_flatten
    except Exception as exc:  # pragma: no cover - environment guard
        raise CompactRendererMlxSpineRunnerError(
            "MLX parameter snapshot requires mlx.utils.tree_flatten"
        ) from exc
    snapshot: list[tuple[Any, Any]] = []
    for raw_name, leaf in tree_flatten(model.parameters()):
        snapshot.append((raw_name, mx.array(leaf)))
    mx.eval(*[leaf for _name, leaf in snapshot])
    return snapshot


def _restore_mlx_model_parameters(model: Any, snapshot: list[tuple[Any, Any]]) -> None:
    try:
        import mlx.core as mx
        from mlx.utils import tree_unflatten
    except Exception as exc:  # pragma: no cover - environment guard
        raise CompactRendererMlxSpineRunnerError(
            "MLX parameter restore requires mlx.utils.tree_unflatten"
        ) from exc
    model.update(tree_unflatten([(name, mx.array(value)) for name, value in snapshot]))
    mx.eval(model.parameters())


def _hi_nerv_pose_trusted_birth_payload_blockers(payload: Mapping[str, Any]) -> list[str]:
    """Return fail-closed blockers for an accepted pose-trusted birth payload."""

    blockers: list[str] = []
    receipt_raw = payload.get("receipt")
    receipt = receipt_raw if isinstance(receipt_raw, Mapping) else {}
    row = receipt if receipt else payload
    if str(row.get("schema") or "") != "hi_nerv_target_region_birth_receipt.v1":
        blockers.append("hi_nerv_pose_trusted_birth_receipt_missing")
    if int(row.get("accepted_step_count") or payload.get("accepted_step_count") or 0) <= 0:
        blockers.append("hi_nerv_pose_trusted_birth_accepted_step_missing")

    transitions_raw = row.get("argmax_transitions")
    transitions = transitions_raw if isinstance(transitions_raw, Mapping) else row
    hard_won = transitions.get("target_hard_won_count")
    net_support = transitions.get("net_target_support_delta")
    if not isinstance(hard_won, (int, float)) or float(hard_won) <= 0.0:
        blockers.append("hi_nerv_pose_trusted_birth_target_hard_won_missing")
    if not isinstance(net_support, (int, float)) or float(net_support) <= 0.0:
        blockers.append("hi_nerv_pose_trusted_birth_net_support_not_positive")
    lost_fields = (
        ("target_hard_lost_count", "hi_nerv_pose_trusted_birth_target_hard_lost"),
        ("target_to_wrong_count", "hi_nerv_pose_trusted_birth_target_to_wrong"),
    )
    for field, blocker in lost_fields:
        value = transitions.get(field)
        if value is None:
            value = row.get(field)
        if isinstance(value, (int, float)) and float(value) > 0.0:
            blockers.append(blocker)

    pose_guard_raw = row.get("pose_guard")
    pose_guard = pose_guard_raw if isinstance(pose_guard_raw, Mapping) else {}
    if pose_guard.get("available") is not True:
        blockers.append("hi_nerv_pose_trusted_birth_pose_guard_missing")
    if pose_guard.get("pose_input_contest_resolution") is not True:
        blockers.append("hi_nerv_pose_trusted_birth_pose_input_not_contest_resolution")
    accepted_delta = pose_guard.get("max_accepted_pose_output_delta_l2")
    pose_cap = pose_guard.get("max_pose_output_delta_l2")
    if not isinstance(accepted_delta, (int, float)) or not isinstance(pose_cap, (int, float)):
        blockers.append("hi_nerv_pose_trusted_birth_pose_cap_telemetry_missing")
    elif (
        float(accepted_delta) > float(pose_cap)
        and pose_guard.get("raw_pose_cap_is_counterfactual_only") is not True
    ):
        blockers.append("hi_nerv_pose_trusted_birth_pose_cap_exceeded")

    nonrate_raw = row.get("exact_nonrate")
    nonrate = nonrate_raw if isinstance(nonrate_raw, Mapping) else {}
    delta_score = nonrate.get("delta_score_nonrate")
    if nonrate.get("pose_term_available") is not True:
        blockers.append("hi_nerv_pose_trusted_birth_pose_nonrate_missing")
    if not isinstance(delta_score, (int, float)) or float(delta_score) >= 0.0:
        blockers.append("hi_nerv_pose_trusted_birth_exact_nonrate_not_improved")

    frontier_raw = row.get("candidate_frontier_telemetry")
    frontier = frontier_raw if isinstance(frontier_raw, Mapping) else {}
    if int(frontier.get("candidate_attempt_count") or 0) <= 0:
        blockers.append("hi_nerv_pose_trusted_birth_candidate_frontier_missing")
    already_won_lost = frontier.get("final_already_won_lost_count")
    if isinstance(already_won_lost, (int, float)) and float(already_won_lost) > 0.0:
        blockers.append("hi_nerv_pose_trusted_birth_already_won_lost")

    compensation_raw = row.get("pose_compensation")
    compensation = compensation_raw if isinstance(compensation_raw, Mapping) else None
    if compensation is not None and compensation.get("composite_accepted") is True:
        if compensation.get("frame1_receiver_uint8_unchanged_by_compensation") is not True:
            blockers.append("hi_nerv_pose_trusted_birth_compensation_moved_frame1")
        birth_names = {str(name) for name in (row.get("updated_parameter_names") or [])}
        compensation_names = [str(name) for name in (compensation.get("compensation_updated_parameter_names") or [])]
        if not compensation_names:
            blockers.append("hi_nerv_pose_trusted_birth_compensation_names_missing")
        for name in compensation_names:
            if not name.startswith("head_rgb_0"):
                blockers.append("hi_nerv_pose_trusted_birth_compensation_scope_escape")
                break
            if name in birth_names:
                blockers.append("hi_nerv_pose_trusted_birth_compensation_in_birth_scope")
                break

    admission_rows: list[Mapping[str, Any]] = []
    frontier_attempts = frontier.get("attempts")
    if isinstance(frontier_attempts, Sequence) and not isinstance(frontier_attempts, (str, bytes)):
        admission_rows.extend(row for row in frontier_attempts if isinstance(row, Mapping))
    if compensation is not None:
        compensation_attempts = compensation.get("attempts")
        if isinstance(compensation_attempts, Sequence) and not isinstance(compensation_attempts, (str, bytes)):
            admission_rows.extend(row for row in compensation_attempts if isinstance(row, Mapping))

    def _decision_text(source: Mapping[str, Any], *keys: str) -> str:
        for key in keys:
            value = source.get(key)
            if value is not None:
                return str(value)
        return ""

    v6_decision_seen = any(
        _decision_text(row, "exact_score_decision", "composite_exact_score_decision")
        or _decision_text(row, "catastrophic_guard_decision", "composite_catastrophic_guard_decision")
        for row in admission_rows
    )
    if v6_decision_seen and not any(
        _decision_text(row, "exact_score_decision", "composite_exact_score_decision") == "accepted"
        and _decision_text(row, "catastrophic_guard_decision", "composite_catastrophic_guard_decision")
        == "satisfied"
        for row in admission_rows
    ):
        blockers.append("hi_nerv_pose_trusted_birth_v6_admission_decision_missing")

    return _dedupe(blockers)


def _write_hi_nerv_runner_live_birth_survival_rows(
    *,
    model: Any,
    output_dir: str | Path,
    live_birth_payload: Mapping[str, Any] | None,
    scorer_teacher: Any | None,
    target_labels: Any | None,
    pair_indices: Any | None,
    pose_teacher: Any | None = None,
    target_rgb_0: Any | None = None,
    target_rgb_1: Any | None = None,
    fakequant_bits: int = 8,
    hysteresis_extra_steps: int = 3,
    hysteresis_learning_rate: float = 2.0e-3,
) -> dict[str, Any]:
    """Write live hard-birth survival rows that do not mutate training state."""

    if not isinstance(live_birth_payload, Mapping):
        return {}
    receipt = live_birth_payload.get("receipt")
    receipt = receipt if isinstance(receipt, Mapping) else {}
    action_id = str(live_birth_payload.get("action_id") or receipt.get("action_id") or "")
    if not action_id:
        return {}

    out = Path(output_dir).expanduser().resolve(strict=False)
    out.mkdir(parents=True, exist_ok=True)

    def _blocked(
        schema: str,
        path: Path,
        blocker: str,
        reason: str | None = None,
        extra: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        row = {
            "schema": schema,
            "action_id": action_id,
            "blocked": True,
            "blocker": blocker,
            "blockers": [blocker],
            "reason": reason or blocker,
            "producer": "hi_nerv_runner_live_birth_survival",
            "human_visual_fidelity_objective": False,
            "score_claim": False,
            "promotion_eligible": False,
            "ready_for_exact_eval_dispatch": False,
            **FALSE_AUTHORITY,
        }
        if isinstance(extra, Mapping):
            row.update(dict(extra))
        row["artifact_path"] = path.as_posix()
        _write_json(path, row)
        return row

    summary: dict[str, Any] = {
        "schema": "hi_nerv_runner_live_birth_survival_bundle.v1",
        "action_id": action_id,
        "producer": "hi_nerv_runner_live_birth_survival",
        "fakequant_survival_path": None,
        "hysteresis_path": None,
        "blockers": [],
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }

    def _write_four_arm_action_effect_rows() -> tuple[int, list[str]]:
        action_effect_ledger_path = out / "hi_nerv_birth_action_effects.jsonl"
        blockers: list[str] = []
        rows_written = 0
        try:
            from tac.analysis.action_effect import ActionEffect, append_action_effect

            for four_arm_effect in ActionEffect.from_hinerv_four_arm_ablation(
                live_birth_payload,
                consumer="nerv_long_run_launch_gate",
            ):
                append_action_effect(four_arm_effect, action_effect_ledger_path)
                rows_written += 1
        except Exception as exc:
            blockers.append(
                f"hi_nerv_birth_four_arm_action_effect_write_failed:{type(exc).__name__}:{exc}"
            )
        summary["action_effect_ledger_path"] = action_effect_ledger_path.as_posix()
        summary["action_effect_rows_written"] = rows_written
        summary["four_arm_action_effect_rows_written"] = rows_written
        return rows_written, blockers

    if "accepted" in live_birth_payload and live_birth_payload.get("accepted") is not True:
        payload_blockers = [str(value) for value in live_birth_payload.get("blockers") or []]
        blocker = "birth_survival_live_birth_not_accepted"
        summary["birth_accepted"] = False
        summary["blockers"] = [blocker, *payload_blockers]
        summary["live_birth_blockers"] = payload_blockers
        fake_path = out / "hi_nerv_birth_fakequant_survival.json"
        hyst_path = out / "hi_nerv_birth_hysteresis.json"
        blocked_extra = {
            "accepted": False,
            "source_schema": str(live_birth_payload.get("schema") or ""),
            "source_blockers": payload_blockers,
            "source_birth_surface": str(live_birth_payload.get("surface") or "live_mlx"),
        }
        _blocked(
            "hi_nerv_target_region_birth_survival_blocked.v1",
            fake_path,
            blocker,
            reason="live target-region hard birth did not pass its acceptance gate",
            extra=blocked_extra,
        )
        _blocked(
            "hi_nerv_target_region_birth_hysteresis_blocked.v1",
            hyst_path,
            blocker,
            reason="live target-region hard birth did not pass its acceptance gate",
            extra=blocked_extra,
        )
        summary["fakequant_survival_path"] = fake_path.as_posix()
        summary["hysteresis_path"] = hyst_path.as_posix()
        _rows_written, action_effect_blockers = _write_four_arm_action_effect_rows()
        if action_effect_blockers:
            summary["blockers"] = _dedupe([*[str(value) for value in summary.get("blockers") or []], *action_effect_blockers])
        return summary
    if scorer_teacher is None or target_labels is None or pair_indices is None:
        missing = []
        if scorer_teacher is None:
            missing.append("birth_survival_live_scorer_teacher_missing")
        if target_labels is None:
            missing.append("birth_survival_live_target_labels_missing")
        if pair_indices is None:
            missing.append("birth_survival_live_pair_indices_missing")
        summary["blockers"] = missing
        fake_path = out / "hi_nerv_birth_fakequant_survival.json"
        hyst_path = out / "hi_nerv_birth_hysteresis.json"
        _blocked("hi_nerv_target_region_birth_survival_blocked.v1", fake_path, missing[0])
        _blocked("hi_nerv_target_region_birth_hysteresis_blocked.v1", hyst_path, missing[0])
        summary["fakequant_survival_path"] = fake_path.as_posix()
        summary["hysteresis_path"] = hyst_path.as_posix()
        return summary

    from tac.substrates.hi_nerv.birth_survival import (
        measure_birth_hysteresis,
        measure_birth_survival,
    )

    fake_path = out / "hi_nerv_birth_fakequant_survival.json"
    action_effect_ledger_path = out / "hi_nerv_birth_action_effects.jsonl"
    try:
        fake_row = dict(
            measure_birth_survival(
                model,
                scorer_teacher=scorer_teacher,
                pose_teacher=pose_teacher,
                target_rgb_0=target_rgb_0,
                target_rgb_1=target_rgb_1,
                target_labels=target_labels,
                live_birth_payload=live_birth_payload,
                surface="fakequant_mlx",
                pair_indices=pair_indices,
                fakequant_bits=int(fakequant_bits),
            )
        )
    except Exception as exc:
        fake_row = _blocked(
            "hi_nerv_target_region_birth_survival_blocked.v1",
            fake_path,
            "birth_survival_fakequant_remeasurement_failed",
            reason=f"{type(exc).__name__}:{exc}",
        )
    else:
        fake_row["artifact_path"] = fake_path.as_posix()
        fake_row["producer"] = "hi_nerv_runner_live_birth_survival"
        _write_json(fake_path, fake_row)
    summary["fakequant_survival_path"] = fake_path.as_posix()
    summary["fakequant_survived"] = fake_row.get("survived")
    summary["fakequant_blockers"] = [str(value) for value in fake_row.get("blockers") or []]
    summary["action_effect_ledger_path"] = action_effect_ledger_path.as_posix()
    try:
        from tac.analysis.action_effect import ActionEffect, append_action_effect

        rows_written = 0
        four_arm_rows_written = 0
        source_receipt = dict(receipt or live_birth_payload)
        source_receipt["fakequant_survived"] = fake_row.get("survived") is True
        try:
            action_effect = ActionEffect.from_hinerv_birth_receipt(
                source_receipt,
                consumer="nerv_long_run_launch_gate",
            )
        except Exception as exc:
            blocker = f"hi_nerv_birth_base_action_effect_write_failed:{type(exc).__name__}:{exc}"
            summary["blockers"] = _dedupe([*[str(value) for value in summary.get("blockers") or []], blocker])
        else:
            append_action_effect(action_effect, action_effect_ledger_path)
            rows_written += 1
        four_arm_rows_written, four_arm_blockers = _write_four_arm_action_effect_rows()
        rows_written += four_arm_rows_written
        if four_arm_blockers:
            summary["blockers"] = _dedupe([*[str(value) for value in summary.get("blockers") or []], *four_arm_blockers])
        summary["action_effect_rows_written"] = rows_written
        summary["four_arm_action_effect_rows_written"] = four_arm_rows_written
    except Exception as exc:
        blocker = f"hi_nerv_birth_action_effect_write_failed:{type(exc).__name__}:{exc}"
        summary["action_effect_rows_written"] = 0
        summary["four_arm_action_effect_rows_written"] = 0
        summary["blockers"] = _dedupe([*[str(value) for value in summary.get("blockers") or []], blocker])

    hyst_path = out / "hi_nerv_birth_hysteresis.json"
    snapshot: list[tuple[Any, Any]] | None = None
    try:
        snapshot = _snapshot_mlx_model_parameters(model)
        hyst_row = dict(
            measure_birth_hysteresis(
                model,
                scorer_teacher=scorer_teacher,
                target_rgb_0=target_rgb_0,
                target_rgb_1=target_rgb_1,
                target_labels=target_labels,
                live_birth_payload=live_birth_payload,
                pair_indices=pair_indices,
                extra_steps=int(hysteresis_extra_steps),
                learning_rate=float(hysteresis_learning_rate),
            )
        )
    except Exception as exc:
        hyst_row = _blocked(
            "hi_nerv_target_region_birth_hysteresis_blocked.v1",
            hyst_path,
            "birth_hysteresis_remeasurement_failed",
            reason=f"{type(exc).__name__}:{exc}",
        )
    finally:
        if snapshot is not None:
            _restore_mlx_model_parameters(model, snapshot)
    hyst_row["artifact_path"] = hyst_path.as_posix()
    hyst_row["producer"] = "hi_nerv_runner_live_birth_survival"
    _write_json(hyst_path, hyst_row)
    summary["hysteresis_path"] = hyst_path.as_posix()
    summary["hysteresis_passed"] = hyst_row.get("passed")
    summary["hysteresis_blockers"] = [str(value) for value in hyst_row.get("blockers") or []]
    summary["blockers"] = [
        *[str(value) for value in summary.get("blockers") or []],
        *summary.get("fakequant_blockers", []),
        *summary.get("hysteresis_blockers", []),
    ]
    return summary


def _write_hi_nerv_runner_birth_parseback_survival_for_archive(
    *,
    archive_path: str | Path,
    output_dir: str | Path,
    live_birth_payload: Mapping[str, Any] | None,
    scorer_teacher: Any | None,
    target_labels: Any | None,
    pair_indices: Any | None,
    pose_teacher: Any | None = None,
    target_rgb_0: Any | None = None,
    target_rgb_1: Any | None = None,
    candidate_kind: str = "",
    canonical_for_launch_gate: bool = True,
) -> dict[str, Any] | None:
    """Write same-action parseback survival evidence for a HiNeRV hard birth."""

    if not isinstance(live_birth_payload, Mapping):
        return None
    receipt = live_birth_payload.get("receipt")
    receipt = receipt if isinstance(receipt, Mapping) else {}
    action_id = str(live_birth_payload.get("action_id") or receipt.get("action_id") or "")
    if not action_id:
        return None

    out = Path(output_dir).expanduser().resolve(strict=False)
    out.mkdir(parents=True, exist_ok=True)
    safe_kind = "".join(
        ch if ch.isalnum() or ch in {"-", "_"} else "_"
        for ch in str(candidate_kind or "archive")
    )
    row_path = out / f"hi_nerv_birth_parseback_survival_{safe_kind}.json"

    def _blocked(
        blocker: str,
        reason: str | None = None,
        extra: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        row = {
            "schema": (
                "hi_nerv_target_region_birth_survival_blocked.v1"
                if canonical_for_launch_gate
                else "hi_nerv_target_region_birth_survival_candidate_blocked.v1"
            ),
            "surface": "parseback_mlx",
            "action_id": action_id,
            "candidate_kind": str(candidate_kind or ""),
            "archive_path": str(archive_path),
            "blocker": blocker,
            "blockers": [blocker],
            "reason": reason or blocker,
            "producer": "hi_nerv_runner_archive_selection_birth_parseback_survival",
            "score_claim": False,
            "promotion_eligible": False,
            "ready_for_exact_eval_dispatch": False,
            **FALSE_AUTHORITY,
        }
        if isinstance(extra, Mapping):
            row.update(dict(extra))
        row["artifact_path"] = row_path.as_posix()
        _write_json(row_path, row)
        return row

    if "accepted" in live_birth_payload and live_birth_payload.get("accepted") is not True:
        payload_blockers = [str(value) for value in live_birth_payload.get("blockers") or []]
        return _blocked(
            "birth_survival_parseback_live_birth_not_accepted",
            reason="live target-region hard birth did not pass its acceptance gate",
            extra={
                "accepted": False,
                "source_schema": str(live_birth_payload.get("schema") or ""),
                "source_blockers": payload_blockers,
                "source_birth_surface": str(live_birth_payload.get("surface") or "live_mlx"),
            },
        )

    archive = Path(archive_path).expanduser().resolve(strict=False)
    if not archive.is_file():
        return _blocked("birth_survival_parseback_archive_zip_missing")
    if scorer_teacher is None:
        return _blocked("birth_survival_parseback_scorer_teacher_missing")
    if target_labels is None:
        return _blocked("birth_survival_parseback_target_labels_missing")
    if pair_indices is None:
        return _blocked("birth_survival_parseback_pair_indices_missing")

    parseback_report = {
        "schema": "hi_nerv_runner_archive_selection_parseback_report.v1",
        "archive_path": archive.as_posix(),
        "archive_sha256": _sha256_file(archive),
        "archive_bytes": int(archive.stat().st_size),
        "action_id": action_id,
        "candidate_kind": str(candidate_kind or ""),
        "producer": "hi_nerv_runner_archive_selection_birth_parseback_survival",
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
        **FALSE_AUTHORITY,
    }
    try:
        from tac.substrates.hi_nerv.birth_survival import (
            measure_birth_parseback_survival_from_report,
        )

        row = dict(
            measure_birth_parseback_survival_from_report(
                parseback_report=parseback_report,
                scorer_teacher=scorer_teacher,
                pose_teacher=pose_teacher,
                target_rgb_0=target_rgb_0,
                target_rgb_1=target_rgb_1,
                target_labels=target_labels,
                live_birth_payload=live_birth_payload,
                pair_indices=pair_indices,
            )
        )
    except Exception as exc:
        return _blocked(
            "birth_survival_parseback_remeasurement_failed",
            reason=f"{type(exc).__name__}:{exc}",
        )

    row["candidate_kind"] = str(candidate_kind or "")
    if not canonical_for_launch_gate:
        row["source_schema"] = row.get("schema")
        row["schema"] = "hi_nerv_target_region_birth_survival_candidate.v1"
        row["canonical_launch_gate_schema"] = False
    row["artifact_path"] = row_path.as_posix()
    row["producer"] = "hi_nerv_runner_archive_selection_birth_parseback_survival"
    action_effect_ledger_path = row_path.with_name("hi_nerv_birth_action_effects.jsonl")
    try:
        from tac.analysis.action_effect import ActionEffect, append_action_effect

        action_effect = ActionEffect.build(
            action_id=action_id,
            family="hinerv",
            authority="parseback_mlx",
            producer="hi_nerv_runner_archive_selection_birth_parseback_survival",
            consumer="nerv_long_run_launch_gate",
            parseback_survived=row.get("survived") is True,
        )
        append_action_effect(action_effect, action_effect_ledger_path)
        row["action_effect_ledger_path"] = action_effect_ledger_path.as_posix()
        row["action_effect_rows_written"] = 1
    except Exception as exc:
        row["action_effect_ledger_path"] = action_effect_ledger_path.as_posix()
        row["action_effect_rows_written"] = 0
        row["blockers"] = _dedupe(
            [
                *[str(value) for value in row.get("blockers") or []],
                f"hi_nerv_birth_parseback_action_effect_write_failed:{type(exc).__name__}:{exc}",
            ]
        )
    _write_json(row_path, row)
    return row


def _promote_hi_nerv_selected_birth_parseback_survival(
    *,
    archive_resolution: Mapping[str, Any],
    output_dir: str | Path,
    artifact_dict: dict[str, Any],
) -> dict[str, Any] | None:
    archive_raw = archive_resolution.get("archive_path")
    if not archive_raw:
        return None
    archive = Path(str(archive_raw)).expanduser().resolve(strict=False)
    if not archive.is_file():
        return None
    candidate_kind = str(archive_resolution.get("candidate_kind") or "archive")
    safe_kind = "".join(ch if ch.isalnum() or ch in {"-", "_"} else "_" for ch in candidate_kind)
    candidate_path = archive.parent / f"hi_nerv_birth_parseback_survival_{safe_kind}.json"
    if not candidate_path.is_file():
        matches = sorted(archive.parent.glob("hi_nerv_birth_parseback_survival_*.json"))
        candidate_path = matches[0] if matches else candidate_path
    if not candidate_path.is_file():
        return None
    try:
        row = _load_json(candidate_path)
    except Exception:
        return None
    if not isinstance(row, Mapping):
        return None
    if str(row.get("schema") or "") != "hi_nerv_target_region_birth_survival_candidate.v1":
        return None
    promoted = dict(row)
    promoted["source_schema"] = row.get("schema")
    promoted["schema"] = str(row.get("source_schema") or "hi_nerv_target_region_birth_survival.v1")
    promoted["canonical_launch_gate_schema"] = True
    promoted["selected_archive_path"] = archive.as_posix()
    promoted["selected_archive_sha256"] = archive_resolution.get("archive_sha256") or _sha256_file(archive)
    promoted["selected_candidate_kind"] = candidate_kind
    promoted["source_candidate_artifact_path"] = candidate_path.as_posix()
    promoted["producer"] = "hi_nerv_runner_selected_birth_parseback_survival"
    out = Path(output_dir).expanduser().resolve(strict=False)
    out.mkdir(parents=True, exist_ok=True)
    promoted_path = out / "hi_nerv_selected_birth_parseback_survival.json"
    promoted["artifact_path"] = promoted_path.as_posix()
    _write_json(promoted_path, promoted)

    artifact_dict["selected_birth_parseback_survival"] = dict(promoted)
    metadata = artifact_dict.get("substrate_artifact_metadata")
    if isinstance(metadata, dict):
        metadata["selected_birth_parseback_survival"] = dict(promoted)
        score_training = metadata.get("score_aware_training")
        if isinstance(score_training, dict):
            score_training["selected_birth_parseback_survival"] = {
                "schema": promoted.get("schema"),
                "surface": promoted.get("surface"),
                "action_id": promoted.get("action_id"),
                "survived": promoted.get("survived"),
                "artifact_path": promoted.get("artifact_path"),
                "selected_candidate_kind": promoted.get("selected_candidate_kind"),
                "blockers": [str(value) for value in promoted.get("blockers") or []],
                "score_claim": False,
                "promotion_eligible": False,
                "ready_for_exact_eval_dispatch": False,
            }
    artifact_path = out / "training_artifact.json"
    if artifact_path.is_file():
        try:
            artifact = json.loads(artifact_path.read_text(encoding="utf-8"))
        except Exception:
            artifact = None
        if isinstance(artifact, dict):
            artifact["selected_birth_parseback_survival"] = dict(promoted)
            artifact_metadata = dict(artifact.get("substrate_artifact_metadata") or {})
            artifact_metadata["selected_birth_parseback_survival"] = dict(promoted)
            score_training = artifact_metadata.get("score_aware_training")
            if isinstance(score_training, dict):
                score_training["selected_birth_parseback_survival"] = {
                    "schema": promoted.get("schema"),
                    "surface": promoted.get("surface"),
                    "action_id": promoted.get("action_id"),
                    "survived": promoted.get("survived"),
                    "artifact_path": promoted.get("artifact_path"),
                    "selected_candidate_kind": promoted.get("selected_candidate_kind"),
                    "blockers": [str(value) for value in promoted.get("blockers") or []],
                    "score_claim": False,
                    "promotion_eligible": False,
                    "ready_for_exact_eval_dispatch": False,
                }
            artifact["substrate_artifact_metadata"] = artifact_metadata
            artifact_path.write_text(
                json.dumps(artifact, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
    return promoted


def _write_hi_nerv_runner_birth_inflated_survival_from_local_replay(
    *,
    local_cpu_replay_summary: Mapping[str, Any] | None,
    output_dir: str | Path,
    live_birth_payload: Mapping[str, Any] | None,
    scorer_teacher: Any | None,
    target_labels: Any | None,
    pair_indices: Any | None,
    pose_teacher: Any | None = None,
    target_rgb_0: Any | None = None,
    target_rgb_1: Any | None = None,
    selected_birth_parseback_survival: Mapping[str, Any] | None = None,
    live_birth_survival_bundle: Mapping[str, Any] | None = None,
    artifact_dict: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Write same-action inflated-torch CPU survival from retained local replay."""

    if not isinstance(live_birth_payload, Mapping):
        return None
    receipt = live_birth_payload.get("receipt")
    receipt = receipt if isinstance(receipt, Mapping) else {}
    action_id = str(live_birth_payload.get("action_id") or receipt.get("action_id") or "")
    if not action_id:
        return None

    out = Path(output_dir).expanduser().resolve(strict=False)
    out.mkdir(parents=True, exist_ok=True)
    row_path = out / "hi_nerv_birth_inflated_torch_cpu_survival.json"

    def _blocked(blocker: str, reason: str | None = None) -> dict[str, Any]:
        row = {
            "schema": "hi_nerv_target_region_birth_survival_blocked.v1",
            "surface": "inflated_torch_cpu",
            "action_id": action_id,
            "blocked": True,
            "blocker": blocker,
            "blockers": [blocker],
            "reason": reason or blocker,
            "producer": "hi_nerv_runner_local_cpu_replay_birth_survival",
            "artifact_path": row_path.as_posix(),
            "score_claim": False,
            "promotion_eligible": False,
            "ready_for_exact_eval_dispatch": False,
            **FALSE_AUTHORITY,
        }
        _write_json(row_path, row)
        return row

    if not isinstance(local_cpu_replay_summary, Mapping):
        row = _blocked("birth_survival_inflated_local_replay_summary_missing")
    elif scorer_teacher is None:
        row = _blocked("birth_survival_inflated_scorer_teacher_missing")
    elif target_labels is None:
        row = _blocked("birth_survival_inflated_target_labels_missing")
    elif pair_indices is None:
        row = _blocked("birth_survival_inflated_pair_indices_missing")
    else:
        try:
            from tac.substrates.hi_nerv.birth_survival import (
                measure_birth_inflated_torch_cpu_survival_from_local_replay,
            )

            row = dict(
                measure_birth_inflated_torch_cpu_survival_from_local_replay(
                    local_replay_summary=local_cpu_replay_summary,
                    scorer_teacher=scorer_teacher,
                    pose_teacher=pose_teacher,
                    target_rgb_0=target_rgb_0,
                    target_rgb_1=target_rgb_1,
                    target_labels=target_labels,
                    live_birth_payload=live_birth_payload,
                    pair_indices=pair_indices,
                )
            )
        except Exception as exc:
            row = _blocked(
                "birth_survival_inflated_remeasurement_failed",
                reason=f"{type(exc).__name__}:{exc}",
            )

    row["artifact_path"] = row_path.as_posix()
    row["producer"] = "hi_nerv_runner_local_cpu_replay_birth_survival"
    _write_json(row_path, row)

    parseback_survived = (
        isinstance(selected_birth_parseback_survival, Mapping)
        and selected_birth_parseback_survival.get("survived") is True
        and str(selected_birth_parseback_survival.get("action_id") or "") == action_id
    )
    fakequant_survived = (
        isinstance(live_birth_survival_bundle, Mapping)
        and live_birth_survival_bundle.get("fakequant_survived") is True
    )
    if row.get("survived") is True and parseback_survived and fakequant_survived:
        action_effect_ledger_path = out / "hi_nerv_birth_action_effects.jsonl"
        action_surface = str(
            receipt.get("surface")
            or live_birth_payload.get("surface")
            or live_birth_payload.get("authority")
            or "live_mlx"
        )
        action_authority = str(
            receipt.get("authority")
            or live_birth_payload.get("authority")
            or "batch_local_live_mlx"
        )
        action_normalization_scope = str(
            receipt.get("normalization_scope")
            or live_birth_payload.get("normalization_scope")
            or "batch_local"
        )
        merged_receipt = {
            **dict(receipt or live_birth_payload),
            **dict(row),
            "surface": action_surface,
            "authority": action_authority,
            "normalization_scope": action_normalization_scope,
            "inflated_survival_surface": "inflated_torch_cpu",
            "fakequant_survived": True,
            "parseback_survived": True,
            "inflate_survived": True,
            "artifact_path": row_path.as_posix(),
            "archive_sha256": (
                row.get("local_replay_archive_zip_sha256")
                or row.get("parseback_archive_sha256")
                or row.get("archive_sha256")
            ),
        }
        try:
            from tac.analysis.action_effect import (
                ActionEffect,
                append_action_effect,
                validate_action_effect_payload,
            )

            effect = ActionEffect.from_hinerv_birth_receipt(
                merged_receipt,
                consumer="nerv_long_run_launch_gate",
            )
            record = effect.as_dict()
            status = validate_action_effect_payload(record)
            if status.get("passed") is True:
                append_action_effect(effect, action_effect_ledger_path)
                row["combined_action_effect_ledger_path"] = action_effect_ledger_path.as_posix()
                row["combined_action_effect_rows_written"] = 1
            else:
                row["combined_action_effect_ledger_path"] = action_effect_ledger_path.as_posix()
                row["combined_action_effect_rows_written"] = 0
                row["combined_action_effect_blockers"] = [
                    str(value) for value in status.get("blockers") or []
                ]
        except Exception as exc:
            row["combined_action_effect_ledger_path"] = action_effect_ledger_path.as_posix()
            row["combined_action_effect_rows_written"] = 0
            row["combined_action_effect_blockers"] = [f"{type(exc).__name__}:{exc}"]
        _write_json(row_path, row)

    if artifact_dict is not None:
        artifact_dict["birth_inflated_torch_cpu_survival"] = dict(row)
        metadata = artifact_dict.get("substrate_artifact_metadata")
        if isinstance(metadata, dict):
            metadata["birth_inflated_torch_cpu_survival"] = dict(row)
            score_training = metadata.get("score_aware_training")
            if isinstance(score_training, dict):
                score_training["birth_inflated_torch_cpu_survival"] = _strip_substrate_metadata_authority_fields(
                    {
                        "schema": row.get("schema"),
                        "surface": row.get("surface"),
                        "action_id": row.get("action_id"),
                        "survived": row.get("survived"),
                        "artifact_path": row.get("artifact_path"),
                        "producer": row.get("producer"),
                        "blockers": [str(value) for value in row.get("blockers") or []],
                        "combined_action_effect_rows_written": row.get(
                            "combined_action_effect_rows_written"
                        ),
                        "score_claim": False,
                        "promotion_eligible": False,
                        "ready_for_exact_eval_dispatch": False,
                    }
                )
        artifact_path = out / "training_artifact.json"
        if artifact_path.is_file():
            try:
                artifact = _load_json(artifact_path)
            except Exception:
                artifact = None
            if isinstance(artifact, dict):
                artifact["birth_inflated_torch_cpu_survival"] = dict(row)
                artifact_metadata = dict(artifact.get("substrate_artifact_metadata") or {})
                artifact_metadata["birth_inflated_torch_cpu_survival"] = dict(row)
                score_training = artifact_metadata.get("score_aware_training")
                if isinstance(score_training, dict):
                    score_training["birth_inflated_torch_cpu_survival"] = _strip_substrate_metadata_authority_fields(
                        {
                            "schema": row.get("schema"),
                            "surface": row.get("surface"),
                            "action_id": row.get("action_id"),
                            "survived": row.get("survived"),
                            "artifact_path": row.get("artifact_path"),
                            "producer": row.get("producer"),
                            "blockers": [str(value) for value in row.get("blockers") or []],
                            "combined_action_effect_rows_written": row.get(
                                "combined_action_effect_rows_written"
                            ),
                            "score_claim": False,
                            "promotion_eligible": False,
                            "ready_for_exact_eval_dispatch": False,
                        }
                    )
                artifact["substrate_artifact_metadata"] = artifact_metadata
                artifact_path.write_text(
                    json.dumps(artifact, indent=2, sort_keys=True) + "\n",
                    encoding="utf-8",
                )
    return row


def _hi_nerv_receiver_replay_selection_score(
    report: Mapping[str, Any] | None,
) -> float | None:
    """Return archive-backed local scorer score when receiver replay produced it."""

    if not isinstance(report, Mapping):
        return None
    probe = report.get("mlx_scorer_response_probe")
    if not isinstance(probe, Mapping):
        return None
    return _first_finite_float(probe.get("canonical_score"))


def _write_hi_nerv_receiver_replay_parseback_servo_lift(
    *,
    receiver_replay_archive_selection: Mapping[str, Any] | None,
    receiver_surface_trace: Mapping[str, Any] | None,
    local_cpu_replay_summary: Mapping[str, Any] | None,
    output_dir: str | Path,
) -> dict[str, Any] | None:
    """Lift receiver-replayed archive selection into the shared servo IR."""

    lift = _hi_nerv_receiver_replay_parseback_servo_lift(
        receiver_replay_archive_selection=receiver_replay_archive_selection,
        receiver_surface_trace=receiver_surface_trace,
        local_cpu_replay_summary=local_cpu_replay_summary,
    )
    if lift is None:
        return None
    out = Path(output_dir).expanduser().resolve(strict=False)
    out.mkdir(parents=True, exist_ok=True)
    path = out / "receiver_replay_parseback_servo_lift.json"
    _write_json(path, lift)
    lift = dict(lift)
    lift["artifact_path"] = path.as_posix()
    lift["artifact_sha256"] = _sha256_file(path)
    _write_json(path, lift)
    return lift


def _hi_nerv_receiver_replay_parseback_servo_lift(
    *,
    receiver_replay_archive_selection: Mapping[str, Any] | None,
    receiver_surface_trace: Mapping[str, Any] | None,
    local_cpu_replay_summary: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(receiver_replay_archive_selection, Mapping):
        return None
    rows = [row for row in receiver_replay_archive_selection.get("rows") or [] if isinstance(row, Mapping)]
    if len(rows) < 2:
        return None
    training_row = next(
        (row for row in rows if row.get("selected_by_training_proxy") is True),
        None,
    )
    selected_path = str(receiver_replay_archive_selection.get("selected_archive_path") or "")
    selected_row = next(
        (row for row in rows if str(row.get("archive_path") or "") == selected_path),
        None,
    )
    blockers: list[str] = []
    if training_row is None:
        blockers.append("hi_nerv_receiver_replay_servo_lift_training_proxy_row_missing")
    if selected_row is None:
        blockers.append("hi_nerv_receiver_replay_servo_lift_selected_row_missing")
    if training_row is None or selected_row is None:
        return {
            "schema": "hi_nerv_receiver_replay_parseback_servo_lift.v1",
            "parseback_servo_lift": None,
            "blockers": blockers,
            **FALSE_AUTHORITY,
        }

    old_summary = training_row.get("receiver_replay_summary")
    new_summary = selected_row.get("receiver_replay_summary")
    if not isinstance(old_summary, Mapping):
        old_summary = {}
        blockers.append("hi_nerv_receiver_replay_servo_lift_old_summary_missing")
    if not isinstance(new_summary, Mapping):
        new_summary = {}
        blockers.append("hi_nerv_receiver_replay_servo_lift_new_summary_missing")

    old_d_seg = _first_finite_float(old_summary.get("mlx_scorer_response_avg_segnet_dist"))
    new_d_seg = _first_finite_float(new_summary.get("mlx_scorer_response_avg_segnet_dist"))
    old_d_pose = _first_finite_float(old_summary.get("mlx_scorer_response_avg_posenet_dist"))
    new_d_pose = _first_finite_float(new_summary.get("mlx_scorer_response_avg_posenet_dist"))
    old_bytes = _positive_int_or_none(training_row.get("archive_bytes"))
    new_bytes = _positive_int_or_none(selected_row.get("archive_bytes"))
    old_archive_sha = _sha256_text(training_row.get("archive_sha256"))
    new_archive_sha = _sha256_text(selected_row.get("archive_sha256"))
    old_flips = _hi_nerv_parseback_argmax_flipped_pixels(old_summary)
    new_flips = _hi_nerv_parseback_argmax_flipped_pixels(new_summary)
    argmax_delta = abs(float(new_flips) - float(old_flips)) if old_flips is not None and new_flips is not None else None
    pose_delta = (
        abs(float(new_d_pose) - float(old_d_pose)) if old_d_pose is not None and new_d_pose is not None else None
    )
    uint8_changed_pixels = _first_finite_float(
        new_summary.get("receiver_surface_uint8_changed_pixels"),
        receiver_surface_trace.get("receiver_surface_uint8_changed_pixels")
        if isinstance(receiver_surface_trace, Mapping)
        else None,
    )
    fakequant_survival = _bool_or_none(new_summary.get("fakequant_survival"))
    parseback_survival = bool(
        new_d_seg is not None
        and new_d_pose is not None
        and new_archive_sha is not None
        and new_summary.get("mlx_scorer_response_probe_required") is True
    )
    inflate_survival = bool(
        isinstance(local_cpu_replay_summary, Mapping) and local_cpu_replay_summary.get("evaluation_passed") is True
    )

    from tac.substrates._shared.mlx_score_aware.servo_lift import servo_lift

    parseback_servo_lift = servo_lift(
        {
            "action_id": "hi_nerv_receiver_replay_archive_selection",
            "family": "hinerv",
            "stage": "receiver_replay_archive_selection",
            "authority": "parseback_mlx",
            "producer": "hi_nerv_receiver_replay_archive_selection",
            "consumer": "hi_nerv_runner_archive_resolution",
            "affected_pairs": [],
            "affected_regions": ["receiver_replay_archive_selection"],
            "payload_sections": ["archive_zip"],
            "archive_sha256": new_archive_sha,
            "source_archive_sha256": old_archive_sha,
            "old_d_seg": old_d_seg,
            "new_d_seg": new_d_seg,
            "old_d_pose": old_d_pose,
            "new_d_pose": new_d_pose,
            "old_bytes": old_bytes,
            "new_bytes": new_bytes,
            "fakequant_survived": fakequant_survival,
            "parseback_survived": parseback_survival,
            "inflate_survived": inflate_survival,
            "receiver_surface": {
                "receiver_surface": "receiver_replay_archive_selection",
                "uint8_changed_pixels": uint8_changed_pixels,
                "parseback_argmax_flipped_pixels": argmax_delta,
                "pose_output_delta_l2": pose_delta,
                "fakequant_survival": fakequant_survival,
                "parseback_survival": parseback_survival,
                "inflate_survival": inflate_survival,
            },
        },
        family="hinerv",
        stage="receiver_replay_archive_selection",
        require_inflate_survival=True,
    )
    blockers.extend(str(blocker) for blocker in parseback_servo_lift.get("blockers") or [])
    return {
        "schema": "hi_nerv_receiver_replay_parseback_servo_lift.v1",
        "selection_manifest_path": receiver_replay_archive_selection.get("manifest_path"),
        "training_proxy_archive_path": training_row.get("archive_path"),
        "selected_archive_path": selected_row.get("archive_path"),
        "training_proxy_archive_sha256": old_archive_sha,
        "selected_archive_sha256": new_archive_sha,
        "parseback_servo_lift": parseback_servo_lift,
        "blockers": _dedupe(blockers),
        "score_claim": False,
        **FALSE_AUTHORITY,
    }


def _hi_nerv_receiver_surface_trace_from_replay_evidence(
    *,
    receiver_replay_archive_selection: Mapping[str, Any] | None,
    post_export_receiver_cache_quality: Mapping[str, Any] | None,
    local_cpu_replay_summary: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """Build canonical receiver-surface trace fields from real replay evidence."""

    report = None
    selection_source = "post_export_receiver_cache_quality"
    if isinstance(receiver_replay_archive_selection, Mapping):
        selected = receiver_replay_archive_selection.get("selected_receiver_replay_report")
        if isinstance(selected, Mapping):
            report = selected
            selection_source = "receiver_replay_archive_selection"
    if report is None and isinstance(post_export_receiver_cache_quality, Mapping):
        report = post_export_receiver_cache_quality
    if report is None and not isinstance(local_cpu_replay_summary, Mapping):
        return None

    trace: dict[str, Any] = {
        "schema": "nerv_receiver_surface_trace.v1",
        "trace_source": "hi_nerv_runner_replay_evidence",
        "archive_parseback_source": selection_source if report is not None else None,
        "local_cpu_replay_source": (
            "local_submission_replay.v1" if isinstance(local_cpu_replay_summary, Mapping) else None
        ),
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }
    if isinstance(report, Mapping):
        summary = _hi_nerv_receiver_cache_quality_summary(report)
        if isinstance(summary, Mapping):
            trace["receiver_surface_parseback_report_path"] = summary.get("report_path")
            trace["receiver_surface_parseback_archive_sha256"] = summary.get("archive_sha256")
            parseback_flips = _hi_nerv_parseback_argmax_flipped_pixels(summary)
            if parseback_flips is not None:
                trace["receiver_surface_parseback_argmax_flipped_pixels"] = parseback_flips
            for source_key, trace_key in (
                (
                    "mlx_scorer_response_avg_segnet_dist",
                    "receiver_surface_parseback_segnet_distortion",
                ),
                (
                    "mlx_scorer_response_avg_posenet_dist",
                    "receiver_surface_parseback_posenet_distortion",
                ),
                (
                    "mlx_scorer_response_canonical_score",
                    "receiver_surface_parseback_canonical_score",
                ),
            ):
                value = _first_finite_float(summary.get(source_key))
                if value is not None:
                    trace[trace_key] = value
    if isinstance(local_cpu_replay_summary, Mapping):
        trace["receiver_surface_inflate_evaluate_passed"] = bool(local_cpu_replay_summary.get("evaluation_passed"))
        trace["receiver_surface_inflate_axis_tag"] = local_cpu_replay_summary.get("axis_tag")
        for source_key, trace_key in (
            ("seg_distortion", "receiver_surface_inflate_segnet_distortion"),
            ("pose_distortion", "receiver_surface_inflate_posenet_distortion"),
            ("local_score_estimate", "receiver_surface_inflate_local_score_estimate"),
            (
                "receiver_surface_inflated_argmax_flipped_pixels",
                "receiver_surface_inflated_argmax_flipped_pixels",
            ),
        ):
            value = _first_finite_float(local_cpu_replay_summary.get(source_key))
            if value is not None:
                trace[trace_key] = value
    return trace


def _hi_nerv_parseback_argmax_flipped_pixels(
    summary: Mapping[str, Any],
) -> float | None:
    rate = _first_finite_float(summary.get("segnet_argmax_disagreement_rate"))
    sample_pairs = _first_finite_float(summary.get("segnet_argmax_sample_pairs"))
    if rate is None or sample_pairs is None:
        return None
    if rate < 0.0 or sample_pairs <= 0.0:
        return None
    return float(rate) * float(sample_pairs) * float(HI_NERV_SEGNET_SCORER_FRAME_PIXELS)


def _attach_hi_nerv_runner_receiver_surface_trace(
    *,
    artifact_dict: dict[str, Any],
    output_dir: str | Path,
    receiver_surface_trace: Mapping[str, Any] | None,
) -> None:
    if not isinstance(receiver_surface_trace, Mapping):
        return
    trace = _merge_hi_nerv_receiver_surface_trace(
        artifact_dict.get("receiver_surface_trace"),
        receiver_surface_trace,
    )
    artifact_dict["receiver_surface_trace"] = trace
    metadata = artifact_dict.get("substrate_artifact_metadata")
    if isinstance(metadata, dict):
        trace = _merge_hi_nerv_receiver_surface_trace(
            metadata.get("receiver_surface_trace"),
            trace,
        )
        metadata["receiver_surface_trace"] = trace
        artifact_dict["receiver_surface_trace"] = trace
        score_training = metadata.get("score_aware_training")
        if isinstance(score_training, dict):
            trace = _merge_hi_nerv_receiver_surface_trace(
                score_training.get("receiver_surface_trace"),
                trace,
            )
            score_training["receiver_surface_trace"] = trace
            metadata["receiver_surface_trace"] = trace
            artifact_dict["receiver_surface_trace"] = trace

    artifact_path = Path(output_dir).expanduser().resolve(strict=False) / ("training_artifact.json")
    if not artifact_path.is_file():
        return
    try:
        artifact = json.loads(artifact_path.read_text(encoding="utf-8"))
    except Exception:
        return
    trace = _merge_hi_nerv_receiver_surface_trace(
        artifact.get("receiver_surface_trace"),
        trace,
    )
    artifact["receiver_surface_trace"] = trace
    artifact_metadata = dict(artifact.get("substrate_artifact_metadata") or {})
    trace = _merge_hi_nerv_receiver_surface_trace(
        artifact_metadata.get("receiver_surface_trace"),
        trace,
    )
    artifact_metadata["receiver_surface_trace"] = trace
    artifact["receiver_surface_trace"] = trace
    score_training = artifact_metadata.get("score_aware_training")
    if isinstance(score_training, dict):
        trace = _merge_hi_nerv_receiver_surface_trace(
            score_training.get("receiver_surface_trace"),
            trace,
        )
        score_training["receiver_surface_trace"] = trace
        artifact_metadata["receiver_surface_trace"] = trace
        artifact["receiver_surface_trace"] = trace
    artifact["substrate_artifact_metadata"] = artifact_metadata
    artifact_path.write_text(
        json.dumps(artifact, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


def _merge_hi_nerv_receiver_surface_trace(
    existing: Any,
    incoming: Mapping[str, Any],
) -> dict[str, Any]:
    merged = dict(existing) if isinstance(existing, Mapping) else {}
    merged.update(dict(incoming))
    return merged


def _write_hi_nerv_runner_receiver_replay_archive_selection(
    *,
    requested: bool,
    archive_resolution: Mapping[str, Any],
    source_video_path: str | Path,
    output_dir: str | Path,
    reference_cache_dir: str | Path | None,
    max_pairs: int,
    batch_pairs: int,
    min_segnet_std: float,
    min_segnet_dynamic_range: float,
    max_segnet_mae_vs_reference_for_fit_gate: float,
    segnet_argmax_probe: bool,
    segnet_argmax_batch_frames: int,
    max_segnet_argmax_disagreement_for_fit_gate: float,
    min_segnet_argmax_occupied_class_fraction_for_fit_gate: float,
    repo_root: str | Path,
    min_posenet_yuv6_std: float = 1.0,
    min_posenet_yuv6_dynamic_range: float = 16.0,
    max_posenet_yuv6_mae_vs_reference_for_fit_gate: float = 64.0,
    min_posenet_yuv6_temporal_signal_std_for_fit_gate: float = 0.25,
    min_posenet_yuv6_temporal_signal_mean_abs_for_fit_gate: float = 0.25,
    pair_indices: Sequence[int] = (),
    mlx_scorer_response_probe: bool = True,
    mlx_scorer_response_upstream_dir: str | Path | None = None,
    mlx_scorer_response_device_type: str = "cpu",
    mlx_scorer_response_batch_pairs: int = 1,
    max_mlx_scorer_response_posenet_dist_for_fit_gate: float = (
        DEFAULT_MAX_MLX_SCORER_RESPONSE_POSENET_DIST_FOR_FIT_GATE
    ),
    max_mlx_scorer_response_segnet_dist_for_fit_gate: float = (
        DEFAULT_MAX_MLX_SCORER_RESPONSE_SEGNET_DIST_FOR_FIT_GATE
    ),
) -> dict[str, Any] | None:
    """Select HiNeRV live/EMA archive by receiver-replayed scorer response.

    Training-side live/EMA selection can prefer a smoother proxy state whose
    packed receiver output is worse.  This selector prices each exported
    candidate through the HIV1 archive receiver and local MLX scorer probe, then
    lets downstream gates consume the best replayed archive.  It is still
    false-authority local evidence, not a contest score claim.
    """

    if not requested or not bool(mlx_scorer_response_probe):
        return None
    raw_candidates = archive_resolution.get("candidates")
    if not isinstance(raw_candidates, Sequence) or isinstance(raw_candidates, (str, bytes)):
        return None
    candidates: list[Mapping[str, Any]] = []
    seen_paths: set[str] = set()
    for raw in raw_candidates:
        if not isinstance(raw, Mapping):
            continue
        raw_path = raw.get("archive_path")
        if not isinstance(raw_path, str) or not raw_path:
            continue
        archive_path = Path(raw_path).expanduser().resolve(strict=False)
        if not archive_path.is_file():
            continue
        key = archive_path.as_posix()
        if key in seen_paths:
            continue
        seen_paths.add(key)
        candidates.append(raw)
    if len(candidates) < 2:
        return None

    out = Path(output_dir).expanduser().resolve(strict=False)
    selection_dir = out / "receiver_replay_archive_selection"
    selection_dir.mkdir(parents=True, exist_ok=True)
    rows: list[dict[str, Any]] = []
    selected_report: dict[str, Any] | None = None

    for idx, candidate in enumerate(candidates):
        archive_path = Path(str(candidate["archive_path"])).expanduser().resolve(strict=False)
        kind = str(candidate.get("candidate_kind") or f"candidate_{idx}")
        safe_kind = re.sub(r"[^A-Za-z0-9_.-]+", "_", kind).strip("._") or (f"candidate_{idx}")
        candidate_output_dir = selection_dir / f"{idx:02d}_{safe_kind}"
        report = _write_hi_nerv_runner_post_export_receiver_cache_quality(
            requested=True,
            archive_zip_path=archive_path,
            source_video_path=source_video_path,
            output_dir=candidate_output_dir,
            reference_cache_dir=reference_cache_dir,
            max_pairs=max_pairs,
            batch_pairs=batch_pairs,
            pair_indices=pair_indices,
            min_segnet_std=min_segnet_std,
            min_segnet_dynamic_range=min_segnet_dynamic_range,
            max_segnet_mae_vs_reference_for_fit_gate=(max_segnet_mae_vs_reference_for_fit_gate),
            min_posenet_yuv6_std=min_posenet_yuv6_std,
            min_posenet_yuv6_dynamic_range=min_posenet_yuv6_dynamic_range,
            max_posenet_yuv6_mae_vs_reference_for_fit_gate=(max_posenet_yuv6_mae_vs_reference_for_fit_gate),
            min_posenet_yuv6_temporal_signal_std_for_fit_gate=(min_posenet_yuv6_temporal_signal_std_for_fit_gate),
            min_posenet_yuv6_temporal_signal_mean_abs_for_fit_gate=(
                min_posenet_yuv6_temporal_signal_mean_abs_for_fit_gate
            ),
            segnet_argmax_probe=segnet_argmax_probe,
            segnet_argmax_batch_frames=segnet_argmax_batch_frames,
            max_segnet_argmax_disagreement_for_fit_gate=(max_segnet_argmax_disagreement_for_fit_gate),
            min_segnet_argmax_occupied_class_fraction_for_fit_gate=(
                min_segnet_argmax_occupied_class_fraction_for_fit_gate
            ),
            mlx_scorer_response_probe=True,
            mlx_scorer_response_upstream_dir=mlx_scorer_response_upstream_dir,
            mlx_scorer_response_device_type=mlx_scorer_response_device_type,
            mlx_scorer_response_batch_pairs=mlx_scorer_response_batch_pairs,
            max_mlx_scorer_response_posenet_dist_for_fit_gate=(max_mlx_scorer_response_posenet_dist_for_fit_gate),
            max_mlx_scorer_response_segnet_dist_for_fit_gate=(max_mlx_scorer_response_segnet_dist_for_fit_gate),
            repo_root=repo_root,
        )
        summary = _hi_nerv_receiver_cache_quality_summary(report)
        local_score = _hi_nerv_receiver_replay_selection_score(report)
        rows.append(
            {
                "schema": ("hi_nerv_receiver_replay_archive_selection_candidate.v1"),
                "candidate_index": int(idx),
                "candidate_kind": candidate.get("candidate_kind"),
                "archive_path": archive_path.as_posix(),
                "archive_sha256": candidate.get("archive_sha256"),
                "archive_bytes": candidate.get("archive_bytes"),
                "source": candidate.get("source"),
                "selected_by_training_proxy": bool(candidate.get("selected_for_training_artifact")),
                "diagnostic_only_before_receiver_replay": bool(candidate.get("diagnostic_only")),
                "byte_cap_rejected": bool(candidate.get("byte_cap_rejected")),
                "receiver_replay_report_path": (report.get("report_path") if isinstance(report, Mapping) else None),
                "receiver_replay_summary": summary,
                "receiver_replay_local_canonical_score": local_score,
                **FALSE_AUTHORITY,
            }
        )

    finite_rows = [
        row for row in rows if _first_finite_float(row.get("receiver_replay_local_canonical_score")) is not None
    ]
    selected = None
    if finite_rows:
        selected = min(
            finite_rows,
            key=lambda row: (
                int(bool(row.get("byte_cap_rejected"))),
                float(row["receiver_replay_local_canonical_score"]),
                int(row.get("archive_bytes") or 0),
                0 if row.get("candidate_kind") == "ema" else 1,
            ),
        )
        selected_report_path = selected.get("receiver_replay_report_path")
        if isinstance(selected_report_path, str) and selected_report_path:
            try:
                selected_report = _load_json(Path(selected_report_path))
            except Exception:
                selected_report = None

    manifest = {
        "schema": "hi_nerv_receiver_replay_archive_selection.v1",
        "selection_metric": "archive_backed_mlx_scorer_response_canonical_score",
        "authority": "local_receiver_replay_false_authority",
        "candidate_count": len(rows),
        "selected_candidate_kind": (selected.get("candidate_kind") if isinstance(selected, Mapping) else None),
        "selected_archive_path": (selected.get("archive_path") if isinstance(selected, Mapping) else None),
        "selected_archive_sha256": (selected.get("archive_sha256") if isinstance(selected, Mapping) else None),
        "selected_archive_bytes": (selected.get("archive_bytes") if isinstance(selected, Mapping) else None),
        "selected_receiver_replay_local_canonical_score": (
            selected.get("receiver_replay_local_canonical_score") if isinstance(selected, Mapping) else None
        ),
        "selected_receiver_replay_report_path": (
            selected.get("receiver_replay_report_path") if isinstance(selected, Mapping) else None
        ),
        "rows": rows,
        "blockers": _dedupe(
            [
                "hi_nerv_receiver_replay_archive_selection_is_false_authority",
                *(["hi_nerv_receiver_replay_archive_selection_no_finite_score"] if selected is None else []),
            ]
        ),
        **FALSE_AUTHORITY,
    }
    if selected_report is not None:
        manifest["selected_receiver_replay_report"] = selected_report
    manifest_path = selection_dir / "receiver_replay_archive_selection.json"
    manifest["manifest_path"] = manifest_path.as_posix()
    _write_json(manifest_path, manifest)
    return manifest


def _argmax_histogram_occupied_fraction(histogram: Any) -> float | None:
    return _argmax_histogram_occupancy(histogram).get("occupied_class_fraction")


def _argmax_histogram_occupancy(histogram: Any) -> dict[str, float | None]:
    if not isinstance(histogram, list) or not histogram:
        return {
            "occupied_class_fraction": None,
            "any_occupied_class_fraction": None,
            "min_class_pixel_count": None,
        }
    try:
        values = [int(value) for value in histogram]
    except (TypeError, ValueError):
        return {
            "occupied_class_fraction": None,
            "any_occupied_class_fraction": None,
            "min_class_pixel_count": None,
        }
    total = sum(max(0, value) for value in values)
    if total <= 0:
        return {
            "occupied_class_fraction": 0.0,
            "any_occupied_class_fraction": 0.0,
            "min_class_pixel_count": 2.0,
        }
    min_count = max(2, math.ceil(total * 1.0e-3))
    return {
        "occupied_class_fraction": float(sum(1 for value in values if value >= min_count) / max(len(values), 1)),
        "any_occupied_class_fraction": float(sum(1 for value in values if value > 0) / max(len(values), 1)),
        "min_class_pixel_count": float(min_count),
    }


def _argmax_histogram_target_class_coverage(
    candidate_histogram: Any,
    reference_histogram: Any,
) -> dict[str, Any]:
    if not isinstance(candidate_histogram, list) or not isinstance(
        reference_histogram,
        list,
    ):
        return {
            "candidate_target_class_coverage_fraction": None,
            "candidate_target_any_class_coverage_fraction": None,
            "candidate_target_class_min_ratio": None,
            "target_material_class_count": None,
            "target_any_class_count": None,
            "candidate_target_material_class_covered_count": None,
            "candidate_target_any_class_covered_count": None,
            "candidate_target_class_covered": None,
            "candidate_target_any_class_covered": None,
            "candidate_target_class_ratio": None,
            "min_class_pixel_count_for_target_coverage": None,
        }
    try:
        class_count = max(len(candidate_histogram), len(reference_histogram), 1)
        candidate = [
            max(0, int(candidate_histogram[i])) if i < len(candidate_histogram) else 0 for i in range(class_count)
        ]
        reference = [
            max(0, int(reference_histogram[i])) if i < len(reference_histogram) else 0 for i in range(class_count)
        ]
    except (TypeError, ValueError):
        return {
            "candidate_target_class_coverage_fraction": None,
            "candidate_target_any_class_coverage_fraction": None,
            "candidate_target_class_min_ratio": None,
            "target_material_class_count": None,
            "target_any_class_count": None,
            "candidate_target_material_class_covered_count": None,
            "candidate_target_any_class_covered_count": None,
            "candidate_target_class_covered": None,
            "candidate_target_any_class_covered": None,
            "candidate_target_class_ratio": None,
            "min_class_pixel_count_for_target_coverage": None,
        }
    reference_total = sum(reference)
    min_count = max(2, math.ceil(reference_total * 1.0e-3))
    target_any_count = sum(1 for value in reference if value > 0)
    target_material_count = sum(1 for value in reference if value >= min_count)
    any_covered = [bool(reference[i] > 0 and candidate[i] > 0) for i in range(class_count)]
    material_covered = [
        bool(reference[i] >= min_count and candidate[i] >= min(min_count, reference[i])) for i in range(class_count)
    ]
    ratios = [
        1.0 if reference[i] <= 0 else min(1.0, float(candidate[i] / max(reference[i], 1))) for i in range(class_count)
    ]
    material_covered_count = sum(1 for value in material_covered if value)
    any_covered_count = sum(1 for value in any_covered if value)
    target_present_ratios = [ratios[i] for i in range(class_count) if reference[i] > 0]
    return {
        "candidate_target_class_coverage_fraction": (
            float(material_covered_count / target_material_count) if target_material_count > 0 else 1.0
        ),
        "candidate_target_any_class_coverage_fraction": (
            float(any_covered_count / target_any_count) if target_any_count > 0 else 1.0
        ),
        "candidate_target_class_min_ratio": (float(min(target_present_ratios)) if target_present_ratios else 1.0),
        "target_material_class_count": int(target_material_count),
        "target_any_class_count": int(target_any_count),
        "candidate_target_material_class_covered_count": int(material_covered_count),
        "candidate_target_any_class_covered_count": int(any_covered_count),
        "candidate_target_class_covered": material_covered,
        "candidate_target_any_class_covered": any_covered,
        "candidate_target_class_ratio": ratios,
        "min_class_pixel_count_for_target_coverage": int(min_count),
    }


def _first_finite_float(*values: Any) -> float | None:
    for value in values:
        if _finite_json_number(value):
            return float(value)
    return None


def _positive_int_or_none(value: Any) -> int | None:
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        return None
    return parsed if parsed > 0 else None


def _sha256_text(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    text = value.strip()
    if len(text) != 64:
        return None
    if not all(char in "0123456789abcdefABCDEF" for char in text):
        return None
    return text


def _bool_or_none(value: Any) -> bool | None:
    return value if isinstance(value, bool) else None


def _hi_nerv_train_receiver_class_escape_contract(
    *,
    training_telemetry_contract: Mapping[str, Any] | None,
    receiver_cache_quality_summary: Mapping[str, Any] | None,
    min_surviving_fraction: float = (HI_NERV_SEGNET_ARGMAX_MIN_OCCUPIED_CLASS_FRACTION_FOR_FIT_GATE),
    min_escape_delta: float = 0.199999,
) -> dict[str, Any]:
    """Name the crux when class escape is learned but not receiver-preserved."""

    train_fraction: float | None = None
    receiver_fraction: float | None = None
    target_fraction: float | None = None
    train_target_coverage_fraction: float | None = None
    receiver_target_coverage_fraction: float | None = None
    train_target_min_ratio: float | None = None
    receiver_target_min_ratio: float | None = None
    receiver_target_material_class_count: float | None = None
    train_row_count: int | None = None
    train_source_pair_indices: set[int] = set()
    receiver_sample_pairs: int | None = None
    receiver_pair_indices: set[int] = set()
    if isinstance(training_telemetry_contract, Mapping):
        value = training_telemetry_contract.get("row_count")
        if _finite_json_number(value):
            train_row_count = int(value)
        raw_source_pairs = training_telemetry_contract.get("train_source_pair_indices_observed")
        if isinstance(raw_source_pairs, Sequence) and not isinstance(
            raw_source_pairs,
            (str, bytes, bytearray),
        ):
            for raw in raw_source_pairs:
                if _finite_json_number(raw):
                    train_source_pair_indices.add(int(raw))
        value = training_telemetry_contract.get("train_source_pair_count_observed")
        if _finite_json_number(value) and not train_source_pair_indices:
            train_source_pair_indices.update(range(int(value)))
        value = training_telemetry_contract.get("segnet_direct_live_max_candidate_occupied_class_fraction")
        if _finite_json_number(value):
            train_fraction = float(value)
        value = training_telemetry_contract.get("segnet_direct_live_max_candidate_target_class_coverage_fraction")
        if _finite_json_number(value):
            train_target_coverage_fraction = float(value)
        value = _first_finite_float(
            training_telemetry_contract.get("segnet_direct_live_max_candidate_target_class_min_ratio"),
            training_telemetry_contract.get("segnet_direct_live_min_candidate_target_class_min_ratio"),
        )
        if _finite_json_number(value):
            train_target_min_ratio = float(value)
    if isinstance(receiver_cache_quality_summary, Mapping):
        value = receiver_cache_quality_summary.get("segnet_candidate_occupied_class_fraction")
        if _finite_json_number(value):
            receiver_fraction = float(value)
        value = receiver_cache_quality_summary.get("segnet_reference_occupied_class_fraction")
        if _finite_json_number(value):
            target_fraction = float(value)
        value = receiver_cache_quality_summary.get("segnet_candidate_target_class_coverage_fraction")
        if _finite_json_number(value):
            receiver_target_coverage_fraction = float(value)
        value = receiver_cache_quality_summary.get("segnet_candidate_target_class_min_ratio")
        if _finite_json_number(value):
            receiver_target_min_ratio = float(value)
        value = receiver_cache_quality_summary.get("segnet_target_material_class_count")
        if _finite_json_number(value):
            receiver_target_material_class_count = float(value)
        value = receiver_cache_quality_summary.get("segnet_argmax_sample_pairs")
        if _finite_json_number(value):
            receiver_sample_pairs = int(value)
        raw_receiver_pairs = receiver_cache_quality_summary.get("runner_receiver_cache_quality_pair_indices")
        if isinstance(raw_receiver_pairs, Sequence) and not isinstance(
            raw_receiver_pairs,
            (str, bytes, bytearray),
        ):
            for raw in raw_receiver_pairs:
                if _finite_json_number(raw):
                    receiver_pair_indices.add(int(raw))

    blockers: list[str] = []
    if train_fraction is None:
        blockers.append("hi_nerv_train_receiver_class_escape_train_fraction_missing")
    if receiver_fraction is None:
        blockers.append("hi_nerv_train_receiver_class_escape_receiver_fraction_missing")
    if train_source_pair_indices and receiver_pair_indices:
        scope_aligned = train_source_pair_indices.issubset(receiver_pair_indices)
    elif train_source_pair_indices and receiver_sample_pairs is not None:
        scope_aligned = receiver_sample_pairs >= len(train_source_pair_indices)
    elif receiver_sample_pairs is not None and train_row_count is not None:
        scope_aligned = receiver_sample_pairs >= max(1, train_row_count)
    else:
        scope_aligned = True
    if not scope_aligned:
        blockers.append("hi_nerv_train_receiver_class_escape_pair_scope_mismatch")
    if (
        scope_aligned
        and train_fraction is not None
        and receiver_fraction is not None
        and train_fraction >= min_surviving_fraction
        and receiver_fraction < min_surviving_fraction
        and (train_fraction - receiver_fraction) >= min_escape_delta
    ):
        blockers.append("hi_nerv_train_time_class_escape_not_receiver_export_preserved")
    if (
        target_fraction is not None
        and receiver_fraction is not None
        and target_fraction >= min_surviving_fraction
        and receiver_fraction < min_surviving_fraction
    ):
        blockers.append("hi_nerv_receiver_export_segnet_argmax_class_collapse")
    if (
        scope_aligned
        and train_target_coverage_fraction is not None
        and receiver_target_coverage_fraction is not None
        and train_target_coverage_fraction >= min_surviving_fraction
        and receiver_target_coverage_fraction < min_surviving_fraction
        and (train_target_coverage_fraction - receiver_target_coverage_fraction) >= min_escape_delta
    ):
        blockers.append("hi_nerv_train_time_target_class_coverage_not_receiver_export_preserved")
    if (
        receiver_target_material_class_count is not None
        and receiver_target_material_class_count > 0
        and receiver_target_coverage_fraction is not None
        and receiver_target_coverage_fraction < min_surviving_fraction
    ):
        blockers.append("hi_nerv_receiver_export_segnet_target_class_coverage_collapse")
    min_target_mass_ratio = 0.2
    if (
        scope_aligned
        and train_target_min_ratio is not None
        and receiver_target_min_ratio is not None
        and train_target_min_ratio >= min_target_mass_ratio
        and receiver_target_min_ratio < min_target_mass_ratio
        and (train_target_min_ratio - receiver_target_min_ratio) >= min_escape_delta
    ):
        blockers.append("hi_nerv_train_time_target_class_mass_not_receiver_export_preserved")
    if (
        receiver_target_material_class_count is not None
        and receiver_target_material_class_count > 0
        and receiver_target_min_ratio is not None
        and receiver_target_min_ratio < min_target_mass_ratio
    ):
        blockers.append("hi_nerv_receiver_export_segnet_target_class_mass_collapse")
    return {
        "schema": "hi_nerv_train_receiver_class_escape_contract.v1",
        "train_direct_live_max_candidate_occupied_class_fraction": train_fraction,
        "train_direct_live_max_candidate_target_class_coverage_fraction": (train_target_coverage_fraction),
        "train_direct_live_best_candidate_target_class_min_ratio": (train_target_min_ratio),
        "train_telemetry_row_count": train_row_count,
        "train_source_pair_indices_observed": sorted(train_source_pair_indices),
        "train_source_pair_count_observed": (len(train_source_pair_indices) if train_source_pair_indices else None),
        "receiver_candidate_occupied_class_fraction": receiver_fraction,
        "receiver_reference_occupied_class_fraction": target_fraction,
        "receiver_candidate_target_class_coverage_fraction": (receiver_target_coverage_fraction),
        "receiver_candidate_target_class_min_ratio": receiver_target_min_ratio,
        "receiver_target_material_class_count": receiver_target_material_class_count,
        "receiver_segnet_argmax_sample_pairs": receiver_sample_pairs,
        "receiver_pair_indices": sorted(receiver_pair_indices),
        "train_receiver_scope_aligned": scope_aligned,
        "min_surviving_fraction": float(min_surviving_fraction),
        "min_target_mass_ratio": float(min_target_mass_ratio),
        "min_escape_delta": float(min_escape_delta),
        "passed": not blockers,
        "blockers": blockers,
        "authority": "macos_mlx_research_signal_false_authority",
        "score_claim": False,
        "promotion_eligible": False,
        "ready_for_exact_eval_dispatch": False,
    }


def _hi_nerv_effective_receiver_cache_quality_max_pairs(
    *,
    requested_max_pairs: int,
    num_pairs: int,
    train_batch_pairs: int,
) -> dict[str, int]:
    """Keep receiver quality broad enough to catch long-run scorer collapse."""

    requested = max(1, int(requested_max_pairs))
    candidate_pairs = max(1, int(num_pairs))
    train_batch = max(1, int(train_batch_pairs))
    quality_floor = min(candidate_pairs, 16)
    train_scope_min = max(1, min(candidate_pairs, max(train_batch, quality_floor)))
    return {
        "requested_max_pairs": requested,
        "quality_floor_min_pairs": quality_floor,
        "train_scope_min_pairs": train_scope_min,
        "effective_max_pairs": max(requested, train_scope_min),
    }


def _hi_nerv_receiver_cache_quality_routable_hard_pair_coverage(
    report: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(report, Mapping):
        return None
    crux = report.get("distortion_crux_probe")
    if not isinstance(crux, Mapping):
        return None
    coverage = crux.get("hard_pair_coverage")
    if not isinstance(coverage, Mapping):
        return None
    if not (
        coverage.get("representative_distortion_evidence") is True
        or coverage.get("score_axis_hard_pair_coverage") is True
        or coverage.get("coverage_valid_for_distortion") is True
    ):
        return None
    return dict(coverage)


def _compact_score_aware_training_telemetry_contract(
    telemetry_path: str | Path | None,
    *,
    family: str,
    segnet_distillation_weight: float,
    pose_distillation_weight: float,
    segnet_student_live_calibration_weight: float,
    segnet_direct_live_distillation_weight: float = 0.0,
    segnet_direct_live_class_histogram_weight: float = 0.0,
    segnet_direct_live_class_balanced_hinge_weight: float = 0.0,
    segnet_direct_live_class_balanced_ce_weight: float = 0.0,
    segnet_direct_live_class_balanced_squared_hinge_weight: float = 0.0,
    segnet_direct_live_class_region_recon_weight: float = 0.0,
    segnet_direct_live_rare_class_logit_weight: float = 0.0,
    segnet_direct_live_target_mass_floor_weight: float = 0.0,
    segnet_direct_live_target_min_ratio_floor_weight: float = 0.0,
    pose_direct_live_distillation_weight: float = 0.0,
    scorer_support_ladder_enabled: bool = False,
    pr95_faithful_curriculum_enabled: bool,
    coder_aware_qat_bound: bool,
    train_time_section_byte_control_bound: bool,
    scorer_input_distribution_guard_weight: float,
    scorer_input_contrast_floor_weight: float = 0.0,
    scorer_input_shape_tether_weight: float = 0.0,
    posenet_yuv6_geometry_tether_weight: float = 0.0,
    posenet_temporal_signal_floor_weight: float = 0.0,
    gradient_multiplier_controls_requested: bool = False,
    min_segnet_direct_live_occupied_class_fraction_for_fit_gate: float = (
        HI_NERV_SEGNET_ARGMAX_MIN_OCCUPIED_CLASS_FRACTION_FOR_FIT_GATE
    ),
    min_segnet_direct_live_target_class_coverage_fraction_for_fit_gate: float = (
        HI_NERV_SEGNET_TARGET_CLASS_COVERAGE_FRACTION_FOR_FIT_GATE
    ),
    min_segnet_direct_live_target_class_min_ratio_for_fit_gate: float = (
        HI_NERV_SEGNET_TARGET_CLASS_MIN_RATIO_FOR_FIT_GATE
    ),
) -> dict[str, Any]:
    """Validate that a compact long run actually actuated score controls."""

    family_key = str(family).strip().lower()
    path = Path(telemetry_path).expanduser() if telemetry_path else Path("")
    expected_seg = float(segnet_distillation_weight) > 0.0
    expected_pose = float(pose_distillation_weight) > 0.0
    expected_pose_direct_live = float(pose_direct_live_distillation_weight) > 0.0
    support_ladder_expected = bool(scorer_support_ladder_enabled)
    expected_live_calibration = bool(expected_seg and float(segnet_student_live_calibration_weight) > 0.0)
    direct_live_subcontrol_weights = {
        "class_histogram": float(segnet_direct_live_class_histogram_weight),
        "class_balanced_hinge": float(segnet_direct_live_class_balanced_hinge_weight),
        "class_balanced_ce": float(segnet_direct_live_class_balanced_ce_weight),
        "class_balanced_squared_hinge": float(segnet_direct_live_class_balanced_squared_hinge_weight),
        "class_region_recon": float(segnet_direct_live_class_region_recon_weight),
        "rare_class_logit": float(segnet_direct_live_rare_class_logit_weight),
        "target_mass_floor": float(segnet_direct_live_target_mass_floor_weight),
        "target_min_ratio_floor": float(segnet_direct_live_target_min_ratio_floor_weight),
    }
    expected_direct_live_subcontrols = {name: weight > 0.0 for name, weight in direct_live_subcontrol_weights.items()}
    direct_live_seg_dual_suffix_by_control = {
        "class_histogram": "segnet_direct_live_class_histogram",
        "class_balanced_hinge": "segnet_direct_live_class_balanced_hinge",
        "class_balanced_ce": "segnet_direct_live_class_balanced_ce",
        "class_balanced_squared_hinge": ("segnet_direct_live_class_balanced_squared_hinge"),
        "class_region_recon": "segnet_direct_live_class_region_recon",
        "rare_class_logit": "segnet_direct_live_rare_class_logit",
        "target_mass_floor": "segnet_direct_live_target_mass_floor",
        "target_min_ratio_floor": "segnet_direct_live_target_min_ratio_floor",
    }

