def _resolve(path: str | Path, *, base: Path) -> Path:
    p = Path(path).expanduser()
    return p if p.is_absolute() else (base / p).resolve(strict=False)


def _resolve_existing(path: str | Path, *, base: Path) -> Path:
    resolved = _resolve(path, base=base)
    if not resolved.is_file():
        raise CompactRendererMlxSpineRunnerError(f"required file missing: {resolved}")
    return resolved


def _resolve_source_video_path(
    path: str | Path,
    *,
    base: Path,
    upstream_dir: str | Path | None = None,
) -> Path:
    """Resolve bulky source video paths across clean SSD source worktrees."""

    env_override = os.environ.get("PACT_SOURCE_VIDEO_PATH")
    candidates: list[Path] = []
    if env_override:
        candidates.append(Path(env_override).expanduser())
    raw = Path(path).expanduser()
    candidates.append(raw if raw.is_absolute() else (base / raw))
    if upstream_dir is not None and not raw.is_absolute() and raw.parts and raw.parts[0] == "upstream":
        upstream = Path(upstream_dir).expanduser().resolve(strict=False)
        candidates.append(upstream / Path(*raw.parts[1:]))
    if not raw.is_absolute():
        candidates.append(Path("/Users/adpena/Projects/pact") / raw)
    elif raw.name == "0.mkv" and "upstream" in raw.parts and "videos" in raw.parts:
        candidates.append(Path("/Users/adpena/Projects/pact/upstream/videos/0.mkv"))
    for candidate in candidates:
        resolved = candidate.resolve(strict=False)
        if resolved.is_file():
            return resolved
    tried = ", ".join(str(candidate.resolve(strict=False)) for candidate in candidates)
    raise CompactRendererMlxSpineRunnerError(f"source video missing; tried: {tried}")


def _optional_existing(path: Any, *, base: Path) -> Path | None:
    if not isinstance(path, (str, os.PathLike)) or not path:
        return None
    resolved = _resolve(path, base=base)
    return resolved if resolved.is_file() else None


def _load_modelsize_byte_cap_feedback_rows(paths: Sequence[Path]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for raw_path in paths:
        path = Path(raw_path).expanduser().resolve(strict=False)
        payload = _load_json(path)
        for row in _extract_modelsize_byte_cap_feedback_rows(
            payload,
            source_path=path,
        ):
            row.setdefault("source_path", path.as_posix())
            rows.append(row)
    return rows


def _extract_modelsize_byte_cap_feedback_rows(
    payload: Mapping[str, Any],
    *,
    source_path: Path | None = None,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []

    def visit(node: Any) -> None:
        if isinstance(node, Mapping):
            row = _modelsize_byte_cap_feedback_row(node, source_path=source_path)
            if row is not None:
                rows.append(row)
            for key in (
                "row",
                "rows",
                "archive_rows",
                "ladder_rows",
                "receiver_closed_rows",
                "points",
                "selected_candidates",
                "family_rows",
                "trained_archive_byte_oracle",
                "modelsize_byte_cap_feedback_row",
                "modelsize_candidate",
            ):
                child = node.get(key)
                if child is not None:
                    visit(child)
        elif isinstance(node, Sequence) and not isinstance(node, (str, bytes, bytearray)):
            for item in node:
                visit(item)

    visit(payload)
    deduped: list[dict[str, Any]] = []
    seen: dict[tuple[Any, ...], dict[str, Any]] = {}
    for row in rows:
        key = (
            row.get("source_path"),
            row.get("row_id"),
            row.get("candidate_id"),
            row.get("measured_archive_bytes"),
            row.get("nominal_total_payload_bytes"),
            row.get("packet_bytes"),
        )
        existing = seen.get(key)
        if existing is not None:
            for item_key, value in row.items():
                if item_key not in existing or existing[item_key] is None:
                    existing[item_key] = value
            continue
        seen[key] = row
        deduped.append(row)
    return deduped


def _modelsize_byte_cap_feedback_row(
    node: Mapping[str, Any],
    *,
    source_path: Path | None = None,
) -> dict[str, Any] | None:
    measured = _compact_first_present_int(
        node,
        (
            "charged_archive_bytes",
            "measured_archive_bytes",
            "archive_bytes",
            "archive_zip_bytes",
            "candidate_archive_bytes",
        ),
    )
    if measured is None or measured <= 0:
        return None
    candidate = node.get("modelsize_candidate")
    candidate_mapping = candidate if isinstance(candidate, Mapping) else {}
    if not candidate_mapping:
        candidate_mapping = _startup_modelsize_candidate_from_node(
            node,
            source_path=source_path,
        )
    if not _modelsize_byte_cap_scope_matches_candidate(node, candidate_mapping):
        return None
    # Checkpoint exports also carry top-level ``packet_bytes``. That is the
    # realized receiver packet size, not the modelsize ladder's nominal payload
    # estimate, so nested candidate metadata must win when present.
    nominal = _compact_first_present_int(
        candidate_mapping,
        (
            "nominal_total_payload_bytes",
            "total_payload_bytes",
            "estimated_total_payload_bytes",
            "packet_bytes",
        ),
    )
    if nominal is None:
        nominal = _compact_first_present_int(
            node,
            (
                "nominal_total_payload_bytes",
                "total_payload_bytes",
                "estimated_total_payload_bytes",
                "packet_bytes",
            ),
        )
    if nominal is None or nominal <= 0:
        return None
    receiver_closed = _modelsize_byte_cap_row_receiver_closed(
        node,
        source_path=source_path,
    )
    if not receiver_closed:
        return None
    row = {
        "family": (
            node.get("family")
            or candidate_mapping.get("family")
            or ("snerv" if node.get("schema") == "snerv_binary_profile.v1" else None)
        ),
        "row_id": node.get("row_id") or node.get("candidate_id"),
        "candidate_id": node.get("candidate_id") or candidate_mapping.get("candidate_id"),
        "measured_num_pairs": _compact_first_present_int(
            node,
            ("measured_num_pairs", "candidate_num_pairs", "num_pairs"),
        ),
        "measured_archive_bytes": int(measured),
        "measured_payload_bytes": _compact_first_present_int(
            node,
            (
                "measured_payload_bytes",
                "payload_bytes",
                "packet_bytes",
                "snar1_packet_bytes",
            ),
        ),
        "nominal_total_payload_bytes": int(nominal),
        "hard_byte_ceiling": (
            _compact_first_present_int(node, ("hard_byte_ceiling",))
            or _compact_first_present_int(candidate_mapping, ("hard_byte_ceiling",))
        ),
        "decoder_codec": (
            node.get("decoder_codec")
            or node.get("decoder_payload_codec")
            or candidate_mapping.get("decoder_codec")
            or candidate_mapping.get("decoder_payload_codec")
        ),
        "source_bound_controls": (_byte_cap_candidate_match_controls(candidate_mapping) if candidate_mapping else {}),
        "receiver_closed": True,
        "receiver_closed_status": receiver_closed.get("status"),
        "receiver_proof_path": (
            receiver_closed.get("proof_path") or node.get("receiver_proof_path") or node.get("proof_path")
        ),
        "report_path": node.get("report_path"),
        "artifact_report_path": node.get("artifact_report_path") or node.get("report_path"),
        "packet_path": node.get("packet_path") or node.get("payload_path"),
        "packet_sha256": (node.get("packet_sha256") or node.get("payload_sha256") or node.get("snar1_packet_sha256")),
        "archive_path": (
            node.get("archive_path")
            or node.get("candidate_archive_path")
            or node.get("source_archive_path")
            or node.get("input_path")
        ),
        "archive_sha256": node.get("archive_sha256") or node.get("input_sha256"),
    }
    for key in (
        "receiver_contract_satisfied",
        "receiver_proof_passed",
        "runtime_consumption_proof_ready",
        "runtime_consumption_proof_passed",
    ):
        if node.get(key) is not None:
            row[key] = bool(node.get(key))
    official_state_slice = _modelsize_byte_cap_official_state_slice(
        node,
        source_path=source_path,
    )
    row.update(official_state_slice)
    for key in (
        "archive_minus_nominal_bytes",
        "archive_to_nominal_ratio",
        "calibrated_archive_overrun_bytes",
        "required_nominal_payload_bytes_max",
        "hard_byte_ceiling_measurement_bypass_enabled",
        "hard_byte_ceiling_checked_after_export",
    ):
        if key in node:
            row[key] = node.get(key)
    return {key: value for key, value in row.items() if value is not None}


def _modelsize_byte_cap_official_state_slice(
    node: Mapping[str, Any],
    *,
    source_path: Path | None = None,
) -> dict[str, Any]:
    """Expose exported SNeRV official checkpoint slices as real runner controls."""

    binding = node.get("official_checkpoint_export_binding")
    sources: list[Mapping[str, Any]] = [node]
    if isinstance(binding, Mapping):
        sources.append(binding)
    for source in sources:
        raw_path = source.get("official_trained_checkpoint_state_dict_slice_path")
        if not raw_path:
            continue
        base = (
            source_path.parent
            if source_path is not None and not Path(str(raw_path)).expanduser().is_absolute()
            else Path.cwd()
        )
        path = _resolve(str(raw_path), base=base)
        out: dict[str, Any] = {
            "snerv_official_trained_checkpoint_state_dict_slice_path": path.as_posix(),
            "snerv_official_trained_checkpoint_state_dict_slice_present": bool(
                source.get("official_trained_checkpoint_state_dict_slice_present")
            ),
            "snerv_official_trained_checkpoint_state_dict_slice_file_present": path.is_file(),
            "snerv_official_trained_checkpoint_state_dict_slice_runner_arg": source.get(
                "official_trained_checkpoint_state_dict_slice_runner_arg"
            ),
        }
        if path.is_file():
            out["snerv_official_trained_checkpoint_state_dict_path"] = path.as_posix()
        for source_key, row_key in (
            (
                "official_trained_checkpoint_state_dict_slice_bytes",
                "snerv_official_trained_checkpoint_state_dict_slice_bytes",
            ),
            (
                "official_trained_checkpoint_state_dict_slice_sha256",
                "snerv_official_trained_checkpoint_state_dict_slice_sha256",
            ),
            (
                "official_trained_checkpoint_state_dict_slice_member_count",
                "snerv_official_trained_checkpoint_state_dict_slice_member_count",
            ),
        ):
            if source.get(source_key) is not None:
                out[row_key] = source.get(source_key)
        if isinstance(
            source.get("official_trained_checkpoint_state_dict_slice_member_names"),
            Sequence,
        ) and not isinstance(
            source.get("official_trained_checkpoint_state_dict_slice_member_names"),
            (str, bytes, bytearray),
        ):
            out["snerv_official_trained_checkpoint_state_dict_slice_member_names"] = list(
                source.get("official_trained_checkpoint_state_dict_slice_member_names") or []
            )
        return out
    return {}


def _modelsize_byte_cap_scope_matches_candidate(
    node: Mapping[str, Any],
    candidate: Mapping[str, Any],
) -> bool:
    if not candidate:
        return True
    measured_pairs = _compact_first_present_int(
        node,
        ("measured_num_pairs", "candidate_num_pairs", "num_pairs"),
    )
    metadata = node.get("snar1_metadata")
    if measured_pairs is None and isinstance(metadata, Mapping):
        measured_pairs = _compact_first_present_int(metadata, ("n_pairs", "num_pairs"))
    candidate_pairs = _compact_first_present_int(candidate, ("num_pairs",))
    return not (
        measured_pairs is not None and candidate_pairs is not None and int(measured_pairs) != int(candidate_pairs)
    )


def _startup_modelsize_candidate_from_node(
    node: Mapping[str, Any],
    *,
    source_path: Path | None = None,
) -> dict[str, Any]:
    path_value = node.get("startup_json_path")
    startup_paths: list[Path] = []
    if path_value:
        startup_paths.append(Path(str(path_value)).expanduser().resolve(strict=False))
    for artifact_path in _modelsize_byte_cap_row_artifact_paths(
        node,
        source_path=source_path,
    ):
        startup_paths.extend(
            candidate for candidate in _startup_paths_from_artifact(artifact_path) if candidate not in startup_paths
        )
    for path in startup_paths:
        try:
            if not path.is_file():
                continue
            startup = _load_json(path)
        except (OSError, ValueError, json.JSONDecodeError, CompactRendererMlxSpineRunnerError):
            continue
        candidate = startup.get("modelsize_candidate")
        if isinstance(candidate, Mapping):
            return dict(candidate)
    return {}


def _modelsize_byte_cap_row_receiver_closed(
    node: Mapping[str, Any],
    *,
    source_path: Path | None = None,
) -> dict[str, Any]:
    inline_runtime_ready = _truthy_any(
        node,
        (
            "receiver_closed",
            "receiver_proof_ready",
            "receiver_proof_passed",
            "runtime_consumption_proof_ready",
            "receiver_archive_replay_verified",
            "byte_closed_receiver_proof",
        ),
    )
    contract_ok = node.get("receiver_contract_satisfied") is not False
    if inline_runtime_ready and contract_ok:
        return {"status": "inline_receiver_closed"}
    for proof_path in _modelsize_byte_cap_receiver_proof_paths(
        node,
        source_path=source_path,
    ):
        try:
            proof = _load_json(proof_path)
        except (OSError, ValueError, json.JSONDecodeError, CompactRendererMlxSpineRunnerError):
            continue
        runtime_ready = bool(
            proof.get("runtime_consumption_proof_ready")
            or proof.get("runtime_consumption_proof_passed")
            or proof.get("receiver_proof_ready")
            or proof.get("receiver_proof_passed")
        )
        if not (runtime_ready and proof.get("receiver_contract_satisfied") is True):
            continue
        proof_archive_sha = str(proof.get("archive_sha256") or "").strip().lower()
        node_archive_sha = str(node.get("input_sha256") or node.get("archive_sha256") or "").strip().lower()
        if proof_archive_sha and node_archive_sha and proof_archive_sha != node_archive_sha:
            continue
        proof_archive_bytes = _compact_first_present_int(
            proof,
            ("archive_bytes", "measured_archive_bytes", "archive_zip_bytes"),
        )
        node_archive_bytes = _compact_first_present_int(
            node,
            (
                "charged_archive_bytes",
                "measured_archive_bytes",
                "archive_bytes",
                "archive_zip_bytes",
                "candidate_archive_bytes",
            ),
        )
        if (
            proof_archive_bytes is not None
            and node_archive_bytes is not None
            and int(proof_archive_bytes) != int(node_archive_bytes)
        ):
            continue
        return {
            "status": "associated_receiver_proof",
            "proof_path": proof_path.as_posix(),
        }
    return {}


def _modelsize_byte_cap_receiver_proof_paths(
    node: Mapping[str, Any],
    *,
    source_path: Path | None = None,
) -> list[Path]:
    paths: list[Path] = []
    for artifact_path in _modelsize_byte_cap_row_artifact_paths(
        node,
        source_path=source_path,
    ):
        for parent in _self_and_parents(artifact_path):
            for name in (
                "snerv_inverse_steg_receiver_proof.json",
                "hi_nerv_mlx_receiver_proof.json",
            ):
                for candidate in (parent / name, parent / "receiver_proof" / name):
                    if candidate.is_file() and candidate not in paths:
                        paths.append(candidate)
    return paths


def _modelsize_byte_cap_row_artifact_paths(
    node: Mapping[str, Any],
    *,
    source_path: Path | None = None,
) -> list[Path]:
    out: list[Path] = []
    if source_path is not None:
        out.append(Path(source_path).expanduser().resolve(strict=False))
    for key in (
        "input_path",
        "archive_path",
        "source_archive_path",
        "candidate_archive_path",
        "proof_path",
        "receiver_proof_path",
        "report_path",
    ):
        value = node.get(key)
        if not value:
            continue
        candidate = Path(str(value)).expanduser().resolve(strict=False)
        if candidate not in out:
            out.append(candidate)
    return out


def _startup_paths_from_artifact(path: Path) -> list[Path]:
    out: list[Path] = []
    for parent in _self_and_parents(path):
        candidate = parent / "compact_renderer_mlx_spine_runner_startup.json"
        if candidate.is_file() and candidate not in out:
            out.append(candidate)
    return out


def _self_and_parents(path: Path) -> list[Path]:
    base = path if path.is_dir() else path.parent
    return [base, *list(base.parents)]


def _load_json(path: Path) -> dict[str, Any]:
    payload = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(payload, dict):
        raise CompactRendererMlxSpineRunnerError(f"JSON root must be object: {path}")
    return payload


def _write_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def _snerv_scorer_loop_progress_callback(progress_path: Path):
    progress_path.parent.mkdir(parents=True, exist_ok=True)

    def callback(row: Any) -> None:
        row_payload = row.as_jsonable() if hasattr(row, "as_jsonable") else dict(row)
        payload = {
            "schema": "snerv_scorer_loop_decoder_qat_progress.v1",
            "captured_at_utc": datetime.now(UTC).isoformat().replace("+00:00", "Z"),
            "axis_tag": "[macOS-CPU advisory]",
            "score_claim": False,
            "promotion_eligible": False,
            "rank_or_kill_eligible": False,
            "ready_for_exact_eval_dispatch": False,
            "row": row_payload,
        }
        with progress_path.open("a", encoding="utf-8") as handle:
            handle.write(json.dumps(payload, sort_keys=True) + "\n")
            handle.flush()

    return callback


def _has_disallowed_existing_output_artifacts(
    output_dir: Path,
    *,
    allow_startup_marker_only: bool = False,
) -> bool:
    """Return whether output_dir contains artifacts that should block a launch."""

    if not output_dir.exists():
        return False
    entries = list(output_dir.iterdir())
    if not entries:
        return False
    if allow_startup_marker_only:
        for entry in entries:
            if entry.is_file() and entry.name == COMPACT_FAMILY_STARTUP_MARKER_FILENAME:
                continue
            if entry.is_dir() and not any(child.is_file() or child.is_symlink() for child in entry.rglob("*")):
                continue
            return True
        return False
    return True


def _sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as fh:
        for chunk in iter(lambda: fh.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def _file_record(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {"path": path.as_posix(), "exists": False}
    return {
        "path": path.as_posix(),
        "exists": True,
        "bytes": path.stat().st_size,
        "sha256": _sha256_file(path),
    }


def _dedupe(values: list[Any]) -> list[Any]:
    seen: set[str] = set()
    out: list[Any] = []
    for value in values:
        key = json.dumps(value, sort_keys=True, default=str)
        if key in seen:
            continue
        seen.add(key)
        out.append(value)
    return out


def _nested(mapping: Mapping[str, Any], *keys: str) -> Any:
    current: Any = mapping
    for key in keys:
        if not isinstance(current, Mapping):
            return None
        current = current.get(key)
    return current


def _stamp() -> str:
    return datetime.now(UTC).strftime("%Y%m%dT%H%M%SZ")


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (
        OSError,
        json.JSONDecodeError,
        CompactRendererMlxSpineRunnerError,
    ) as exc:
        print(f"run_compact_renderer_mlx_spine_runner failed: {exc}", file=sys.stderr)
        raise SystemExit(2) from exc
